package main

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
	F3 int
}

type Tuple2 struct {
	F0 int
	F1 int
}

type edge struct {
	to      int
	minutes int
	energy  int
}

type heapItem struct {
	d  int
	id int
}

type minHeap []heapItem

func (h *minHeap) push(x heapItem) {
	*h = append(*h, x)
	s := *h
	i := len(s) - 1
	for i > 0 {
		p := (i - 1) >> 1
		if s[p].d <= s[i].d {
			break
		}
		s[p], s[i] = s[i], s[p]
		i = p
	}
}

func (h *minHeap) pop() heapItem {
	s := *h
	res := s[0]
	last := len(s) - 1
	s[0] = s[last]
	*h = s[:last]
	s = *h
	n := len(s)
	i := 0
	for {
		l := 2*i + 1
		if l >= n {
			break
		}
		c := l
		if r := l + 1; r < n && s[r].d < s[l].d {
			c = r
		}
		if s[i].d <= s[c].d {
			break
		}
		s[i], s[c] = s[c], s[i]
		i = c
	}
	return res
}

func FastestDelivery(n int, roads []Tuple1, stations []int, capacity int, swap_time int, max_swaps int, s int, t int) *Tuple2 {
	if s == t {
		return &Tuple2{F0: 0, F1: 0}
	}

	adj := make([][]edge, n)
	for _, r := range roads {
		adj[r.F0] = append(adj[r.F0], edge{
			to:      r.F1,
			minutes: r.F2,
			energy:  r.F3,
		})
	}

	uniqueStations := make([]int, 0, len(stations))
	isStation := make([]bool, n)
	for _, u := range stations {
		if !isStation[u] {
			isStation[u] = true
			uniqueStations = append(uniqueStations, u)
		}
	}

	const inf = 1 << 60
	stride := capacity + 1
	totalStates := n * stride

	dist := make([]int, totalStates)
	nextDist := make([]int, totalStates)
	for i := range dist {
		dist[i] = inf
	}

	pq := make(minHeap, 0, totalStates)
	startID := s*stride + capacity
	dist[startID] = 0
	pq.push(heapItem{d: 0, id: startID})

	bestMin := inf
	bestSwaps := -1

	for k := 0; k <= max_swaps; k++ {
		if len(pq) == 0 {
			break
		}

		for len(pq) > 0 {
			cur := pq.pop()
			if cur.d != dist[cur.id] {
				continue
			}
			u := cur.id / stride
			c := cur.id % stride
			for _, e := range adj[u] {
				if c < e.energy {
					continue
				}
				nc := c - e.energy
				if nc > capacity {
					nc = capacity
				}
				nid := e.to*stride + nc
				nd := cur.d + e.minutes
				if nd < dist[nid] {
					dist[nid] = nd
					pq.push(heapItem{d: nd, id: nid})
				}
			}
		}

		tBase := t * stride
		for c := 0; c <= capacity; c++ {
			if dist[tBase+c] < bestMin {
				bestMin = dist[tBase+c]
				bestSwaps = k
			}
		}

		if k == max_swaps {
			break
		}

		for i := range nextDist {
			nextDist[i] = inf
		}
		for _, u := range uniqueStations {
			uBase := u * stride
			minAtU := inf
			for c := 0; c <= capacity; c++ {
				if dist[uBase+c] < minAtU {
					minAtU = dist[uBase+c]
				}
			}
			if minAtU < inf {
				nid := uBase + capacity
				nd := minAtU + swap_time
				nextDist[nid] = nd
				pq.push(heapItem{d: nd, id: nid})
			}
		}
		dist, nextDist = nextDist, dist
	}

	if bestSwaps == -1 {
		return nil
	}
	return &Tuple2{F0: bestMin, F1: bestSwaps}
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2, long f3) {}

    public record Tuple2(long f0, long f1) {}

    private record Edge(int to, long minutes, int energy) {}

    private record State(long dist, int swaps, int u, int charge) implements Comparable<State> {
        @Override
        public int compareTo(State other) {
            int cmp = Long.compare(this.dist, other.dist);
            return cmp != 0 ? cmp : Integer.compare(this.swaps, other.swaps);
        }
    }

    public static Tuple2 fastestDelivery(long n, List<Tuple1> roads, List<Long> stations, long capacity, long swap_time, long max_swaps, long s, long t) {
        int numNodes = (int) n;
        int cap = (int) capacity;
        int maxSwaps = (int) max_swaps;
        int start = (int) s;
        int target = (int) t;

        if (start == target) {
            return new Tuple2(0L, 0L);
        }

        @SuppressWarnings("unchecked")
        List<Edge>[] adj = new ArrayList[numNodes];
        for (int i = 0; i < numNodes; i++) {
            adj[i] = new ArrayList<>();
        }
        for (Tuple1 r : roads) {
            int u = (int) r.f0();
            int v = (int) r.f1();
            long minutes = r.f2();
            int energy = (int) r.f3();
            adj[u].add(new Edge(v, minutes, energy));
        }

        boolean[] isStation = new boolean[numNodes];
        for (long st : stations) {
            isStation[(int) st] = true;
        }

        int capStates = cap + 1;
        int swapStates = maxSwaps + 1;
        long[][][] dist = new long[numNodes][capStates][swapStates];
        for (int i = 0; i < numNodes; i++) {
            for (int c = 0; c < capStates; c++) {
                Arrays.fill(dist[i][c], Long.MAX_VALUE);
            }
        }

        PriorityQueue<State> pq = new PriorityQueue<>();
        dist[start][cap][0] = 0L;
        pq.add(new State(0L, 0, start, cap));

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            long d = cur.dist();
            int k = cur.swaps();
            int u = cur.u();
            int c = cur.charge();

            if (d > dist[u][c][k]) {
                continue;
            }

            if (u == target) {
                return new Tuple2(d, k);
            }

            if (isStation[u] && k < maxSwaps && c < cap) {
                long nd = d + swap_time;
                if (nd < dist[u][cap][k + 1]) {
                    dist[u][cap][k + 1] = nd;
                    pq.add(new State(nd, k + 1, u, cap));
                }
            }

            List<Edge> edges = adj[u];
            for (int i = 0, size = edges.size(); i < size; i++) {
                Edge e = edges.get(i);
                if (c >= e.energy()) {
                    int nc = Math.min(cap, c - e.energy());
                    long nd = d + e.minutes();
                    if (nd < dist[e.to()][nc][k]) {
                        dist[e.to()][nc][k] = nd;
                        pq.add(new State(nd, k, e.to(), nc));
                    }
                }
            }
        }

        return null;
    }
}

#include <algorithm>
#include <limits>
#include <optional>
#include <queue>
#include <tuple>
#include <vector>

std::optional<std::tuple<long long, long long>> fastest_delivery(
    long long n,
    const std::vector<std::tuple<long long, long long, long long, long long>>& roads,
    const std::vector<long long>& stations,
    long long capacity,
    long long swap_time,
    long long max_swaps,
    long long s,
    long long t) {
    if (s == t) {
        return std::make_tuple(0LL, 0LL);
    }

    struct Edge {
        int to;
        long long minutes;
        long long energy;
    };

    std::vector<std::vector<Edge>> adj(n);
    for (const auto& [u, v, minutes, energy] : roads) {
        adj[u].push_back(Edge{static_cast<int>(v), minutes, energy});
    }

    std::vector<bool> is_station(n, false);
    for (long long st : stations) {
        if (st >= 0 && st < n) {
            is_station[st] = true;
        }
    }

    const long long INF = std::numeric_limits<long long>::max() / 4;
    const int cap = static_cast<int>(capacity);
    const int stride = cap + 1;
    const int num_states = static_cast<int>(n) * stride;

    std::vector<long long> dist(num_states, INF);
    dist[static_cast<int>(s) * stride + cap] = 0;

    long long best_minutes = INF;
    long long best_swaps = -1;

    using PQE = std::pair<long long, int>;
    std::priority_queue<PQE, std::vector<PQE>, std::greater<PQE>> pq;

    for (long long swaps = 0; swaps <= max_swaps; ++swaps) {
        for (int state = 0; state < num_states; ++state) {
            if (dist[state] < INF) {
                pq.emplace(dist[state], state);
            }
        }

        while (!pq.empty()) {
            auto [d, state] = pq.top();
            pq.pop();

            if (d > dist[state]) {
                continue;
            }

            int u = state / stride;
            int c = state % stride;

            for (const auto& edge : adj[u]) {
                if (c >= edge.energy) {
                    int next_c = static_cast<int>(std::min(capacity, static_cast<long long>(c) - edge.energy));
                    int next_state = edge.to * stride + next_c;
                    long long next_d = d + edge.minutes;
                    if (next_d < dist[next_state]) {
                        dist[next_state] = next_d;
                        pq.emplace(next_d, next_state);
                    }
                }
            }
        }

        long long layer_best_t = INF;
        int t_base = static_cast<int>(t) * stride;
        for (int c = 0; c <= cap; ++c) {
            layer_best_t = std::min(layer_best_t, dist[t_base + c]);
        }

        if (layer_best_t < best_minutes) {
            best_minutes = layer_best_t;
            best_swaps = swaps;
        }

        if (swaps < max_swaps) {
            std::vector<long long> next_dist(num_states, INF);
            for (int u = 0; u < n; ++u) {
                if (!is_station[u]) {
                    continue;
                }
                int u_base = u * stride;
                long long min_u = INF;
                for (int c = 0; c <= cap; ++c) {
                    min_u = std::min(min_u, dist[u_base + c]);
                }
                if (min_u < INF) {
                    next_dist[u_base + cap] = min_u + swap_time;
                }
            }
            dist = std::move(next_dist);
        }
    }

    if (best_minutes == INF) {
        return std::nullopt;
    }
    return std::make_tuple(best_minutes, best_swaps);
}

export function fastestDelivery(
  n: number,
  roads: [number, number, number, number][],
  stations: number[],
  capacity: number,
  swap_time: number,
  max_swaps: number,
  s: number,
  t: number
): [number, number] | null {
  if (s === t) {
    return [0, 0];
  }

  const m = roads.length;
  const head = new Int32Array(n).fill(-1);
  const to = new Int32Array(m);
  const roadMinutes = new Float64Array(m);
  const roadEnergy = new Int32Array(m);
  const next = new Int32Array(m);

  for (let i = 0; i < m; i++) {
    const [u, v, mins, eng] = roads[i];
    to[i] = v;
    roadMinutes[i] = mins;
    roadEnergy[i] = eng;
    next[i] = head[u];
    head[u] = i;
  }

  const uniqueStations: number[] = [];
  const isStation = new Uint8Array(n);
  for (let i = 0; i < stations.length; i++) {
    const u = stations[i];
    if (!isStation[u]) {
      isStation[u] = 1;
      uniqueStations.push(u);
    }
  }

  const C = capacity + 1;
  const numStates = n * C;
  let dist = new Float64Array(numStates).fill(Infinity);
  let nextDist = new Float64Array(numStates).fill(Infinity);

  let heapCap = 65536;
  let heapDist = new Float64Array(heapCap);
  let heapState = new Int32Array(heapCap);
  let heapSize = 0;

  function push(d: number, state: number): void {
    if (heapSize === heapCap) {
      heapCap *= 2;
      const newDist = new Float64Array(heapCap);
      newDist.set(heapDist);
      heapDist = newDist;
      const newState = new Int32Array(heapCap);
      newState.set(heapState);
      heapState = newState;
    }
    let idx = heapSize++;
    while (idx > 0) {
      const parent = (idx - 1) >> 1;
      if (heapDist[parent] <= d) break;
      heapDist[idx] = heapDist[parent];
      heapState[idx] = heapState[parent];
      idx = parent;
    }
    heapDist[idx] = d;
    heapState[idx] = state;
  }

  dist[s * C + capacity] = 0;
  push(0, s * C + capacity);

  let bestTime = Infinity;
  let bestSwaps = -1;

  for (let swaps = 0; swaps <= max_swaps; swaps++) {
    while (heapSize > 0) {
      const d = heapDist[0];
      const state = heapState[0];
      heapSize--;
      if (heapSize > 0) {
        const lastD = heapDist[heapSize];
        const lastS = heapState[heapSize];
        let idx = 0;
        const half = heapSize >> 1;
        while (idx < half) {
          let child = (idx << 1) + 1;
          const right = child + 1;
          if (right < heapSize && heapDist[right] < heapDist[child]) {
            child = right;
          }
          if (lastD <= heapDist[child]) break;
          heapDist[idx] = heapDist[child];
          heapState[idx] = heapState[child];
          idx = child;
        }
        heapDist[idx] = lastD;
        heapState[idx] = lastS;
      }

      if (d > dist[state]) continue;
      if (d >= bestTime) break;

      const charge = state % C;
      const u = (state - charge) / C;

      for (let e = head[u]; e !== -1; e = next[e]) {
        const eng = roadEnergy[e];
        if (charge < eng) continue;
        let newCharge = charge - eng;
        if (newCharge > capacity) newCharge = capacity;
        const nextState = to[e] * C + newCharge;
        const nd = d + roadMinutes[e];
        if (nd < dist[nextState] && nd < bestTime) {
          dist[nextState] = nd;
          push(nd, nextState);
        }
      }
    }

    heapSize = 0;

    const tBase = t * C;
    for (let c = 0; c < C; c++) {
      if (dist[tBase + c] < bestTime) {
        bestTime = dist[tBase + c];
        bestSwaps = swaps;
      }
    }

    if (swaps < max_swaps && uniqueStations.length > 0) {
      nextDist.fill(Infinity);
      for (let i = 0; i < uniqueStations.length; i++) {
        const u = uniqueStations[i];
        const base = u * C;
        let minD = Infinity;
        for (let c = 0; c < C; c++) {
          if (dist[base + c] < minD) {
            minD = dist[base + c];
          }
        }
        const swappedTime = minD + swap_time;
        if (swappedTime < bestTime) {
          const fullState = base + capacity;
          nextDist[fullState] = swappedTime;
          push(swappedTime, fullState);
        }
      }
      const tmp = dist;
      dist = nextDist;
      nextDist = tmp;
    } else {
      break;
    }
  }

  return bestTime === Infinity ? null : [bestTime, bestSwaps];
}

package main

import (
	"errors"
	"math"
)

type Tuple1 struct {
	F0 int
	F1 int
	F2 bool
}

func BestContext(messages []Tuple1, budget int, max_gap int, bonus int) (*int, error) {
	if budget < 0 || max_gap < 0 {
		return nil, errors.New("budget and max_gap must be non-negative")
	}

	n := len(messages)
	if n == 0 {
		zero := 0
		return &zero, nil
	}

	maxG := max_gap
	if maxG > n {
		maxG = n
	}

	stride := maxG + 1
	size := (budget + 1) * stride
	const negInf = math.MinInt / 4

	dp := make([]int, size)
	nextDP := make([]int, size)
	for idx := range dp {
		dp[idx] = negInf
	}

	// Initialize for message 0
	m0 := messages[0]
	len0, val0, pin0 := m0.F0, m0.F1, m0.F2
	if len0 <= budget {
		dp[len0*stride+0] = val0
	}
	if !pin0 && 1 <= maxG {
		if 0 > dp[0*stride+1] {
			dp[0*stride+1] = 0
		}
	}

	// Transitions for messages 1 .. n-1
	for i := 1; i < n; i++ {
		for idx := range nextDP {
			nextDP[idx] = negInf
		}

		msg := messages[i]
		length, value, pinned := msg.F0, msg.F1, msg.F2

		for b := 0; b <= budget; b++ {
			base := b * stride
			for g := 0; g <= maxG; g++ {
				cur := dp[base+g]
				if cur == negInf {
					continue
				}

				// Option 1: Keep message i
				if b+length <= budget {
					score := cur + value
					if g == 0 {
						score += bonus
					}
					keepIdx := (b + length) * stride
					if score > nextDP[keepIdx] {
						nextDP[keepIdx] = score
					}
				}

				// Option 2: Drop message i
				if !pinned && g+1 <= maxG {
					dropIdx := base + g + 1
					if cur > nextDP[dropIdx] {
						nextDP[dropIdx] = cur
					}
				}
			}
		}

		dp, nextDP = nextDP, dp
	}

	best := negInf
	for _, val := range dp {
		if val > best {
			best = val
		}
	}

	if best == negInf {
		return nil, nil
	}
	return &best, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, boolean f2) {}

    private static final long NEG_INF = Long.MIN_VALUE / 4;

    public static Long bestContext(List<Tuple1> messages, long budget, long max_gap, long bonus) {
        if (budget < 0 || max_gap < 0) {
            throw new IllegalArgumentException("budget and max_gap must be non-negative");
        }
        if (messages == null) {
            throw new IllegalArgumentException("messages must not be null");
        }

        int n = messages.size();
        if (n == 0) {
            return 0L;
        }

        long sumSelectable = 0;
        for (Tuple1 msg : messages) {
            long len = msg.f0();
            if (len <= budget) {
                if (sumSelectable <= budget - len) {
                    sumSelectable += len;
                } else {
                    sumSelectable = budget;
                }
            }
        }

        int effectiveBudget = (int) Math.min(budget, sumSelectable);
        int maxGap = (int) Math.min(max_gap, n);

        long[] kept = new long[effectiveBudget + 1];
        long[][] dropped = new long[maxGap + 1][effectiveBudget + 1];
        long[] nextKept = new long[effectiveBudget + 1];
        long[][] nextDropped = new long[maxGap + 1][effectiveBudget + 1];

        Arrays.fill(kept, NEG_INF);
        for (int g = 0; g <= maxGap; g++) {
            Arrays.fill(dropped[g], NEG_INF);
        }
        dropped[0][0] = 0L;

        for (Tuple1 msg : messages) {
            long len = msg.f0();
            long val = msg.f1();
            boolean pinned = msg.f2();

            Arrays.fill(nextKept, NEG_INF);
            for (int g = 0; g <= maxGap; g++) {
                Arrays.fill(nextDropped[g], NEG_INF);
            }

            if (len <= effectiveBudget) {
                int l = (int) len;
                int limit = effectiveBudget - l;
                for (int b = 0; b <= limit; b++) {
                    long prev = kept[b];
                    if (prev != NEG_INF) {
                        nextKept[b + l] = prev + val + bonus;
                    }
                }
                for (int g = 0; g <= maxGap; g++) {
                    long[] dg = dropped[g];
                    for (int b = 0; b <= limit; b++) {
                        long prev = dg[b];
                        if (prev != NEG_INF) {
                            long cand = prev + val;
                            if (cand > nextKept[b + l]) {
                                nextKept[b + l] = cand;
                            }
                        }
                    }
                }
            }

            if (!pinned && maxGap >= 1) {
                long[] nd1 = nextDropped[1];
                long[] d0 = dropped[0];
                for (int b = 0; b <= effectiveBudget; b++) {
                    nd1[b] = Math.max(kept[b], d0[b]);
                }
                for (int g = 1; g < maxGap; g++) {
                    System.arraycopy(dropped[g], 0, nextDropped[g + 1], 0, effectiveBudget + 1);
                }
            }

            long[] tmpKept = kept;
            kept = nextKept;
            nextKept = tmpKept;

            long[][] tmpDropped = dropped;
            dropped = nextDropped;
            nextDropped = tmpDropped;
        }

        long ans = NEG_INF;
        for (int b = 0; b <= effectiveBudget; b++) {
            if (kept[b] > ans) {
                ans = kept[b];
            }
        }
        for (int g = 0; g <= maxGap; g++) {
            long[] dg = dropped[g];
            for (int b = 0; b <= effectiveBudget; b++) {
                if (dg[b] > ans) {
                    ans = dg[b];
                }
            }
        }

        return ans == NEG_INF ? null : ans;
    }
}

#include <algorithm>
#include <limits>
#include <optional>
#include <stdexcept>
#include <tuple>
#include <vector>

std::optional<long long> best_context(
    const std::vector<std::tuple<long long, long long, bool>>& messages,
    long long budget,
    long long max_gap,
    long long bonus) {
    if (budget < 0 || max_gap < 0) {
        throw std::invalid_argument("budget and max_gap must be non-negative");
    }

    const std::size_t n = messages.size();
    if (n == 0) {
        return 0LL;
    }

    const std::size_t cap_gap = static_cast<std::size_t>(
        std::min<long long>(max_gap, static_cast<long long>(n)));

    long long sum_keepable_lengths = 0;
    for (const auto& [len, val, pinned] : messages) {
        if (pinned && len > budget) {
            return std::nullopt;
        }
        if (len <= budget) {
            if (budget - sum_keepable_lengths <= len) {
                sum_keepable_lengths = budget;
            } else {
                sum_keepable_lengths += len;
            }
        }
    }

    const std::size_t cap_budget = static_cast<std::size_t>(
        std::min<long long>(budget, sum_keepable_lengths));

    constexpr long long NEG_INF = std::numeric_limits<long long>::lowest() / 4;
    const std::size_t stride = cap_budget + 1;
    const std::size_t state_count = (cap_gap + 1) * stride;

    std::vector<long long> dp(state_count, NEG_INF);
    std::vector<long long> next_dp(state_count, NEG_INF);
    dp[0] = 0;

    for (std::size_t i = 0; i < n; ++i) {
        std::fill(next_dp.begin(), next_dp.end(), NEG_INF);
        const auto [len, val, pinned] = messages[i];

        for (std::size_t g = 0; g <= cap_gap; ++g) {
            const std::size_t row_offset = g * stride;
            const long long keep_gain = val + ((i > 0 && g == 0) ? bonus : 0LL);

            for (std::size_t b = 0; b <= cap_budget; ++b) {
                const long long cur = dp[row_offset + b];
                if (cur == NEG_INF) {
                    continue;
                }

                // Option 1: Keep message i
                if (len <= static_cast<long long>(cap_budget - b)) {
                    const std::size_t nb = b + static_cast<std::size_t>(len);
                    next_dp[nb] = std::max(next_dp[nb], cur + keep_gain);
                }

                // Option 2: Drop message i
                if (!pinned && g + 1 <= cap_gap) {
                    const std::size_t next_idx = (g + 1) * stride + b;
                    next_dp[next_idx] = std::max(next_dp[next_idx], cur);
                }
            }
        }

        dp.swap(next_dp);
    }

    long long ans = NEG_INF;
    for (long long score : dp) {
        ans = std::max(ans, score);
    }

    if (ans == NEG_INF) {
        return std::nullopt;
    }
    return ans;
}

export function bestContext(
  messages: [number, number, boolean][],
  budget: number,
  max_gap: number,
  bonus: number
): number | null {
  if (budget < 0 || max_gap < 0) {
    throw new Error("budget and max_gap must be non-negative");
  }

  const n = messages.length;
  if (n === 0) {
    return 0;
  }

  let totalLength = 0;
  for (let i = 0; i < n; i++) {
    totalLength += messages[i][0];
  }

  const maxB = Math.min(budget, totalLength);
  const maxG = Math.min(max_gap, n);
  const stride = maxB + 1;
  const size = (maxG + 1) * stride;

  let dp = new Float64Array(size);
  let nextDp = new Float64Array(size);
  dp.fill(-Infinity);

  // Process index 0 separately (keeping index 0 cannot earn an adjacency bonus)
  const [len0, val0, pinned0] = messages[0];
  if (len0 <= maxB) {
    dp[len0] = val0; // d = 0, budget = len0
  }
  if (!pinned0 && 1 <= maxG) {
    dp[stride] = 0; // d = 1, budget = 0
  }

  for (let i = 1; i < n; i++) {
    const [len, val, pinned] = messages[i];
    nextDp.fill(-Infinity);

    const limitD = Math.min(i, maxG);
    for (let d = 0; d <= limitD; d++) {
      const rowOffset = d * stride;
      const keepGain = d === 0 ? val + bonus : val;
      const canDrop = !pinned && d + 1 <= maxG;
      const nextDropOffset = (d + 1) * stride;

      for (let b = 0; b <= maxB; b++) {
        const cur = dp[rowOffset + b];
        if (cur === -Infinity) continue;

        // Option 1: Keep message i
        const nb = b + len;
        if (nb <= maxB) {
          const cand = cur + keepGain;
          if (cand > nextDp[nb]) {
            nextDp[nb] = cand;
          }
        }

        // Option 2: Drop message i
        if (canDrop) {
          const dropIdx = nextDropOffset + b;
          if (cur > nextDp[dropIdx]) {
            nextDp[dropIdx] = cur;
          }
        }
      }
    }

    const tmp = dp;
    dp = nextDp;
    nextDp = tmp;
  }

  let best = -Infinity;
  for (let idx = 0; idx < size; idx++) {
    if (dp[idx] > best) {
      best = dp[idx];
    }
  }

  if (best === -Infinity) {
    return null;
  }
  return best === 0 ? 0 : best;
}

package main

func MinPruningCost(parent []int, demand []int, cap []int, cut_cost []int, critical []bool, root_cap int, penalty int) *int {
	const inf int = 1 << 60
	n := len(parent)

	children := make([][]int, n)
	for v := 1; v < n; v++ {
		p := parent[v]
		children[p] = append(children[p], v)
	}

	// Build BFS order from root 0 so reverse order is a valid post-order.
	order := make([]int, 0, n)
	order = append(order, 0)
	for i := 0; i < len(order); i++ {
		u := order[i]
		for _, v := range children[u] {
			order = append(order, v)
		}
	}

	subDemand := make([]int, n)
	hasCrit := make([]bool, n)
	dp := make([][]int, n)

	for i := n - 1; i >= 0; i-- {
		u := order[i]
		subDemand[u] = demand[u]
		hasCrit[u] = critical[u]
		for _, v := range children[u] {
			subDemand[u] += subDemand[v]
			if hasCrit[v] {
				hasCrit[u] = true
			}
		}

		uCap := root_cap
		if u > 0 {
			uCap = cap[u]
		}

		if demand[u] > uCap {
			continue
		}

		cur := make([]int, demand[u]+1)
		for d := range cur {
			cur[d] = inf
		}
		cur[demand[u]] = 0

		for _, v := range children[u] {
			childMax := 0
			if len(dp[v]) > 0 {
				childMax = len(dp[v]) - 1
			}
			newMax := len(cur) - 1 + childMax
			if newMax > uCap {
				newMax = uCap
			}

			next := make([]int, newMax+1)
			for d := range next {
				next[d] = inf
			}

			if !hasCrit[v] {
				cutCost := cut_cost[v] + penalty*subDemand[v]
				for du, cu := range cur {
					if cu < inf && cu+cutCost < next[du] {
						next[du] = cu + cutCost
					}
				}
			}

			if len(dp[v]) > 0 {
				dpv := dp[v]
				for du, cu := range cur {
					if cu == inf {
						continue
					}
					maxDv := uCap - du
					if len(dpv)-1 < maxDv {
						maxDv = len(dpv) - 1
					}
					for dv := 0; dv <= maxDv; dv++ {
						cv := dpv[dv]
						if cv < inf && cu+cv < next[du+dv] {
							next[du+dv] = cu + cv
						}
					}
				}
			}

			cur = next
		}

		dp[u] = cur
	}

	best := inf
	for _, c := range dp[0] {
		if c < best {
			best = c
		}
	}
	if best == inf {
		return nil
	}
	return &best
}

import java.util.*;

public final class Solution {
    private static final long INF = Long.MAX_VALUE / 4;

    public static Long minPruningCost(
            List<Long> parent,
            List<Long> demand,
            List<Long> cap,
            List<Long> cut_cost,
            List<Boolean> critical,
            long root_cap,
            long penalty) {
        int n = parent.size();
        int[] head = new int[n];
        int[] nextEdge = new int[n];
        Arrays.fill(head, -1);
        for (int v = 1; v < n; v++) {
            int p = parent.get(v).intValue();
            nextEdge[v] = head[p];
            head[p] = v;
        }

        int[] order = new int[n];
        int qHead = 0;
        int qTail = 0;
        order[qTail++] = 0;
        while (qHead < qTail) {
            int u = order[qHead++];
            for (int c = head[u]; c != -1; c = nextEdge[c]) {
                order[qTail++] = c;
            }
        }

        long[] subDemand = new long[n];
        boolean[] hasCrit = new boolean[n];
        long[][] dp = new long[n][];

        for (int idx = n - 1; idx >= 0; idx--) {
            int u = order[idx];
            long dU = demand.get(u);
            long totalSub = dU;
            boolean critSub = critical.get(u);
            for (int c = head[u]; c != -1; c = nextEdge[c]) {
                totalSub += subDemand[c];
                critSub |= hasCrit[c];
            }
            subDemand[u] = totalSub;
            hasCrit[u] = critSub;

            long limitU = (u == 0) ? root_cap : cap.get(u);
            if (dU > limitU) {
                dp[u] = null;
                continue;
            }

            int maxAllowed = (int) Math.min(limitU, totalSub);
            int curMax = (int) dU;
            long[] cur = new long[curMax + 1];
            Arrays.fill(cur, INF);
            cur[curMax] = 0L;

            for (int c = head[u]; c != -1; c = nextEdge[c]) {
                long[] dpC = dp[c];
                int addMax = (dpC == null) ? 0 : (dpC.length - 1);
                int nextMax = Math.min(maxAllowed, curMax + addMax);
                long[] next = new long[nextMax + 1];
                Arrays.fill(next, INF);

                if (!hasCrit[c]) {
                    long cutPenalty = cut_cost.get(c) + penalty * subDemand[c];
                    for (int i = 0; i <= curMax; i++) {
                        if (cur[i] != INF) {
                            next[i] = cur[i] + cutPenalty;
                        }
                    }
                }

                if (dpC != null) {
                    for (int i = 0; i <= curMax; i++) {
                        long baseCost = cur[i];
                        if (baseCost == INF) {
                            continue;
                        }
                        int maxJ = Math.min(dpC.length - 1, nextMax - i);
                        for (int j = 0; j <= maxJ; j++) {
                            long childCost = dpC[j];
                            if (childCost != INF) {
                                long cand = baseCost + childCost;
                                if (cand < next[i + j]) {
                                    next[i + j] = cand;
                                }
                            }
                        }
                    }
                }

                boolean anyFeasible = false;
                for (int i = 0; i <= nextMax; i++) {
                    if (next[i] != INF) {
                        anyFeasible = true;
                        break;
                    }
                }
                if (!anyFeasible) {
                    cur = null;
                    break;
                }
                cur = next;
                curMax = nextMax;
            }

            dp[u] = cur;
        }

        if (dp[0] == null) {
            return null;
        }
        long ans = INF;
        for (long cost : dp[0]) {
            if (cost < ans) {
                ans = cost;
            }
        }
        return ans == INF ? null : ans;
    }
}

#include <algorithm>
#include <optional>
#include <utility>
#include <vector>

std::optional<long long> min_pruning_cost(
    const std::vector<long long>& parent,
    const std::vector<long long>& demand,
    const std::vector<long long>& cap,
    const std::vector<long long>& cut_cost,
    const std::vector<bool>& critical,
    long long root_cap,
    long long penalty) {
    const int n = static_cast<int>(parent.size());
    if (n == 0) {
        return 0;
    }

    std::vector<std::vector<int>> children(n);
    for (int v = 1; v < n; ++v) {
        children[static_cast<int>(parent[v])].push_back(v);
    }

    constexpr long long INF = 4'000'000'000'000'000'000LL;

    std::vector<long long> sub_demand(n, 0);
    std::vector<bool> has_crit(n, false);
    std::vector<std::vector<long long>> dp(n);

    auto dfs = [&](auto& self, int u) -> void {
        sub_demand[u] = demand[u];
        has_crit[u] = critical[u];

        for (int v : children[u]) {
            self(self, v);
            sub_demand[u] += sub_demand[v];
            if (has_crit[v]) {
                has_crit[u] = true;
            }
        }

        const long long lim = (u == 0) ? root_cap : cap[u];
        if (demand[u] > lim) {
            return;
        }

        std::vector<long long> cur(static_cast<std::size_t>(demand[u] + 1), INF);
        cur[static_cast<std::size_t>(demand[u])] = 0;

        for (int v : children[u]) {
            const int max_w_u = static_cast<int>(cur.size()) - 1;
            const int max_w_v = dp[v].empty() ? 0 : static_cast<int>(dp[v].size()) - 1;
            const int next_max_w = static_cast<int>(
                std::min<long long>(lim, static_cast<long long>(max_w_u) + max_w_v));

            std::vector<long long> nxt(static_cast<std::size_t>(next_max_w + 1), INF);

            if (!has_crit[v]) {
                const long long c_cost = cut_cost[v] + penalty * sub_demand[v];
                for (int w = 0; w <= max_w_u; ++w) {
                    if (cur[w] < INF) {
                        nxt[w] = std::min(nxt[w], cur[w] + c_cost);
                    }
                }
            }

            if (!dp[v].empty()) {
                for (int w1 = 0; w1 <= max_w_u; ++w1) {
                    if (cur[w1] == INF) {
                        continue;
                    }
                    const int w2_limit = std::min(max_w_v, next_max_w - w1);
                    for (int w2 = 0; w2 <= w2_limit; ++w2) {
                        if (dp[v][w2] < INF) {
                            nxt[w1 + w2] = std::min(nxt[w1 + w2], cur[w1] + dp[v][w2]);
                        }
                    }
                }
            }

            bool any_valid = false;
            for (long long val : nxt) {
                if (val < INF) {
                    any_valid = true;
                    break;
                }
            }
            if (!any_valid) {
                cur.clear();
                break;
            }
            cur = std::move(nxt);
        }

        dp[u] = std::move(cur);
    };

    dfs(dfs, 0);

    if (dp[0].empty()) {
        return std::nullopt;
    }

    const long long ans = *std::min_element(dp[0].begin(), dp[0].end());
    if (ans >= INF) {
        return std::nullopt;
    }
    return ans;
}

export function minPruningCost(
  parent: number[],
  demand: number[],
  cap: number[],
  cut_cost: number[],
  critical: boolean[],
  root_cap: number,
  penalty: number
): number | null {
  const n = parent.length;
  const children: number[][] = Array.from({ length: n }, () => []);
  for (let v = 1; v < n; v++) {
    children[parent[v]].push(v);
  }

  // Iterative DFS order from root 0
  const order: number[] = [];
  const stack: number[] = [0];
  while (stack.length > 0) {
    const u = stack.pop()!;
    order.push(u);
    for (const c of children[u]) {
      stack.push(c);
    }
  }

  const subDemand = new Float64Array(n);
  const hasCritical = new Uint8Array(n);
  const dp: (Float64Array | null)[] = new Array(n).fill(null);

  // Process bottom-up
  for (let idx = order.length - 1; idx >= 0; idx--) {
    const u = order[idx];
    let totalDem = demand[u];
    let crit = critical[u] ? 1 : 0;
    for (const c of children[u]) {
      totalDem += subDemand[c];
      crit |= hasCritical[c];
    }
    subDemand[u] = totalDem;
    hasCritical[u] = crit;

    const limit = u === 0 ? root_cap : cap[u];
    if (demand[u] > limit) {
      dp[u] = null;
      continue;
    }

    let curMaxW = demand[u];
    let cur = new Float64Array(curMaxW + 1).fill(Infinity);
    cur[demand[u]] = 0;

    let possible = true;
    for (const c of children[u]) {
      const childDp = dp[c];
      const canCut = hasCritical[c] === 0;
      const cutActionCost = cut_cost[c] + penalty * subDemand[c];

      const childMaxW = childDp !== null ? childDp.length - 1 : -1;
      const nextMaxW = Math.min(
        limit,
        curMaxW + Math.max(canCut ? 0 : -1, childMaxW)
      );

      if (nextMaxW < demand[u]) {
        possible = false;
        break;
      }

      const next = new Float64Array(nextMaxW + 1).fill(Infinity);
      let anyFinite = false;

      if (canCut) {
        for (let w = 0; w <= curMaxW; w++) {
          const base = cur[w];
          if (base !== Infinity) {
            const cand = base + cutActionCost;
            if (cand < next[w]) {
              next[w] = cand;
              anyFinite = true;
            }
          }
        }
      }

      if (childDp !== null) {
        for (let w = 0; w <= curMaxW; w++) {
          const base = cur[w];
          if (base === Infinity) continue;
          const maxCw = Math.min(childMaxW, nextMaxW - w);
          for (let cw = 0; cw <= maxCw; cw++) {
            const cCost = childDp[cw];
            if (cCost !== Infinity) {
              const cand = base + cCost;
              if (cand < next[w + cw]) {
                next[w + cw] = cand;
                anyFinite = true;
              }
            }
          }
        }
      }

      if (!anyFinite) {
        possible = false;
        break;
      }

      cur = next;
      curMaxW = nextMaxW;
    }

    dp[u] = possible ? cur : null;
  }

  const rootDp = dp[0];
  if (rootDp === null) {
    return null;
  }

  let ans = Infinity;
  for (let w = 0; w < rootDp.length; w++) {
    if (rootDp[w] < ans) {
      ans = rootDp[w];
    }
  }

  return ans === Infinity ? null : ans;
}

package main

import "sort"

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
	F3 int
	F4 int
}

type byTripDep []Tuple1

func (s byTripDep) Len() int      { return len(s) }
func (s byTripDep) Swap(i, j int) { s[i], s[j] = s[j], s[i] }
func (s byTripDep) Less(i, j int) bool {
	if s[i].F0 != s[j].F0 {
		return s[i].F0 < s[j].F0
	}
	return s[i].F3 < s[j].F3
}

type outEdge struct {
	dep    int
	trip   int32
	absIdx int32
}

type byDepDesc []outEdge

func (s byDepDesc) Len() int           { return len(s) }
func (s byDepDesc) Swap(i, j int)      { s[i], s[j] = s[j], s[i] }
func (s byDepDesc) Less(i, j int) bool { return s[i].dep > s[j].dep }

func EarliestArrival(connections []Tuple1, transfer []int, source int, target int, start_time int, max_boardings int) *int {
	if source == target {
		ans := start_time
		return &ans
	}
	m := len(connections)
	if max_boardings <= 0 || m == 0 {
		return nil
	}

	n := len(transfer)
	conns := make([]Tuple1, m)
	copy(conns, connections)
	sort.Sort(byTripDep(conns))

	deg := make([]int, n)
	var boardedEnd []int32
	for i := 0; i < m; {
		tid := conns[i].F0
		j := i
		for j < m && conns[j].F0 == tid {
			deg[conns[j].F1]++
			j++
		}
		boardedEnd = append(boardedEnd, int32(j))
		i = j
	}

	numTrips := len(boardedEnd)
	minStart := make([]int32, numTrips)
	copy(minStart, boardedEnd)

	offset := make([]int, n+1)
	for u := 0; u < n; u++ {
		offset[u+1] = offset[u] + deg[u]
	}
	ptr := make([]int, n)
	copy(ptr, offset[:n])

	outEdges := make([]outEdge, m)
	tripIdx := int32(0)
	tripLimit := boardedEnd[0]
	for i := 0; i < m; i++ {
		for int32(i) >= tripLimit {
			tripIdx++
			tripLimit = boardedEnd[tripIdx]
		}
		u := conns[i].F1
		pos := ptr[u]
		outEdges[pos] = outEdge{
			dep:    conns[i].F3,
			trip:   tripIdx,
			absIdx: int32(i),
		}
		ptr[u] = pos + 1
	}

	copy(ptr, offset[:n])
	for u := 0; u < n; u++ {
		start, end := offset[u], offset[u+1]
		if end-start > 1 {
			sort.Sort(byDepDesc(outEdges[start:end]))
		}
	}

	const inf = int(1) << 62
	ready := make([]int, n)
	for u := 0; u < n; u++ {
		ready[u] = inf
	}
	ready[source] = start_time

	updated := make([]int, 0, n)
	nextUpdated := make([]int, 0, n)
	inUpdated := make([]bool, n)
	updated = append(updated, source)

	activeTrips := make([]int32, 0, numTrips)
	bestTarget := inf

	for round := 1; round <= max_boardings; round++ {
		for _, u := range updated {
			inUpdated[u] = false
			r := ready[u]
			if r >= bestTarget {
				continue
			}
			end := offset[u+1]
			p := ptr[u]
			for p < end && outEdges[p].dep >= r {
				e := outEdges[p]
				t := e.trip
				if e.absIdx < minStart[t] {
					if minStart[t] == boardedEnd[t] {
						activeTrips = append(activeTrips, t)
					}
					minStart[t] = e.absIdx
				}
				p++
			}
			ptr[u] = p
		}
		updated = updated[:0]

		if len(activeTrips) == 0 {
			break
		}

		for _, t := range activeTrips {
			limit := int(boardedEnd[t])
			for i := int(minStart[t]); i < limit; i++ {
				v := conns[i].F2
				arr := conns[i].F4
				if v == target && arr < bestTarget {
					bestTarget = arr
				}
				nr := arr + transfer[v]
				if nr < ready[v] && nr < bestTarget {
					ready[v] = nr
					if !inUpdated[v] {
						inUpdated[v] = true
						nextUpdated = append(nextUpdated, v)
					}
				}
			}
			boardedEnd[t] = minStart[t]
		}
		activeTrips = activeTrips[:0]

		if len(nextUpdated) == 0 {
			break
		}
		updated, nextUpdated = nextUpdated, updated
	}

	if bestTarget == inf {
		return nil
	}
	return &bestTarget
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2, long f3, long f4) {}

    public static Long earliestArrival(List<Tuple1> connections, List<Long> transfer, long source, long target, long start_time, long max_boardings) {
        if (source == target) {
            return start_time;
        }
        if (max_boardings <= 0 || connections.isEmpty()) {
            return null;
        }

        int n = transfer.size();
        int src = (int) source;
        int dst = (int) target;

        long[] transferArr = new long[n];
        int tIdx = 0;
        for (long val : transfer) {
            transferArr[tIdx++] = val;
        }

        int m = connections.size();
        Tuple1[] byTrip = connections.toArray(new Tuple1[0]);
        Arrays.sort(byTrip, (a, b) -> {
            int cmp = Long.compare(a.f0, b.f0);
            return cmp != 0 ? cmp : Long.compare(a.f3, b.f3);
        });

        int numTrips = 1;
        for (int i = 1; i < m; i++) {
            if (byTrip[i].f0 != byTrip[i - 1].f0) {
                numTrips++;
            }
        }

        int[] minBoardedIdx = new int[numTrips];
        int[] connFrom = new int[m];
        int[] connTo = new int[m];
        long[] connDep = new long[m];
        long[] connArr = new long[m];
        int[] connTrip = new int[m];
        int[] deg = new int[n];

        int tripId = 0;
        for (int i = 0; i < m; i++) {
            if (i > 0 && byTrip[i].f0 != byTrip[i - 1].f0) {
                minBoardedIdx[tripId] = i;
                tripId++;
            }
            Tuple1 c = byTrip[i];
            int u = (int) c.f1;
            connFrom[i] = u;
            connTo[i] = (int) c.f2;
            connDep[i] = c.f3;
            connArr[i] = c.f4;
            connTrip[i] = tripId;
            deg[u]++;
        }
        minBoardedIdx[tripId] = m;

        int[] head = new int[n + 1];
        int[] ptr = new int[n];
        int[] writePos = new int[n];
        for (int u = 0; u < n; u++) {
            ptr[u] = head[u];
            writePos[u] = head[u];
            head[u + 1] = head[u] + deg[u];
        }

        int[] order = new int[m];
        for (int i = 0; i < m; i++) {
            order[i] = i;
        }
        sortByDepDesc(order, new int[m], 0, m, connDep);

        int[] outIdx = new int[m];
        for (int i = 0; i < m; i++) {
            int idx = order[i];
            int u = connFrom[idx];
            outIdx[writePos[u]++] = idx;
        }

        long[] ready = new long[n];
        long[] pendingReady = new long[n];
        Arrays.fill(ready, Long.MAX_VALUE);
        Arrays.fill(pendingReady, Long.MAX_VALUE);
        ready[src] = start_time;
        pendingReady[src] = start_time;

        int[] activeStations = new int[n];
        int activeCount = 1;
        activeStations[0] = src;

        boolean[] inTouched = new boolean[n];
        int[] touched = new int[n];
        int touchedCount = 0;

        long ans = Long.MAX_VALUE;

        for (long round = 1; round <= max_boardings && activeCount > 0; round++) {
            for (int i = 0; i < activeCount; i++) {
                int u = activeStations[i];
                long r = ready[u];
                if (r >= ans) {
                    continue;
                }
                int p = ptr[u];
                int end = head[u + 1];
                while (p < end && connDep[outIdx[p]] >= r) {
                    int idx = outIdx[p++];
                    int t = connTrip[idx];
                    int limit = minBoardedIdx[t];
                    if (idx < limit) {
                        for (int j = idx; j < limit; j++) {
                            int v = connTo[j];
                            long arr = connArr[j];
                            if (v == dst && arr < ans) {
                                ans = arr;
                            }
                            long tr = transferArr[v];
                            long cand = (Long.MAX_VALUE - tr < arr) ? Long.MAX_VALUE : arr + tr;
                            if (cand < pendingReady[v]) {
                                pendingReady[v] = cand;
                                if (!inTouched[v]) {
                                    inTouched[v] = true;
                                    touched[touchedCount++] = v;
                                }
                            }
                        }
                        minBoardedIdx[t] = idx;
                    }
                }
                ptr[u] = p;
            }

            activeCount = 0;
            for (int i = 0; i < touchedCount; i++) {
                int v = touched[i];
                inTouched[v] = false;
                ready[v] = pendingReady[v];
                if (ready[v] < ans) {
                    activeStations[activeCount++] = v;
                }
            }
            touchedCount = 0;
        }

        return ans == Long.MAX_VALUE ? null : ans;
    }

    private static void sortByDepDesc(int[] a, int[] tmp, int left, int right, long[] dep) {
        if (right - left <= 16) {
            for (int i = left + 1; i < right; i++) {
                int v = a[i];
                long dv = dep[v];
                int j = i - 1;
                while (j >= left && dep[a[j]] < dv) {
                    a[j + 1] = a[j];
                    j--;
                }
                a[j + 1] = v;
            }
            return;
        }
        int mid = (left + right) >>> 1;
        sortByDepDesc(a, tmp, left, mid, dep);
        sortByDepDesc(a, tmp, mid, right, dep);
        if (dep[a[mid - 1]] >= dep[a[mid]]) {
            return;
        }
        int p = left;
        int q = mid;
        int k = left;
        while (p < mid && q < right) {
            if (dep[a[p]] >= dep[a[q]]) {
                tmp[k++] = a[p++];
            } else {
                tmp[k++] = a[q++];
            }
        }
        while (p < mid) {
            tmp[k++] = a[p++];
        }
        while (q < right) {
            tmp[k++] = a[q++];
        }
        System.arraycopy(tmp, left, a, left, right - left);
    }
}

#include <algorithm>
#include <cstdint>
#include <limits>
#include <optional>
#include <tuple>
#include <vector>

std::optional<long long> earliest_arrival(
    const std::vector<std::tuple<long long, long long, long long, long long, long long>>& connections,
    const std::vector<long long>& transfer,
    long long source,
    long long target,
    long long start_time,
    long long max_boardings) {
    if (source == target) {
        return start_time;
    }
    if (max_boardings <= 0 || connections.empty()) {
        return std::nullopt;
    }

    const int n = static_cast<int>(transfer.size());

    struct RawConn {
        long long trip_id;
        long long dep;
        long long arr;
        int from;
        int to;
    };

    std::vector<RawConn> raw;
    raw.reserve(connections.size());
    for (const auto& c : connections) {
        const long long dep = std::get<3>(c);
        if (dep < start_time) {
            continue;
        }
        raw.push_back(RawConn{
            std::get<0>(c),
            dep,
            std::get<4>(c),
            static_cast<int>(std::get<1>(c)),
            static_cast<int>(std::get<2>(c))
        });
    }

    if (raw.empty()) {
        return std::nullopt;
    }

    std::sort(raw.begin(), raw.end(), [](const RawConn& a, const RawConn& b) {
        if (a.trip_id != b.trip_id) {
            return a.trip_id < b.trip_id;
        }
        return a.dep < b.dep;
    });

    const int m = static_cast<int>(raw.size());

    struct TripConn {
        long long arr;
        int to;
    };

    std::vector<TripConn> trip_conns(m);
    std::vector<int> earliest_boarded;
    earliest_boarded.reserve(m);

    std::vector<int> head(n + 1, 0);
    for (int i = 0; i < m; ++i) {
        ++head[raw[i].from + 1];
    }
    for (int u = 0; u < n; ++u) {
        head[u + 1] += head[u];
    }

    struct OutEdge {
        long long dep;
        int trip;
        int idx;
    };

    std::vector<OutEdge> out_edges(m);
    std::vector<int> write_pos(head.begin(), head.begin() + n);

    int num_trips = 0;
    for (int i = 0; i < m;) {
        int j = i;
        const long long tid = raw[i].trip_id;
        while (j < m && raw[j].trip_id == tid) {
            trip_conns[j] = TripConn{raw[j].arr, raw[j].to};
            const int u = raw[j].from;
            out_edges[write_pos[u]++] = OutEdge{raw[j].dep, num_trips, j};
            ++j;
        }
        earliest_boarded.push_back(j);
        ++num_trips;
        i = j;
    }

    {
        std::vector<RawConn>().swap(raw);
    }

    for (int u = 0; u < n; ++u) {
        if (head[u + 1] - head[u] > 1) {
            std::sort(out_edges.begin() + head[u], out_edges.begin() + head[u + 1],
                      [](const OutEdge& a, const OutEdge& b) {
                          return a.dep < b.dep;
                      });
        }
    }

    constexpr long long INF = std::numeric_limits<long long>::max();

    std::vector<int> ptr(head.begin() + 1, head.end());
    std::vector<long long> best_ready(n, INF);
    std::vector<long long> pending_ready(n, INF);
    std::vector<std::uint8_t> in_next_active(n, 0);

    const int src = static_cast<int>(source);
    const int dst = static_cast<int>(target);

    best_ready[src] = start_time;
    pending_ready[src] = start_time;

    std::vector<int> active = {src};
    std::vector<int> next_active;

    long long ans = INF;

    for (long long round = 1; round <= max_boardings && !active.empty(); ++round) {
        const bool allow_transfer = (round < max_boardings);
        for (int u : active) {
            const long long r_u = best_ready[u];
            const int limit = head[u];
            int p = ptr[u];
            while (p > limit && out_edges[p - 1].dep >= r_u) {
                --p;
                const OutEdge& e = out_edges[p];
                if (e.dep >= ans) {
                    continue;
                }
                const int eb = earliest_boarded[e.trip];
                if (e.idx < eb) {
                    for (int j = e.idx; j < eb; ++j) {
                        const int v = trip_conns[j].to;
                        const long long arr = trip_conns[j].arr;
                        if (v == dst && arr < ans) {
                            ans = arr;
                        }
                        if (allow_transfer && arr < ans) {
                            const long long tv = transfer[v];
                            const long long r_v = (tv > INF - arr) ? INF : (arr + tv);
                            if (r_v < pending_ready[v] && r_v < ans) {
                                pending_ready[v] = r_v;
                                if (!in_next_active[v]) {
                                    in_next_active[v] = 1;
                                    next_active.push_back(v);
                                }
                            }
                        }
                    }
                    earliest_boarded[e.trip] = e.idx;
                }
            }
            ptr[u] = p;
        }

        for (int v : next_active) {
            best_ready[v] = pending_ready[v];
            in_next_active[v] = 0;
        }
        active.swap(next_active);
        next_active.clear();
    }

    if (ans == INF) {
        return std::nullopt;
    }
    return ans;
}

export function earliestArrival(
  connections: [number, number, number, number, number][],
  transfer: number[],
  source: number,
  target: number,
  start_time: number,
  max_boardings: number
): number | null {
  if (source === target) {
    return start_time;
  }
  const mTotal = connections.length;
  if (max_boardings <= 0 || mTotal === 0) {
    return null;
  }

  const nStations = transfer.length;

  const validIndices = new Int32Array(mTotal);
  const validTripIds = new Int32Array(mTotal);
  const tripMap = new Map<number, number>();
  const tripLengths: number[] = [];
  const stationDeg = new Int32Array(nStations);

  let k = 0;
  let maxDep = 0;
  for (let i = 0; i < mTotal; i++) {
    const conn = connections[i];
    const dep = conn[3];
    if (dep < start_time) {
      continue;
    }
    if (dep > maxDep) {
      maxDep = dep;
    }
    const rawTrip = conn[0];
    let tid = tripMap.get(rawTrip);
    if (tid === undefined) {
      tid = tripLengths.length;
      tripMap.set(rawTrip, tid);
      tripLengths.push(1);
    } else {
      tripLengths[tid]++;
    }
    validIndices[k] = i;
    validTripIds[k] = tid;
    stationDeg[conn[1]]++;
    k++;
  }

  if (k === 0) {
    return null;
  }

  const sortedOrder = new Int32Array(k);
  if (k <= 65536 && maxDep <= 1e10) {
    const packed = new Float64Array(k);
    for (let j = 0; j < k; j++) {
      packed[j] = connections[validIndices[j]][3] * 65536 + j;
    }
    packed.sort();
    const inv = 1 / 65536;
    for (let j = 0; j < k; j++) {
      const val = packed[j];
      sortedOrder[j] = val - Math.floor(val * inv) * 65536;
    }
  } else {
    for (let j = 0; j < k; j++) {
      sortedOrder[j] = j;
    }
    sortedOrder.sort(
      (a, b) => connections[validIndices[a]][3] - connections[validIndices[b]][3]
    );
  }

  const numTrips = tripLengths.length;
  const tripWritePtr = new Int32Array(numTrips);
  const firstBoarded = new Int32Array(numTrips);
  let tripOffset = 0;
  for (let t = 0; t < numTrips; t++) {
    tripWritePtr[t] = tripOffset;
    tripOffset += tripLengths[t];
    firstBoarded[t] = tripOffset;
  }

  const stStart = new Int32Array(nStations);
  const stPtr = new Int32Array(nStations);
  let stOffset = 0;
  for (let s = 0; s < nStations; s++) {
    stStart[s] = stOffset;
    stPtr[s] = stOffset;
    stOffset += stationDeg[s];
  }

  const tripTo = new Int32Array(k);
  const tripArr = new Float64Array(k);
  const stDep = new Float64Array(k);
  const stTrip = new Int32Array(k);
  const stGPos = new Int32Array(k);

  for (let j = 0; j < k; j++) {
    const validIdx = sortedOrder[j];
    const conn = connections[validIndices[validIdx]];
    const tid = validTripIds[validIdx];

    const gPos = tripWritePtr[tid]++;
    tripTo[gPos] = conn[2];
    tripArr[gPos] = conn[4];

    const fromSt = conn[1];
    const sPos = stPtr[fromSt]++;
    stDep[sPos] = conn[3];
    stTrip[sPos] = tid;
    stGPos[sPos] = gPos;
  }

  const ready = new Float64Array(nStations);
  const bestArr = new Float64Array(nStations);
  ready.fill(Infinity);
  bestArr.fill(Infinity);
  ready[source] = start_time;

  let updated = new Int32Array(nStations);
  let nextUpdated = new Int32Array(nStations);
  const changedStations = new Int32Array(nStations);
  const inChanged = new Uint8Array(nStations);

  updated[0] = source;
  let numUpdated = 1;

  const maxRounds = max_boardings < k ? max_boardings : k;

  for (let round = 0; round < maxRounds && numUpdated > 0; round++) {
    let numChanged = 0;

    for (let i = 0; i < numUpdated; i++) {
      const s = updated[i];
      const r = ready[s];
      const startIdx = stStart[s];
      let ptr = stPtr[s];

      while (ptr > startIdx && stDep[ptr - 1] >= r) {
        ptr--;
        const tid = stTrip[ptr];
        const gPos = stGPos[ptr];
        const limit = firstBoarded[tid];
        if (gPos < limit) {
          firstBoarded[tid] = gPos;
          for (let m = gPos; m < limit; m++) {
            const v = tripTo[m];
            const a = tripArr[m];
            if (a < bestArr[v]) {
              bestArr[v] = a;
              if (inChanged[v] === 0) {
                inChanged[v] = 1;
                changedStations[numChanged++] = v;
              }
            }
          }
        }
      }

      stPtr[s] = ptr;
    }

    if (round + 1 === maxRounds) {
      break;
    }

    let numNextUpdated = 0;
    for (let i = 0; i < numChanged; i++) {
      const v = changedStations[i];
      inChanged[v] = 0;
      const newReady = bestArr[v] + transfer[v];
      if (newReady < ready[v]) {
        ready[v] = newReady;
        nextUpdated[numNextUpdated++] = v;
      }
    }

    const tmp = updated;
    updated = nextUpdated;
    nextUpdated = tmp;
    numUpdated = numNextUpdated;
  }

  const ans = bestArr[target];
  return ans === Infinity ? null : ans;
}

package main

import "errors"

type Tuple1 struct {
	F0 int
	F1 string
	F2 int
	F3 bool
}

type clientState struct {
	tokens   int
	lastTime int
	banUntil int
	strikes  []int
	head     int
}

func AdmitRequests(requests []Tuple1, config map[string]int) ([]string, error) {
	for i := 1; i < len(requests); i++ {
		if requests[i].F0 < requests[i-1].F0 {
			return nil, errors.New("requests must be in non-decreasing timestamp order")
		}
	}

	capCfg := config["cap"]
	period := config["period"]
	gcap := config["gcap"]
	gperiod := config["gperiod"]
	reserve := config["reserve"]
	strikesLimit := config["strikes"]
	window := config["window"]
	banLen := config["ban"]

	gTokens := gcap
	gLastTime := 0

	clients := make(map[string]*clientState)
	results := make([]string, len(requests))

	for i, req := range requests {
		t := req.F0
		clientID := req.F1
		cost := req.F2
		vip := req.F3

		if t > gLastTime {
			refills := t/gperiod - gLastTime/gperiod
			gTokens += refills
			if gTokens > gcap {
				gTokens = gcap
			}
			gLastTime = t
		}

		c, exists := clients[clientID]
		if !exists {
			c = &clientState{
				tokens:   capCfg,
				lastTime: t,
			}
			clients[clientID] = c
		} else if t > c.lastTime {
			refills := t/period - c.lastTime/period
			c.tokens += refills
			if c.tokens > capCfg {
				c.tokens = capCfg
			}
			c.lastTime = t
		}

		if t < c.banUntil {
			results[i] = "BANNED"
			continue
		}

		if c.tokens < cost {
			cutoff := t - window
			for c.head < len(c.strikes) && c.strikes[c.head] <= cutoff {
				c.head++
			}
			c.strikes = append(c.strikes, t)
			if len(c.strikes)-c.head >= strikesLimit {
				c.strikes = c.strikes[:0]
				c.head = 0
				c.banUntil = t + banLen
				results[i] = "BAN"
			} else {
				results[i] = "DENY"
			}
			continue
		}

		if vip {
			if gTokens < cost {
				results[i] = "BUSY"
				continue
			}
		} else {
			if gTokens < cost || gTokens-cost < reserve {
				results[i] = "BUSY"
				continue
			}
		}

		c.tokens -= cost
		gTokens -= cost
		results[i] = "OK"
	}

	return results, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, String f1, long f2, boolean f3) {}

    private static final class ClientState {
        long tokens;
        long lastTime;
        long bannedUntil = -1;
        final ArrayDeque<Long> strikeTimes = new ArrayDeque<>();

        ClientState(long tokens, long lastTime) {
            this.tokens = tokens;
            this.lastTime = lastTime;
        }
    }

    public static List<String> admitRequests(List<Tuple1> requests, Map<String, Long> config) {
        int n = requests.size();
        for (int i = 1; i < n; i++) {
            if (requests.get(i).f0() < requests.get(i - 1).f0()) {
                throw new IllegalArgumentException("Request timestamps must be non-decreasing");
            }
        }

        long cap = config.get("cap");
        long period = config.get("period");
        long gcap = config.get("gcap");
        long gperiod = config.get("gperiod");
        long reserve = config.get("reserve");
        long strikes = config.get("strikes");
        long window = config.get("window");
        long ban = config.get("ban");

        long globalTokens = gcap;
        long globalLastTime = 0;

        Map<String, ClientState> clients = new HashMap<>();
        List<String> result = new ArrayList<>(n);

        for (Tuple1 req : requests) {
            long t = req.f0();
            String clientId = req.f1();
            long cost = req.f2();
            boolean vip = req.f3();

            if (t > globalLastTime) {
                long gRefills = (t / gperiod) - (globalLastTime / gperiod);
                globalTokens = Math.min(gcap, globalTokens + gRefills);
                globalLastTime = t;
            }

            ClientState client = clients.get(clientId);
            if (client == null) {
                client = new ClientState(cap, t);
                clients.put(clientId, client);
            } else if (t > client.lastTime) {
                long cRefills = (t / period) - (client.lastTime / period);
                client.tokens = Math.min(cap, client.tokens + cRefills);
                client.lastTime = t;
            }

            if (t < client.bannedUntil) {
                result.add("BANNED");
                continue;
            }

            if (client.tokens < cost) {
                while (!client.strikeTimes.isEmpty() && t - client.strikeTimes.peekFirst() >= window) {
                    client.strikeTimes.pollFirst();
                }
                client.strikeTimes.addLast(t);
                if (client.strikeTimes.size() >= strikes) {
                    client.strikeTimes.clear();
                    client.bannedUntil = t + ban;
                    result.add("BAN");
                } else {
                    result.add("DENY");
                }
                continue;
            }

            long minGlobalRequired = vip ? cost : cost + reserve;
            if (globalTokens < minGlobalRequired) {
                result.add("BUSY");
                continue;
            }

            client.tokens -= cost;
            globalTokens -= cost;
            result.add("OK");
        }

        return result;
    }
}

#include <algorithm>
#include <deque>
#include <map>
#include <stdexcept>
#include <string>
#include <tuple>
#include <unordered_map>
#include <vector>

std::vector<std::string> admit_requests(
    const std::vector<std::tuple<long long, std::string, long long, bool>>& requests,
    const std::map<std::string, long long>& config) {
    for (std::size_t i = 1; i < requests.size(); ++i) {
        if (std::get<0>(requests[i]) < std::get<0>(requests[i - 1])) {
            throw std::invalid_argument("Request timestamps must be non-decreasing");
        }
    }

    const long long cap = config.at("cap");
    const long long period = config.at("period");
    const long long gcap = config.at("gcap");
    const long long gperiod = config.at("gperiod");
    const long long reserve = config.at("reserve");
    const long long strikes_limit = config.at("strikes");
    const long long window = config.at("window");
    const long long ban_duration = config.at("ban");

    struct ClientState {
        long long tokens = 0;
        long long last_t = 0;
        long long ban_until = -1;
        std::deque<long long> strikes;
    };

    std::unordered_map<std::string, ClientState> clients;
    long long global_tokens = gcap;
    long long global_last_t = 0;

    std::vector<std::string> results;
    results.reserve(requests.size());

    for (const auto& [t, client_id, cost, vip] : requests) {
        if (t > global_last_t) {
            long long grefills = (t / gperiod) - (global_last_t / gperiod);
            global_tokens = std::min(gcap, global_tokens + grefills);
            global_last_t = t;
        }

        auto [it, inserted] = clients.try_emplace(client_id);
        ClientState& client = it->second;
        if (inserted) {
            client.tokens = cap;
            client.last_t = t;
        } else if (t > client.last_t) {
            long long crefills = (t / period) - (client.last_t / period);
            client.tokens = std::min(cap, client.tokens + crefills);
            client.last_t = t;
        }

        if (t < client.ban_until) {
            results.emplace_back("BANNED");
            continue;
        }

        if (client.tokens < cost) {
            long long cutoff = t - window;
            while (!client.strikes.empty() && client.strikes.front() <= cutoff) {
                client.strikes.pop_front();
            }
            client.strikes.push_back(t);

            if (static_cast<long long>(client.strikes.size()) >= strikes_limit) {
                client.strikes.clear();
                client.ban_until = t + ban_duration;
                results.emplace_back("BAN");
            } else {
                results.emplace_back("DENY");
            }
            continue;
        }

        bool global_ok = vip ? (global_tokens >= cost) : (global_tokens - cost >= reserve);
        if (!global_ok) {
            results.emplace_back("BUSY");
            continue;
        }

        client.tokens -= cost;
        global_tokens -= cost;
        results.emplace_back("OK");
    }

    return results;
}

interface ClientState {
  tokens: number;
  lastT: number;
  banUntil: number;
  strikes: number[];
  strikeHead: number;
}

export function admitRequests(
  requests: [number, string, number, boolean][],
  config: Record<string, number>
): string[] {
  const n = requests.length;
  for (let i = 1; i < n; i++) {
    if (requests[i][0] < requests[i - 1][0]) {
      throw new Error("Request timestamps must be non-decreasing");
    }
  }

  const cap = config["cap"];
  const period = config["period"];
  const gcap = config["gcap"];
  const gperiod = config["gperiod"];
  const reserve = config["reserve"];
  const maxStrikes = config["strikes"];
  const windowLen = config["window"];
  const banLen = config["ban"];

  let globalTokens = gcap;
  let globalLastT = 0;

  const clients = new Map<string, ClientState>();
  const results = new Array<string>(n);

  for (let i = 0; i < n; i++) {
    const req = requests[i];
    const t = req[0];
    const clientId = req[1];
    const cost = req[2];
    const vip = req[3];

    if (t > globalLastT) {
      const gRefills = Math.floor(t / gperiod) - Math.floor(globalLastT / gperiod);
      if (gRefills > 0) {
        globalTokens = Math.min(gcap, globalTokens + gRefills);
      }
      globalLastT = t;
    }

    let client = clients.get(clientId);
    if (client === undefined) {
      client = {
        tokens: cap,
        lastT: t,
        banUntil: 0,
        strikes: [],
        strikeHead: 0,
      };
      clients.set(clientId, client);
    } else if (t > client.lastT) {
      const cRefills = Math.floor(t / period) - Math.floor(client.lastT / period);
      if (cRefills > 0) {
        client.tokens = Math.min(cap, client.tokens + cRefills);
      }
      client.lastT = t;
    }

    if (t < client.banUntil) {
      results[i] = "BANNED";
      continue;
    }

    if (client.tokens < cost) {
      const cutoff = t - windowLen;
      const strikes = client.strikes;
      let head = client.strikeHead;
      while (head < strikes.length && strikes[head] <= cutoff) {
        head++;
      }
      strikes.push(t);
      if (strikes.length - head >= maxStrikes) {
        client.banUntil = t + banLen;
        client.strikes = [];
        client.strikeHead = 0;
        results[i] = "BAN";
      } else {
        client.strikeHead = head;
        results[i] = "DENY";
      }
      continue;
    }

    const globalAllowed = vip
      ? globalTokens >= cost
      : globalTokens - cost >= reserve;

    if (!globalAllowed) {
      results[i] = "BUSY";
      continue;
    }

    client.tokens -= cost;
    globalTokens -= cost;
    results[i] = "OK";
  }

  return results;
}

package main

import (
	"fmt"
	"strings"
	"unicode"
)

type Tuple1 struct {
	F0 string
	F1 []string
	F2 string
	F3 string
}

type principalKind uint8

const (
	principalAny principalKind = iota
	principalGroup
	principalUser
)

type compiledRule struct {
	isDeny        bool
	pKind         principalKind
	pName         string
	anyAction     bool
	actions       map[string]struct{}
	segments      []string
	minSegs       int
	hasDoubleStar bool
	spec          int
}

func isPySpace(r rune) bool {
	return unicode.IsSpace(r) || (r >= 0x1c && r <= 0x1f)
}

func isValidName(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		b := s[i]
		if !((b >= 'a' && b <= 'z') || (b >= '0' && b <= '9') || b == '_') {
			return false
		}
	}
	return true
}

func isValidActionWord(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		b := s[i]
		if b < 'a' || b > 'z' {
			return false
		}
	}
	return true
}

func isValidLiteralSegment(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		b := s[i]
		if !((b >= 'a' && b <= 'z') || (b >= '0' && b <= '9') || b == '.' || b == '_' || b == '-') {
			return false
		}
	}
	return true
}

func parseResource(res string) (segments []string, literalCount int, minSegs int, hasDoubleStar bool, ok bool) {
	if len(res) == 0 || res[0] != '/' {
		return nil, 0, 0, false, false
	}
	if res == "/" {
		return nil, 0, 0, false, true
	}
	raw := strings.Split(res[1:], "/")
	segments = make([]string, 0, len(raw))
	for _, seg := range raw {
		if seg == "*" {
			minSegs++
			segments = append(segments, seg)
		} else if seg == "**" {
			hasDoubleStar = true
			if len(segments) == 0 || segments[len(segments)-1] != "**" {
				segments = append(segments, seg)
			}
		} else if isValidLiteralSegment(seg) {
			literalCount++
			minSegs++
			segments = append(segments, seg)
		} else {
			return nil, 0, 0, false, false
		}
	}
	return segments, literalCount, minSegs, hasDoubleStar, true
}

func parsePath(path string) ([]string, bool) {
	if len(path) == 0 || path[0] != '/' {
		return nil, false
	}
	if path == "/" {
		return nil, true
	}
	segs := strings.Split(path[1:], "/")
	for _, seg := range segs {
		if !isValidLiteralSegment(seg) {
			return nil, false
		}
	}
	return segs, true
}

func matchResource(pat []string, minSegs int, hasDoubleStar bool, path []string, dp []bool) bool {
	n := len(path)
	if n < minSegs {
		return false
	}
	if !hasDoubleStar {
		if len(pat) != n {
			return false
		}
		for i, p := range pat {
			if p != "*" && p != path[i] {
				return false
			}
		}
		return true
	}

	for j := 1; j <= n; j++ {
		dp[j] = false
	}
	dp[0] = true

	for _, p := range pat {
		if p == "**" {
			for j := 1; j <= n; j++ {
				if dp[j-1] {
					dp[j] = true
				}
			}
		} else if p == "*" {
			anyTrue := false
			for j := n; j >= 1; j-- {
				dp[j] = dp[j-1]
				if dp[j] {
					anyTrue = true
				}
			}
			dp[0] = false
			if !anyTrue {
				return false
			}
		} else {
			anyTrue := false
			for j := n; j >= 1; j-- {
				v := dp[j-1] && path[j-1] == p
				dp[j] = v
				if v {
					anyTrue = true
				}
			}
			dp[0] = false
			if !anyTrue {
				return false
			}
		}
	}
	return dp[n]
}

func EvaluateAccess(rules []string, requests []Tuple1) ([]string, error) {
	compiled := make([]compiledRule, len(rules))
	for i, ruleStr := range rules {
		fields := strings.FieldsFunc(ruleStr, isPySpace)
		if len(fields) != 4 {
			return nil, fmt.Errorf("rule %d: expected 4 fields, got %d", i, len(fields))
		}

		effect, principal, action, resource := fields[0], fields[1], fields[2], fields[3]

		var isDeny bool
		if effect == "ALLOW" {
			isDeny = false
		} else if effect == "DENY" {
			isDeny = true
		} else {
			return nil, fmt.Errorf("rule %d: bad effect %q", i, effect)
		}

		var pKind principalKind
		var pName string
		var specP int
		if principal == "*" {
			pKind = principalAny
			specP = 0
		} else if strings.HasPrefix(principal, "user:") {
			name := principal[len("user:"):]
			if !isValidName(name) {
				return nil, fmt.Errorf("rule %d: bad principal %q", i, principal)
			}
			pKind = principalUser
			pName = name
			specP = 2
		} else if strings.HasPrefix(principal, "group:") {
			name := principal[len("group:"):]
			if !isValidName(name) {
				return nil, fmt.Errorf("rule %d: bad principal %q", i, principal)
			}
			pKind = principalGroup
			pName = name
			specP = 1
		} else {
			return nil, fmt.Errorf("rule %d: bad principal %q", i, principal)
		}

		var anyAction bool
		var actions map[string]struct{}
		var specA int
		if action == "*" {
			anyAction = true
			specA = 0
		} else {
			parts := strings.Split(action, ",")
			actions = make(map[string]struct{}, len(parts))
			for _, w := range parts {
				if !isValidActionWord(w) {
					return nil, fmt.Errorf("rule %d: bad action %q", i, action)
				}
				actions[w] = struct{}{}
			}
			specA = 1
		}

		segs, specL, minSegs, hasDoubleStar, ok := parseResource(resource)
		if !ok {
			return nil, fmt.Errorf("rule %d: bad resource %q", i, resource)
		}

		compiled[i] = compiledRule{
			isDeny:        isDeny,
			pKind:         pKind,
			pName:         pName,
			anyAction:     anyAction,
			actions:       actions,
			segments:      segs,
			minSegs:       minSegs,
			hasDoubleStar: hasDoubleStar,
			spec:          (specL << 3) | (specP << 1) | specA,
		}
	}

	parsedPaths := make([][]string, len(requests))
	maxPathLen := 0
	for j, req := range requests {
		if !isValidName(req.F0) {
			return nil, fmt.Errorf("request %d: bad user %q", j, req.F0)
		}
		for _, g := range req.F1 {
			if !isValidName(g) {
				return nil, fmt.Errorf("request %d: bad groups", j)
			}
		}
		if !isValidActionWord(req.F2) {
			return nil, fmt.Errorf("request %d: bad action %q", j, req.F2)
		}
		pSegs, ok := parsePath(req.F3)
		if !ok {
			return nil, fmt.Errorf("request %d: bad path %q", j, req.F3)
		}
		parsedPaths[j] = pSegs
		if len(pSegs) > maxPathLen {
			maxPathLen = len(pSegs)
		}
	}

	decisions := make([]string, len(requests))
	dp := make([]bool, maxPathLen+1)

	for j, req := range requests {
		user := req.F0
		groups := req.F1
		action := req.F2
		pathSegs := parsedPaths[j]

		var groupSet map[string]struct{}
		if len(groups) > 4 {
			groupSet = make(map[string]struct{}, len(groups))
			for _, g := range groups {
				groupSet[g] = struct{}{}
			}
		}

		hasMatch := false
		bestSpec := -1
		bestIsDeny := false
		bestIdx := -1

		for i := range compiled {
			r := &compiled[i]

			if hasMatch {
				if r.spec < bestSpec {
					continue
				}
				if r.spec == bestSpec && (bestIsDeny || !r.isDeny) {
					continue
				}
			}

			switch r.pKind {
			case principalUser:
				if r.pName != user {
					continue
				}
			case principalGroup:
				if groupSet != nil {
					if _, ok := groupSet[r.pName]; !ok {
						continue
					}
				} else {
					found := false
					for _, g := range groups {
						if g == r.pName {
							found = true
							break
						}
					}
					if !found {
						continue
					}
				}
			}

			if !r.anyAction {
				if _, ok := r.actions[action]; !ok {
					continue
				}
			}

			if !matchResource(r.segments, r.minSegs, r.hasDoubleStar, pathSegs, dp) {
				continue
			}

			hasMatch = true
			bestSpec = r.spec
			bestIsDeny = r.isDeny
			bestIdx = i
		}

		if !hasMatch {
			decisions[j] = "DENY by default"
		} else if bestIsDeny {
			decisions[j] = fmt.Sprintf("DENY by rule %d", bestIdx)
		} else {
			decisions[j] = fmt.Sprintf("ALLOW by rule %d", bestIdx)
		}
	}

	return decisions, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, List<String> f1, String f2, String f3) {}

    private static final int STAR = -1;
    private static final int DOUBLE_STAR = -2;
    private static final int UNKNOWN_LITERAL = -3;

    private static final int PRINCIPAL_ANY = 0;
    private static final int PRINCIPAL_GROUP = 1;
    private static final int PRINCIPAL_USER = 2;

    private record ParsedRule(
            int index,
            boolean isDeny,
            int principalType,
            String principalName,
            Set<String> actions,
            int[] resourceIds,
            int minSegments,
            boolean hasDoubleStar,
            long specificity,
            String decisionString) {}

    private record ParsedRequest(
            String user,
            Set<String> groups,
            String action,
            int[] pathIds) {}

    public static List<String> evaluateAccess(List<String> rules, List<Tuple1> requests) {
        if (rules == null) {
            throw new IllegalArgumentException("rules must be a list");
        }
        if (requests == null) {
            throw new IllegalArgumentException("requests must be a list");
        }

        Map<String, Integer> segmentToId = new HashMap<>();
        List<ParsedRule> parsedRules = new ArrayList<>(rules.size());

        for (int i = 0; i < rules.size(); i++) {
            String ruleStr = rules.get(i);
            if (ruleStr == null) {
                throw new IllegalArgumentException("rule " + i + ": not a str");
            }
            List<String> fields = splitPythonWhitespace(ruleStr);
            if (fields.size() != 4) {
                throw new IllegalArgumentException(
                        "rule " + i + ": expected 4 fields, got " + fields.size());
            }

            String effect = fields.get(0);
            boolean isDeny;
            if ("ALLOW".equals(effect)) {
                isDeny = false;
            } else if ("DENY".equals(effect)) {
                isDeny = true;
            } else {
                throw new IllegalArgumentException(
                        "rule " + i + ": bad effect " + pyRepr(effect));
            }

            String principal = fields.get(1);
            int principalType;
            String principalName;
            if ("*".equals(principal)) {
                principalType = PRINCIPAL_ANY;
                principalName = null;
            } else if (principal.startsWith("user:")) {
                principalName = principal.substring(5);
                if (!isName(principalName)) {
                    throw new IllegalArgumentException(
                            "rule " + i + ": bad principal " + pyRepr(principal));
                }
                principalType = PRINCIPAL_USER;
            } else if (principal.startsWith("group:")) {
                principalName = principal.substring(6);
                if (!isName(principalName)) {
                    throw new IllegalArgumentException(
                            "rule " + i + ": bad principal " + pyRepr(principal));
                }
                principalType = PRINCIPAL_GROUP;
            } else {
                throw new IllegalArgumentException(
                        "rule " + i + ": bad principal " + pyRepr(principal));
            }

            String actionStr = fields.get(2);
            Set<String> actions;
            if ("*".equals(actionStr)) {
                actions = null;
            } else {
                actions = parseRuleActions(actionStr, i);
            }

            String resourceStr = fields.get(3);
            int[] resourceIds = parseRuleResource(resourceStr, segmentToId, i);

            int literalCount = 0;
            int minSegments = 0;
            boolean hasDoubleStar = false;
            for (int segId : resourceIds) {
                if (segId == DOUBLE_STAR) {
                    hasDoubleStar = true;
                } else {
                    minSegments++;
                    if (segId >= 0) {
                        literalCount++;
                    }
                }
            }

            int actionSpec = (actions == null) ? 0 : 1;
            long specificity = ((long) literalCount << 4) | ((long) principalType << 1) | actionSpec;
            String decisionString = (isDeny ? "DENY by rule " : "ALLOW by rule ") + i;

            parsedRules.add(new ParsedRule(
                    i,
                    isDeny,
                    principalType,
                    principalName,
                    actions,
                    resourceIds,
                    minSegments,
                    hasDoubleStar,
                    specificity,
                    decisionString));
        }

        List<ParsedRequest> parsedRequests = new ArrayList<>(requests.size());
        for (int j = 0; j < requests.size(); j++) {
            Tuple1 req = requests.get(j);
            if (req == null) {
                throw new IllegalArgumentException("request " + j + ": expected 4-tuple");
            }

            String user = req.f0();
            if (user == null || !isName(user)) {
                throw new IllegalArgumentException("request " + j + ": bad user " + pyRepr(user));
            }

            List<String> groupsList = req.f1();
            if (groupsList == null) {
                throw new IllegalArgumentException("request " + j + ": bad groups");
            }
            Set<String> groupsSet = groupsList.isEmpty() ? Set.of() : new HashSet<>(groupsList.size() * 2);
            for (String g : groupsList) {
                if (g == null || !isName(g)) {
                    throw new IllegalArgumentException("request " + j + ": bad groups");
                }
                if (!groupsList.isEmpty()) {
                    groupsSet.add(g);
                }
            }

            String action = req.f2();
            if (action == null || !isActionWord(action)) {
                throw new IllegalArgumentException(
                        "request " + j + ": bad action " + pyRepr(action));
            }

            String path = req.f3();
            int[] pathIds = parseRequestPath(path, segmentToId, j);

            parsedRequests.add(new ParsedRequest(user, groupsSet, action, pathIds));
        }

        if (parsedRequests.isEmpty()) {
            return new ArrayList<>();
        }

        parsedRules.sort((a, b) -> {
            int cmp = Long.compare(b.specificity(), a.specificity());
            if (cmp != 0) return cmp;
            cmp = Boolean.compare(b.isDeny(), a.isDeny());
            if (cmp != 0) return cmp;
            return Integer.compare(a.index(), b.index());
        });

        long[] reqSegMasks = new long[segmentToId.size()];
        List<String> decisions = new ArrayList<>(parsedRequests.size());

        for (ParsedRequest req : parsedRequests) {
            int[] pIds = req.pathIds();
            int n = pIds.length;
            boolean useBitmask = (n <= 63);
            long validBits = 0L;

            if (useBitmask) {
                validBits = (n == 63) ? -1L : ((1L << (n + 1)) - 1L);
                for (int k = 0; k < n; k++) {
                    int id = pIds[k];
                    if (id >= 0) {
                        reqSegMasks[id] |= (1L << (k + 1));
                    }
                }
            }

            String decision = "DENY by default";
            for (ParsedRule rule : parsedRules) {
                if (rule.hasDoubleStar()) {
                    if (n < rule.minSegments()) continue;
                } else {
                    if (n != rule.minSegments()) continue;
                }

                int pType = rule.principalType();
                if (pType == PRINCIPAL_USER) {
                    if (!req.user().equals(rule.principalName())) continue;
                } else if (pType == PRINCIPAL_GROUP) {
                    if (!req.groups().contains(rule.principalName())) continue;
                }

                Set<String> ruleActions = rule.actions();
                if (ruleActions != null && !ruleActions.contains(req.action())) {
                    continue;
                }

                boolean matched = useBitmask
                        ? matchesBitmask(rule.resourceIds(), n, validBits, reqSegMasks)
                        : matchesFallback(rule.resourceIds(), pIds);
                if (matched) {
                    decision = rule.decisionString();
                    break;
                }
            }

            if (useBitmask) {
                for (int k = 0; k < n; k++) {
                    int id = pIds[k];
                    if (id >= 0) {
                        reqSegMasks[id] = 0L;
                    }
                }
            }

            decisions.add(decision);
        }

        return decisions;
    }

    private static boolean matchesBitmask(int[] rIds, int n, long validBits, long[] reqSegMasks) {
        long state = 1L;
        for (int rSeg : rIds) {
            if (rSeg == DOUBLE_STAR) {
                state = -(state & -state) & validBits;
            } else if (rSeg == STAR) {
                state = (state << 1) & validBits;
            } else {
                state = (state << 1) & reqSegMasks[rSeg];
            }
            if (state == 0L) {
                return false;
            }
        }
        return (state & (1L << n)) != 0L;
    }

    private static boolean matchesFallback(int[] rIds, int[] pIds) {
        int n = pIds.length;
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int rSeg : rIds) {
            if (rSeg == DOUBLE_STAR) {
                for (int k = 1; k <= n; k++) {
                    if (dp[k - 1]) {
                        dp[k] = true;
                    }
                }
            } else if (rSeg == STAR) {
                for (int k = n; k >= 1; k--) {
                    dp[k] = dp[k - 1];
                }
                dp[0] = false;
            } else {
                for (int k = n; k >= 1; k--) {
                    dp[k] = dp[k - 1] && (pIds[k - 1] == rSeg);
                }
                dp[0] = false;
            }
        }
        return dp[n];
    }

    private static Set<String> parseRuleActions(String actionStr, int ruleIndex) {
        if (actionStr.isEmpty()) {
            throw new IllegalArgumentException(
                    "rule " + ruleIndex + ": bad action " + pyRepr(actionStr));
        }
        Set<String> set = new HashSet<>();
        int start = 0;
        while (true) {
            int comma = actionStr.indexOf(',', start);
            String word = (comma == -1)
                    ? actionStr.substring(start)
                    : actionStr.substring(start, comma);
            if (!isActionWord(word)) {
                throw new IllegalArgumentException(
                        "rule " + ruleIndex + ": bad action " + pyRepr(actionStr));
            }
            set.add(word);
            if (comma == -1) {
                break;
            }
            start = comma + 1;
        }
        return set;
    }

    private static int[] parseRuleResource(
            String resource, Map<String, Integer> segmentToId, int ruleIndex) {
        if (resource.isEmpty() || resource.charAt(0) != '/') {
            throw new IllegalArgumentException(
                    "rule " + ruleIndex + ": bad resource " + pyRepr(resource));
        }
        if (resource.length() == 1) {
            return new int[0];
        }
        List<Integer> list = new ArrayList<>();
        int start = 1;
        while (true) {
            int slash = resource.indexOf('/', start);
            String seg = (slash == -1)
                    ? resource.substring(start)
                    : resource.substring(start, slash);
            if ("*".equals(seg)) {
                list.add(STAR);
            } else if ("**".equals(seg)) {
                list.add(DOUBLE_STAR);
            } else if (isPathSegment(seg)) {
                int id = segmentToId.computeIfAbsent(seg, k -> segmentToId.size());
                list.add(id);
            } else {
                throw new IllegalArgumentException(
                        "rule " + ruleIndex + ": bad resource " + pyRepr(resource));
            }
            if (slash == -1) {
                break;
            }
            start = slash + 1;
        }
        int[] arr = new int[list.size()];
        for (int i = 0; i < arr.length; i++) {
            arr[i] = list.get(i);
        }
        return arr;
    }

    private static int[] parseRequestPath(
            String path, Map<String, Integer> segmentToId, int reqIndex) {
        if (path == null || path.isEmpty() || path.charAt(0) != '/') {
            throw new IllegalArgumentException(
                    "request " + reqIndex + ": bad path " + pyRepr(path));
        }
        if (path.length() == 1) {
            return new int[0];
        }
        List<Integer> list = new ArrayList<>();
        int start = 1;
        while (true) {
            int slash = path.indexOf('/', start);
            String seg = (slash == -1)
                    ? path.substring(start)
                    : path.substring(start, slash);
            if (!isPathSegment(seg)) {
                throw new IllegalArgumentException(
                        "request " + reqIndex + ": bad path " + pyRepr(path));
            }
            list.add(segmentToId.getOrDefault(seg, UNKNOWN_LITERAL));
            if (slash == -1) {
                break;
            }
            start = slash + 1;
        }
        int[] arr = new int[list.size()];
        for (int i = 0; i < arr.length; i++) {
            arr[i] = list.get(i);
        }
        return arr;
    }

    private static List<String> splitPythonWhitespace(String s) {
        List<String> fields = new ArrayList<>(4);
        int len = s.length();
        int i = 0;
        while (i < len) {
            while (i < len) {
                int cp = s.codePointAt(i);
                if (!isPythonSpace(cp)) {
                    break;
                }
                i += Character.charCount(cp);
            }
            if (i >= len) {
                break;
            }
            int start = i;
            while (i < len) {
                int cp = s.codePointAt(i);
                if (isPythonSpace(cp)) {
                    break;
                }
                i += Character.charCount(cp);
            }
            fields.add(s.substring(start, i));
        }
        return fields;
    }

    private static boolean isPythonSpace(int cp) {
        return Character.isWhitespace(cp) || Character.isSpaceChar(cp) || cp == 0x0085;
    }

    private static boolean isName(String s) {
        if (s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')) {
                return false;
            }
        }
        return true;
    }

    private static boolean isActionWord(String s) {
        if (s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!(c >= 'a' && c <= 'z')) {
                return false;
            }
        }
        return true;
    }

    private static boolean isPathSegment(String s) {
        if (s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'a' && c <= 'z')
                    || (c >= '0' && c <= '9')
                    || c == '.'
                    || c == '_'
                    || c == '-')) {
                return false;
            }
        }
        return true;
    }

    private static String pyRepr(String s) {
        return (s == null) ? "None" : "'" + s + "'";
    }
}

#include <algorithm>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <string_view>
#include <tuple>
#include <utility>
#include <vector>

namespace {

bool is_py_ascii_space(unsigned char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' ||
           c == '\x0b' || c == '\x0c' ||
           c == '\x1c' || c == '\x1d' || c == '\x1e' || c == '\x1f';
}

std::vector<std::string_view> split_whitespace(std::string_view s) {
    std::vector<std::string_view> fields;
    std::size_t n = s.size();
    std::size_t i = 0;
    while (i < n) {
        while (i < n && is_py_ascii_space(static_cast<unsigned char>(s[i]))) {
            ++i;
        }
        if (i >= n) {
            break;
        }
        std::size_t start = i;
        while (i < n && !is_py_ascii_space(static_cast<unsigned char>(s[i]))) {
            ++i;
        }
        fields.push_back(s.substr(start, i - start));
    }
    return fields;
}

bool is_valid_name(std::string_view s) {
    if (s.empty()) {
        return false;
    }
    for (unsigned char c : s) {
        if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')) {
            return false;
        }
    }
    return true;
}

bool is_valid_action_word(std::string_view s) {
    if (s.empty()) {
        return false;
    }
    for (unsigned char c : s) {
        if (!(c >= 'a' && c <= 'z')) {
            return false;
        }
    }
    return true;
}

bool is_valid_literal_segment(std::string_view s) {
    if (s.empty()) {
        return false;
    }
    for (unsigned char c : s) {
        if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') ||
              c == '.' || c == '_' || c == '-')) {
            return false;
        }
    }
    return true;
}

enum class PrincipalKind { Any, Group, User };
enum class SegKind { Literal, Star, DoubleStar };

struct Segment {
    SegKind kind;
    std::string text;
};

struct ParsedRule {
    int index = 0;
    bool is_deny = false;
    PrincipalKind principal_kind = PrincipalKind::Any;
    std::string principal_name;
    bool any_action = false;
    std::vector<std::string> actions;
    std::vector<Segment> segments;
    std::size_t min_path_segments = 0;
    bool has_double_star = false;
    int specificity_l = 0;
    int specificity_p = 0;
    int specificity_a = 0;
};

struct ParsedRequest {
    std::string user;
    std::vector<std::string> groups;
    std::string action;
    std::vector<std::string_view> path_segments;
};

ParsedRule parse_and_validate_rule(int idx, const std::string& rule_str) {
    auto fields = split_whitespace(rule_str);
    if (fields.size() != 4) {
        throw std::invalid_argument("rule " + std::to_string(idx) +
                                    ": expected 4 fields, got " +
                                    std::to_string(fields.size()));
    }

    ParsedRule rule;
    rule.index = idx;

    // 1. EFFECT
    std::string_view effect = fields[0];
    if (effect == "ALLOW") {
        rule.is_deny = false;
    } else if (effect == "DENY") {
        rule.is_deny = true;
    } else {
        throw std::invalid_argument("rule " + std::to_string(idx) + ": bad effect");
    }

    // 2. PRINCIPAL
    std::string_view principal = fields[1];
    if (principal == "*") {
        rule.principal_kind = PrincipalKind::Any;
        rule.specificity_p = 0;
    } else if (principal.starts_with("user:")) {
        std::string_view name = principal.substr(5);
        if (!is_valid_name(name)) {
            throw std::invalid_argument("rule " + std::to_string(idx) + ": bad principal");
        }
        rule.principal_kind = PrincipalKind::User;
        rule.principal_name = std::string(name);
        rule.specificity_p = 2;
    } else if (principal.starts_with("group:")) {
        std::string_view name = principal.substr(6);
        if (!is_valid_name(name)) {
            throw std::invalid_argument("rule " + std::to_string(idx) + ": bad principal");
        }
        rule.principal_kind = PrincipalKind::Group;
        rule.principal_name = std::string(name);
        rule.specificity_p = 1;
    } else {
        throw std::invalid_argument("rule " + std::to_string(idx) + ": bad principal");
    }

    // 3. ACTION
    std::string_view action = fields[2];
    if (action == "*") {
        rule.any_action = true;
        rule.specificity_a = 0;
    } else {
        if (action.empty()) {
            throw std::invalid_argument("rule " + std::to_string(idx) + ": bad action");
        }
        rule.any_action = false;
        rule.specificity_a = 1;
        std::size_t pos = 0;
        while (true) {
            std::size_t comma = action.find(',', pos);
            std::string_view word = (comma == std::string_view::npos)
                                        ? action.substr(pos)
                                        : action.substr(pos, comma - pos);
            if (!is_valid_action_word(word)) {
                throw std::invalid_argument("rule " + std::to_string(idx) + ": bad action");
            }
            rule.actions.emplace_back(word);
            if (comma == std::string_view::npos) {
                break;
            }
            pos = comma + 1;
        }
        std::sort(rule.actions.begin(), rule.actions.end());
        rule.actions.erase(std::unique(rule.actions.begin(), rule.actions.end()),
                           rule.actions.end());
    }

    // 4. RESOURCE
    std::string_view resource = fields[3];
    if (resource == "/") {
        // Root resource: zero segments.
    } else {
        if (resource.size() < 2 || resource.front() != '/' || resource.back() == '/') {
            throw std::invalid_argument("rule " + std::to_string(idx) + ": bad resource");
        }
        std::string_view rest = resource.substr(1);
        std::size_t pos = 0;
        while (true) {
            std::size_t slash = rest.find('/', pos);
            std::string_view seg = (slash == std::string_view::npos)
                                       ? rest.substr(pos)
                                       : rest.substr(pos, slash - pos);
            if (seg == "*") {
                rule.segments.push_back(Segment{SegKind::Star, {}});
                ++rule.min_path_segments;
            } else if (seg == "**") {
                rule.segments.push_back(Segment{SegKind::DoubleStar, {}});
                rule.has_double_star = true;
            } else if (is_valid_literal_segment(seg)) {
                rule.segments.push_back(Segment{SegKind::Literal, std::string(seg)});
                ++rule.min_path_segments;
                ++rule.specificity_l;
            } else {
                throw std::invalid_argument("rule " + std::to_string(idx) + ": bad resource");
            }
            if (slash == std::string_view::npos) {
                break;
            }
            pos = slash + 1;
        }
    }

    return rule;
}

ParsedRequest parse_and_validate_request(
    int idx,
    const std::tuple<std::string, std::vector<std::string>, std::string, std::string>& req_tuple) {
    const auto& [user, groups, action, path] = req_tuple;

    if (!is_valid_name(user)) {
        throw std::invalid_argument("request " + std::to_string(idx) + ": bad user");
    }

    for (const auto& g : groups) {
        if (!is_valid_name(g)) {
            throw std::invalid_argument("request " + std::to_string(idx) + ": bad groups");
        }
    }

    if (!is_valid_action_word(action)) {
        throw std::invalid_argument("request " + std::to_string(idx) + ": bad action");
    }

    ParsedRequest req;
    if (path == "/") {
        // Root path: zero segments.
    } else {
        if (path.size() < 2 || path.front() != '/' || path.back() == '/') {
            throw std::invalid_argument("request " + std::to_string(idx) + ": bad path");
        }
        std::string_view rest = std::string_view(path).substr(1);
        std::size_t pos = 0;
        while (true) {
            std::size_t slash = rest.find('/', pos);
            std::string_view seg = (slash == std::string_view::npos)
                                       ? rest.substr(pos)
                                       : rest.substr(pos, slash - pos);
            if (!is_valid_literal_segment(seg)) {
                throw std::invalid_argument("request " + std::to_string(idx) + ": bad path");
            }
            req.path_segments.push_back(seg);
            if (slash == std::string_view::npos) {
                break;
            }
            pos = slash + 1;
        }
    }

    req.user = user;
    req.groups = groups;
    std::sort(req.groups.begin(), req.groups.end());
    req.groups.erase(std::unique(req.groups.begin(), req.groups.end()), req.groups.end());
    req.action = action;

    return req;
}

bool resource_matches(const ParsedRule& rule,
                      const std::vector<std::string_view>& path_segs,
                      std::vector<std::uint8_t>& dp,
                      std::vector<std::uint8_t>& next_dp) {
    const std::size_t n = path_segs.size();
    const std::size_t m = rule.segments.size();

    if (n < rule.min_path_segments) {
        return false;
    }
    if (!rule.has_double_star) {
        if (m != n) {
            return false;
        }
        for (std::size_t i = 0; i < m; ++i) {
            if (rule.segments[i].kind == SegKind::Literal &&
                rule.segments[i].text != path_segs[i]) {
                return false;
            }
        }
        return true;
    }

    dp.assign(n + 1, 0);
    next_dp.assign(n + 1, 0);
    dp[0] = 1;

    for (std::size_t i = 0; i < m; ++i) {
        const auto& seg = rule.segments[i];
        if (seg.kind == SegKind::DoubleStar) {
            std::uint8_t running = 0;
            for (std::size_t j = 0; j <= n; ++j) {
                running |= dp[j];
                next_dp[j] = running;
            }
        } else if (seg.kind == SegKind::Star) {
            next_dp[0] = 0;
            for (std::size_t j = 1; j <= n; ++j) {
                next_dp[j] = dp[j - 1];
            }
        } else {
            next_dp[0] = 0;
            for (std::size_t j = 1; j <= n; ++j) {
                next_dp[j] = (dp[j - 1] && seg.text == path_segs[j - 1]) ? 1 : 0;
            }
        }
        dp.swap(next_dp);
    }

    return dp[n] != 0;
}

bool rule_matches(const ParsedRule& rule,
                  const ParsedRequest& req,
                  std::vector<std::uint8_t>& dp,
                  std::vector<std::uint8_t>& next_dp) {
    switch (rule.principal_kind) {
        case PrincipalKind::Any:
            break;
        case PrincipalKind::User:
            if (rule.principal_name != req.user) {
                return false;
            }
            break;
        case PrincipalKind::Group:
            if (!std::binary_search(req.groups.begin(), req.groups.end(), rule.principal_name)) {
                return false;
            }
            break;
    }

    if (!rule.any_action) {
        if (!std::binary_search(rule.actions.begin(), rule.actions.end(), req.action)) {
            return false;
        }
    }

    return resource_matches(rule, req.path_segments, dp, next_dp);
}

}  // namespace

std::vector<std::string> evaluate_access(
    const std::vector<std::string>& rules,
    const std::vector<std::tuple<std::string, std::vector<std::string>, std::string, std::string>>&
        requests) {
    std::vector<ParsedRule> parsed_rules;
    parsed_rules.reserve(rules.size());
    for (std::size_t i = 0; i < rules.size(); ++i) {
        parsed_rules.push_back(parse_and_validate_rule(static_cast<int>(i), rules[i]));
    }

    std::vector<ParsedRequest> parsed_requests;
    parsed_requests.reserve(requests.size());
    for (std::size_t j = 0; j < requests.size(); ++j) {
        parsed_requests.push_back(parse_and_validate_request(static_cast<int>(j), requests[j]));
    }

    // Sort rules by descending priority:
    // specificity (L, P, A) descending, then DENY over ALLOW, then smaller index first.
    std::sort(parsed_rules.begin(), parsed_rules.end(), [](const ParsedRule& a, const ParsedRule& b) {
        return std::make_tuple(a.specificity_l, a.specificity_p, a.specificity_a,
                               a.is_deny ? 1 : 0, -a.index) >
               std::make_tuple(b.specificity_l, b.specificity_p, b.specificity_a,
                               b.is_deny ? 1 : 0, -b.index);
    });

    std::vector<std::string> decisions;
    decisions.reserve(parsed_requests.size());

    std::vector<std::uint8_t> dp;
    std::vector<std::uint8_t> next_dp;

    for (const auto& req : parsed_requests) {
        const ParsedRule* best = nullptr;
        for (const auto& rule : parsed_rules) {
            if (rule_matches(rule, req, dp, next_dp)) {
                best = &rule;
                break;
            }
        }
        if (best == nullptr) {
            decisions.emplace_back("DENY by default");
        } else if (best->is_deny) {
            decisions.push_back("DENY by rule " + std::to_string(best->index));
        } else {
            decisions.push_back("ALLOW by rule " + std::to_string(best->index));
        }
    }

    return decisions;
}

const PY_WS_TRIM_RE =
  /^[\t\n\x0b\x0c\r\x1c-\x1f \x85\xa0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+|[\t\n\x0b\x0c\r\x1c-\x1f \x85\xa0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+$/g;
const PY_WS_SPLIT_RE =
  /[\t\n\x0b\x0c\r\x1c-\x1f \x85\xa0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+/;

const NAME_RE = /^[a-z0-9_]+$/;
const ACTION_WORD_RE = /^[a-z]+$/;
const ACTION_LIST_RE = /^[a-z]+(?:,[a-z]+)*$/;
const SEGMENT_RE = /^[a-z0-9._-]+$/;

interface ParsedRule {
  index: number;
  isDeny: boolean;
  decision: string;
  specificity: number;
  principalKind: 0 | 1 | 2; // 0 = *, 1 = group, 2 = user
  principalName: string;
  actionAny: boolean;
  actionSingle: string | null;
  actionSet: Set<string> | null;
  pattern: string[];
  hasDoubleStar: boolean;
  minSegments: number;
}

interface ParsedRequest {
  user: string;
  groups: string[];
  groupSet: Set<string> | null;
  action: string;
  segments: string[];
}

function pyRepr(val: unknown): string {
  if (typeof val === "string") {
    if (val.includes("'") && !val.includes('"')) {
      return `"${val.replace(/\\/g, "\\\\")}"`;
    }
    return `'${val.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
  }
  if (val === null) return "None";
  if (typeof val === "boolean") return val ? "True" : "False";
  return String(val);
}

function pySplitWhitespace(s: string): string[] {
  const trimmed = s.replace(PY_WS_TRIM_RE, "");
  if (trimmed.length === 0) return [];
  return trimmed.split(PY_WS_SPLIT_RE);
}

function matchResource(
  pat: string[],
  hasDoubleStar: boolean,
  minSegments: number,
  seg: string[],
): boolean {
  const n = seg.length;
  if (n < minSegments) return false;
  const m = pat.length;

  if (!hasDoubleStar) {
    if (m !== n) return false;
    for (let i = 0; i < m; i++) {
      const p = pat[i]!;
      if (p !== "*" && p !== seg[i]) return false;
    }
    return true;
  }

  let pi = 0;
  let si = 0;
  let starPi = -1;
  let starSi = 0;

  while (si < n) {
    if (pi < m && (pat[pi] === "*" || pat[pi] === seg[si])) {
      pi++;
      si++;
    } else if (pi < m && pat[pi] === "**") {
      starPi = pi;
      starSi = si;
      pi++;
    } else if (starPi !== -1) {
      pi = starPi + 1;
      starSi++;
      si = starSi;
    } else {
      return false;
    }
  }

  while (pi < m && pat[pi] === "**") {
    pi++;
  }

  return pi === m;
}

export function evaluateAccess(
  rules: string[],
  requests: [string, string[], string, string][],
): string[] {
  if (!Array.isArray(rules)) {
    throw new Error("rules must be a list");
  }
  if (!Array.isArray(requests)) {
    throw new Error("requests must be a list");
  }

  const parsedRules: ParsedRule[] = [];

  for (let i = 0; i < rules.length; i++) {
    const rawRule: unknown = rules[i];
    if (typeof rawRule !== "string") {
      throw new Error(`rule ${i}: not a str`);
    }

    const fields = pySplitWhitespace(rawRule);
    if (fields.length !== 4) {
      throw new Error(`rule ${i}: expected 4 fields, got ${fields.length}`);
    }

    const effect = fields[0]!;
    const principal = fields[1]!;
    const action = fields[2]!;
    const resource = fields[3]!;

    if (effect !== "ALLOW" && effect !== "DENY") {
      throw new Error(`rule ${i}: bad effect ${pyRepr(effect)}`);
    }

    let principalKind: 0 | 1 | 2;
    let principalName = "";
    if (principal === "*") {
      principalKind = 0;
    } else if (principal.startsWith("user:")) {
      const name = principal.slice(5);
      if (!NAME_RE.test(name)) {
        throw new Error(`rule ${i}: bad principal ${pyRepr(principal)}`);
      }
      principalKind = 2;
      principalName = name;
    } else if (principal.startsWith("group:")) {
      const name = principal.slice(6);
      if (!NAME_RE.test(name)) {
        throw new Error(`rule ${i}: bad principal ${pyRepr(principal)}`);
      }
      principalKind = 1;
      principalName = name;
    } else {
      throw new Error(`rule ${i}: bad principal ${pyRepr(principal)}`);
    }

    let actionAny = false;
    let actionSingle: string | null = null;
    let actionSet: Set<string> | null = null;
    let actionSpec = 0;
    if (action === "*") {
      actionAny = true;
      actionSpec = 0;
    } else if (ACTION_LIST_RE.test(action)) {
      actionSpec = 1;
      if (action.includes(",")) {
        actionSet = new Set(action.split(","));
      } else {
        actionSingle = action;
      }
    } else {
      throw new Error(`rule ${i}: bad action ${pyRepr(action)}`);
    }

    let literalCount = 0;
    let minSegments = 0;
    let hasDoubleStar = false;
    const collapsedPattern: string[] = [];

    if (resource !== "/") {
      if (resource.length < 2 || !resource.startsWith("/")) {
        throw new Error(`rule ${i}: bad resource ${pyRepr(resource)}`);
      }
      const rawSegments = resource.slice(1).split("/");
      for (let k = 0; k < rawSegments.length; k++) {
        const seg = rawSegments[k]!;
        if (seg === "**") {
          hasDoubleStar = true;
          if (
            collapsedPattern.length === 0 ||
            collapsedPattern[collapsedPattern.length - 1] !== "**"
          ) {
            collapsedPattern.push("**");
          }
        } else if (seg === "*") {
          minSegments++;
          collapsedPattern.push("*");
        } else if (SEGMENT_RE.test(seg)) {
          literalCount++;
          minSegments++;
          collapsedPattern.push(seg);
        } else {
          throw new Error(`rule ${i}: bad resource ${pyRepr(resource)}`);
        }
      }
    }

    const isDeny = effect === "DENY";
    const specificity = literalCount * 6 + principalKind * 2 + actionSpec;

    parsedRules.push({
      index: i,
      isDeny,
      decision: `${effect} by rule ${i}`,
      specificity,
      principalKind,
      principalName,
      actionAny,
      actionSingle,
      actionSet,
      pattern: collapsedPattern,
      hasDoubleStar,
      minSegments,
    });
  }

  const parsedRequests: ParsedRequest[] = [];

  for (let j = 0; j < requests.length; j++) {
    const rawReq: unknown = requests[j];
    if (!Array.isArray(rawReq) || rawReq.length !== 4) {
      throw new Error(`request ${j}: expected 4-tuple`);
    }

    const user: unknown = rawReq[0];
    const groups: unknown = rawReq[1];
    const action: unknown = rawReq[2];
    const path: unknown = rawReq[3];

    if (typeof user !== "string" || !NAME_RE.test(user)) {
      throw new Error(`request ${j}: bad user ${pyRepr(user)}`);
    }

    if (!Array.isArray(groups)) {
      throw new Error(`request ${j}: bad groups`);
    }
    const validGroups: string[] = [];
    for (let k = 0; k < groups.length; k++) {
      if (!(k in groups)) {
        throw new Error(`request ${j}: bad groups`);
      }
      const g: unknown = groups[k];
      if (typeof g !== "string" || !NAME_RE.test(g)) {
        throw new Error(`request ${j}: bad groups`);
      }
      validGroups.push(g);
    }

    if (typeof action !== "string" || !ACTION_WORD_RE.test(action)) {
      throw new Error(`request ${j}: bad action ${pyRepr(action)}`);
    }

    if (typeof path !== "string") {
      throw new Error(`request ${j}: bad path ${pyRepr(path)}`);
    }

    let pathSegments: string[];
    if (path === "/") {
      pathSegments = [];
    } else {
      if (path.length < 2 || !path.startsWith("/")) {
        throw new Error(`request ${j}: bad path ${pyRepr(path)}`);
      }
      pathSegments = path.slice(1).split("/");
      for (let k = 0; k < pathSegments.length; k++) {
        if (!SEGMENT_RE.test(pathSegments[k]!)) {
          throw new Error(`request ${j}: bad path ${pyRepr(path)}`);
        }
      }
    }

    parsedRequests.push({
      user,
      groups: validGroups,
      groupSet: validGroups.length > 4 ? new Set(validGroups) : null,
      action,
      segments: pathSegments,
    });
  }

  parsedRules.sort((a, b) => {
    if (a.specificity !== b.specificity) {
      return b.specificity - a.specificity;
    }
    if (a.isDeny !== b.isDeny) {
      return a.isDeny ? -1 : 1;
    }
    return a.index - b.index;
  });

  const ruleCount = parsedRules.length;
  const decisions: string[] = new Array(parsedRequests.length);

  for (let j = 0; j < parsedRequests.length; j++) {
    const req = parsedRequests[j]!;
    let decision = "DENY by default";

    for (let r = 0; r < ruleCount; r++) {
      const rule = parsedRules[r]!;

      if (rule.principalKind === 2) {
        if (rule.principalName !== req.user) continue;
      } else if (rule.principalKind === 1) {
        if (req.groupSet !== null) {
          if (!req.groupSet.has(rule.principalName)) continue;
        } else {
          if (!req.groups.includes(rule.principalName)) continue;
        }
      }

      if (!rule.actionAny) {
        if (rule.actionSingle !== null) {
          if (rule.actionSingle !== req.action) continue;
        } else if (!rule.actionSet!.has(req.action)) {
          continue;
        }
      }

      if (
        matchResource(
          rule.pattern,
          rule.hasDoubleStar,
          rule.minSegments,
          req.segments,
        )
      ) {
        decision = rule.decision;
        break;
      }
    }

    decisions[j] = decision;
  }

  return decisions;
}

package main

import (
	"errors"
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"unicode"
)

type Tuple1 struct {
	F0 string
	F1 string
	F2 string
	F3 string
}

var (
	openingRe = regexp.MustCompile(`\A-?(0|[1-9][0-9]{0,8})\.[0-9]{2}\z`)
	amountRe  = regexp.MustCompile(`\A(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?\z`)
)

func parseCents(s string) int64 {
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	var intPart, fracPart string
	if idx := strings.IndexByte(s, '.'); idx >= 0 {
		intPart = s[:idx]
		fracPart = s[idx+1:]
	} else {
		intPart = s
	}
	for len(fracPart) < 2 {
		fracPart += "0"
	}
	dollars, _ := strconv.ParseInt(intPart, 10, 64)
	cents, _ := strconv.ParseInt(fracPart, 10, 64)
	total := dollars*100 + cents
	if neg {
		total = -total
	}
	return total
}

func isValidDate(s string) bool {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return false
	}
	for i := 0; i < 10; i++ {
		if i == 4 || i == 7 {
			continue
		}
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	year, _ := strconv.Atoi(s[0:4])
	month, _ := strconv.Atoi(s[5:7])
	day, _ := strconv.Atoi(s[8:10])
	if year < 1900 || year > 2999 || month < 1 || month > 12 || day < 1 {
		return false
	}
	daysInMonth := [13]int{0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}
	if year%4 == 0 && (year%100 != 0 || year%400 == 0) {
		daysInMonth[2] = 29
	}
	return day <= daysInMonth[month]
}

func isValidMemo(s string) bool {
	for _, r := range s {
		if r < 32 || r == 127 {
			return false
		}
	}
	return len(strings.FieldsFunc(s, unicode.IsSpace)) > 0
}

func formatMoney(cents int64) string {
	neg := cents < 0
	if neg {
		cents = -cents
	}
	dollars := cents / 100
	rem := cents % 100

	dStr := strconv.FormatInt(dollars, 10)
	var b strings.Builder
	if neg {
		b.WriteByte('-')
	}
	n := len(dStr)
	for i := 0; i < n; i++ {
		if i > 0 && (n-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteByte(dStr[i])
	}
	fmt.Fprintf(&b, ".%02d", rem)
	return b.String()
}

func formatMemo(memo string) string {
	norm := strings.Join(strings.FieldsFunc(memo, unicode.IsSpace), " ")
	runes := []rune(norm)
	if len(runes) > 20 {
		runes = append(runes[:19:19], '~')
	}
	if len(runes) < 20 {
		return string(runes) + strings.Repeat(" ", 20-len(runes))
	}
	return string(runes)
}

func padLeft(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return strings.Repeat(" ", width-len(s)) + s
}

func renderEntryLine(date, kind string, amtCents int64, memo string, balCents int64) string {
	memoCol := formatMemo(memo)
	sign := "-"
	if kind == "credit" {
		sign = "+"
	}
	amtCol := padLeft(sign+formatMoney(amtCents), 14)
	balCol := padLeft(formatMoney(balCents), 15)
	flag := ""
	if balCents < 0 {
		flag = " OD"
	}
	return fmt.Sprintf("%s  %s  %s  %s%s", date, memoCol, amtCol, balCol, flag)
}

func RenderStatement(opening string, entries []Tuple1) ([]string, error) {
	if !openingRe.MatchString(opening) {
		return nil, fmt.Errorf("opening: bad amount %q", opening)
	}

	type parsedEntry struct {
		date   string
		kind   string
		amount int64
		memo   string
	}

	parsed := make([]parsedEntry, len(entries))
	for i, e := range entries {
		date, kind, amountStr, memo := e.F0, e.F1, e.F2, e.F3
		if !isValidDate(date) {
			return nil, fmt.Errorf("entry %d: bad date %q", i, date)
		}
		if i > 0 && date < entries[i-1].F0 {
			return nil, fmt.Errorf("entry %d: date out of order", i)
		}
		if kind != "credit" && kind != "debit" && kind != "fee" {
			return nil, fmt.Errorf("entry %d: bad kind %q", i, kind)
		}
		if !amountRe.MatchString(amountStr) {
			return nil, fmt.Errorf("entry %d: bad amount %q", i, amountStr)
		}
		amtCents := parseCents(amountStr)
		if amtCents == 0 {
			return nil, fmt.Errorf("entry %d: bad amount %q", i, amountStr)
		}
		if !isValidMemo(memo) {
			return nil, errors.New(fmt.Sprintf("entry %d: bad memo", i))
		}
		parsed[i] = parsedEntry{
			date:   date,
			kind:   kind,
			amount: amtCents,
			memo:   memo,
		}
	}

	bal := parseCents(opening)
	lines := make([]string, 0, len(parsed)+3)
	lines = append(lines, "Opening balance: "+formatMoney(bal))

	odDates := make(map[string]bool)
	var credits, debits, fees int64

	for _, e := range parsed {
		switch e.kind {
		case "credit":
			bal += e.amount
			credits++
		case "debit":
			bal -= e.amount
			debits++
		case "fee":
			bal -= e.amount
			fees++
		}
		lines = append(lines, renderEntryLine(e.date, e.kind, e.amount, e.memo, bal))

		if e.kind == "debit" && bal < 0 && !odDates[e.date] {
			odDates[e.date] = true
			const odFee = 2500
			bal -= odFee
			fees++
			lines = append(lines, renderEntryLine(e.date, "fee", odFee, "OVERDRAFT FEE", bal))
		}
	}

	lines = append(lines, "Closing balance: "+formatMoney(bal))
	lines = append(lines, fmt.Sprintf("Credits: %d  Debits: %d  Fees: %d", credits, debits, fees))
	return lines, nil
}

import java.util.*;
import java.util.regex.Pattern;

public final class Solution {
    public record Tuple1(String f0, String f1, String f2, String f3) {}

    private static final Pattern OPENING_PATTERN =
            Pattern.compile("-?(0|[1-9][0-9]{0,8})\\.[0-9]{2}");
    private static final Pattern AMOUNT_PATTERN =
            Pattern.compile("(0|[1-9][0-9]{0,8})(\\.[0-9]{1,2})?");

    private static final long AUTO_OVERDRAFT_FEE_CENTS = 2500L;
    private static final String AUTO_OVERDRAFT_MEMO_COL = formatMemoColumn("OVERDRAFT FEE");

    private enum Kind {
        CREDIT, DEBIT, FEE
    }

    private record ValidatedEntry(String date, Kind kind, long amountCents, String memoCol) {}

    public static List<String> renderStatement(String opening, List<Tuple1> entries) {
        if (opening == null) {
            throw new IllegalArgumentException("opening must be a str");
        }
        if (!OPENING_PATTERN.matcher(opening).matches()) {
            throw new IllegalArgumentException("opening: bad amount '" + opening + "'");
        }
        if (entries == null) {
            throw new IllegalArgumentException("entries must be a list");
        }

        long openingCents = parseOpening(opening);
        List<ValidatedEntry> validated = new ArrayList<>(entries.size());
        String prevDate = null;

        for (int i = 0; i < entries.size(); i++) {
            Tuple1 entry = entries.get(i);
            if (entry == null) {
                throw new IllegalArgumentException("entry " + i + ": expected 4-tuple");
            }

            String date = entry.f0();
            if (date == null || !isValidDate(date)) {
                throw new IllegalArgumentException("entry " + i + ": bad date");
            }
            if (prevDate != null && date.compareTo(prevDate) < 0) {
                throw new IllegalArgumentException("entry " + i + ": date out of order");
            }
            prevDate = date;

            String kindStr = entry.f1();
            if (kindStr == null) {
                throw new IllegalArgumentException("entry " + i + ": bad kind");
            }
            Kind kind = switch (kindStr) {
                case "credit" -> Kind.CREDIT;
                case "debit" -> Kind.DEBIT;
                case "fee" -> Kind.FEE;
                default -> throw new IllegalArgumentException("entry " + i + ": bad kind");
            };

            String amountStr = entry.f2();
            if (amountStr == null || !AMOUNT_PATTERN.matcher(amountStr).matches()) {
                throw new IllegalArgumentException("entry " + i + ": bad amount");
            }
            long amountCents = parseAmount(amountStr);
            if (amountCents == 0L) {
                throw new IllegalArgumentException("entry " + i + ": bad amount");
            }

            String memoCol = normalizeAndValidateMemo(entry.f3(), i);
            validated.add(new ValidatedEntry(date, kind, amountCents, memoCol));
        }

        List<String> lines = new ArrayList<>(validated.size() + 3);
        lines.add("Opening balance: " + formatMoney(openingCents));

        long balance = openingCents;
        long credits = 0;
        long debits = 0;
        long fees = 0;
        Set<String> autoFeeDates = new HashSet<>();

        for (ValidatedEntry ve : validated) {
            switch (ve.kind()) {
                case CREDIT -> {
                    balance += ve.amountCents();
                    credits++;
                }
                case DEBIT -> {
                    balance -= ve.amountCents();
                    debits++;
                }
                case FEE -> {
                    balance -= ve.amountCents();
                    fees++;
                }
            }

            lines.add(renderEntryLine(ve.date(), ve.memoCol(), ve.kind(), ve.amountCents(), balance));

            if (ve.kind() == Kind.DEBIT && balance < 0 && autoFeeDates.add(ve.date())) {
                balance -= AUTO_OVERDRAFT_FEE_CENTS;
                fees++;
                lines.add(renderEntryLine(
                        ve.date(), AUTO_OVERDRAFT_MEMO_COL, Kind.FEE, AUTO_OVERDRAFT_FEE_CENTS, balance));
            }
        }

        lines.add("Closing balance: " + formatMoney(balance));
        lines.add("Credits: " + credits + "  Debits: " + debits + "  Fees: " + fees);
        return lines;
    }

    private static String renderEntryLine(
            String date, String memoCol, Kind kind, long amountCents, long balanceAfter) {
        String sign = (kind == Kind.CREDIT) ? "+" : "-";
        String amtCol = padLeft(sign + formatMoney(amountCents), 14);
        String balCol = padLeft(formatMoney(balanceAfter), 15);
        String flag = (balanceAfter < 0) ? " OD" : "";
        return date + "  " + memoCol + "  " + amtCol + "  " + balCol + flag;
    }

    private static long parseOpening(String opening) {
        boolean neg = opening.charAt(0) == '-';
        int start = neg ? 1 : 0;
        int dot = opening.indexOf('.');
        long dollars = Long.parseLong(opening.substring(start, dot));
        long cents = Long.parseLong(opening.substring(dot + 1));
        long total = dollars * 100L + cents;
        return (neg && total != 0L) ? -total : total;
    }

    private static long parseAmount(String amount) {
        int dot = amount.indexOf('.');
        if (dot < 0) {
            return Long.parseLong(amount) * 100L;
        }
        long dollars = Long.parseLong(amount.substring(0, dot));
        String frac = amount.substring(dot + 1);
        long cents = Long.parseLong(frac);
        if (frac.length() == 1) {
            cents *= 10L;
        }
        return dollars * 100L + cents;
    }

    private static boolean isValidDate(String s) {
        if (s.length() != 10 || s.charAt(4) != '-' || s.charAt(7) != '-') {
            return false;
        }
        for (int i = 0; i < 10; i++) {
            if (i == 4 || i == 7) {
                continue;
            }
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        int year = Integer.parseInt(s.substring(0, 4));
        int month = Integer.parseInt(s.substring(5, 7));
        int day = Integer.parseInt(s.substring(8, 10));
        if (year < 1900 || year > 2999 || month < 1 || month > 12) {
            return false;
        }
        int maxDay = switch (month) {
            case 4, 6, 9, 11 -> 30;
            case 2 -> isLeapYear(year) ? 29 : 28;
            default -> 31;
        };
        return day >= 1 && day <= maxDay;
    }

    private static boolean isLeapYear(int year) {
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }

    private static String normalizeAndValidateMemo(String memo, int index) {
        if (memo == null) {
            throw new IllegalArgumentException("entry " + index + ": bad memo");
        }
        StringBuilder normalized = new StringBuilder();
        boolean inWord = false;
        boolean hasWord = false;
        for (int p = 0; p < memo.length(); ) {
            int cp = memo.codePointAt(p);
            p += Character.charCount(cp);
            if (cp < 32 || cp == 127) {
                throw new IllegalArgumentException("entry " + index + ": bad memo");
            }
            if (isPythonSpace(cp)) {
                inWord = false;
            } else {
                if (!inWord && hasWord) {
                    normalized.append(' ');
                }
                normalized.appendCodePoint(cp);
                inWord = true;
                hasWord = true;
            }
        }
        if (!hasWord) {
            throw new IllegalArgumentException("entry " + index + ": bad memo");
        }
        return formatMemoColumn(normalized.toString());
    }

    private static boolean isPythonSpace(int cp) {
        if (Character.isSpaceChar(cp) || Character.isWhitespace(cp)) {
            return true;
        }
        byte dir = Character.getDirectionality(cp);
        return dir == Character.DIRECTIONALITY_WHITESPACE
                || dir == Character.DIRECTIONALITY_PARAGRAPH_SEPARATOR
                || dir == Character.DIRECTIONALITY_SEGMENT_SEPARATOR;
    }

    private static String formatMemoColumn(String norm) {
        int cpCount = norm.codePointCount(0, norm.length());
        if (cpCount > 20) {
            int endIdx = norm.offsetByCodePoints(0, 19);
            return norm.substring(0, endIdx) + "~";
        }
        if (cpCount == 20) {
            return norm;
        }
        StringBuilder sb = new StringBuilder(norm.length() + (20 - cpCount));
        sb.append(norm);
        for (int i = cpCount; i < 20; i++) {
            sb.append(' ');
        }
        return sb.toString();
    }

    private static String formatMoney(long cents) {
        StringBuilder sb = new StringBuilder();
        if (cents < 0) {
            sb.append('-');
            cents = -cents;
        }
        long dollars = cents / 100L;
        long rem = cents % 100L;
        String dStr = Long.toString(dollars);
        int len = dStr.length();
        for (int i = 0; i < len; i++) {
            if (i > 0 && (len - i) % 3 == 0) {
                sb.append(',');
            }
            sb.append(dStr.charAt(i));
        }
        sb.append('.');
        if (rem < 10) {
            sb.append('0');
        }
        sb.append(rem);
        return sb.toString();
    }

    private static String padLeft(String s, int width) {
        if (s.length() >= width) {
            return s;
        }
        StringBuilder sb = new StringBuilder(width);
        for (int i = s.length(); i < width; i++) {
            sb.append(' ');
        }
        sb.append(s);
        return sb.toString();
    }
}

#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <tuple>
#include <unordered_set>
#include <vector>

namespace {

bool is_ascii_digit(char c) {
    return c >= '0' && c <= '9';
}

bool is_py_whitespace(char32_t cp) {
    switch (cp) {
        case 0x0009:
        case 0x000A:
        case 0x000B:
        case 0x000C:
        case 0x000D:
        case 0x001C:
        case 0x001D:
        case 0x001E:
        case 0x001F:
        case 0x0020:
        case 0x0085:
        case 0x00A0:
        case 0x1680:
        case 0x2000:
        case 0x2001:
        case 0x2002:
        case 0x2003:
        case 0x2004:
        case 0x2005:
        case 0x2006:
        case 0x2007:
        case 0x2008:
        case 0x2009:
        case 0x200A:
        case 0x2028:
        case 0x2029:
        case 0x202F:
        case 0x205F:
        case 0x3000:
            return true;
        default:
            return false;
    }
}

bool decode_utf8(const std::string& s, std::u32string& out) {
    out.clear();
    out.reserve(s.size());
    size_t i = 0;
    const size_t n = s.size();
    while (i < n) {
        unsigned char b0 = static_cast<unsigned char>(s[i]);
        if (b0 < 0x80) {
            out.push_back(static_cast<char32_t>(b0));
            i += 1;
        } else if ((b0 & 0xE0) == 0xC0) {
            if (i + 1 >= n) return false;
            unsigned char b1 = static_cast<unsigned char>(s[i + 1]);
            if ((b1 & 0xC0) != 0x80) return false;
            char32_t cp = (static_cast<char32_t>(b0 & 0x1F) << 6) |
                          static_cast<char32_t>(b1 & 0x3F);
            if (cp < 0x80) return false;
            out.push_back(cp);
            i += 2;
        } else if ((b0 & 0xF0) == 0xE0) {
            if (i + 2 >= n) return false;
            unsigned char b1 = static_cast<unsigned char>(s[i + 1]);
            unsigned char b2 = static_cast<unsigned char>(s[i + 2]);
            if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80) return false;
            char32_t cp = (static_cast<char32_t>(b0 & 0x0F) << 12) |
                          (static_cast<char32_t>(b1 & 0x3F) << 6) |
                          static_cast<char32_t>(b2 & 0x3F);
            if (cp < 0x800 || (cp >= 0xD800 && cp <= 0xDFFF)) return false;
            out.push_back(cp);
            i += 3;
        } else if ((b0 & 0xF8) == 0xF0) {
            if (i + 3 >= n) return false;
            unsigned char b1 = static_cast<unsigned char>(s[i + 1]);
            unsigned char b2 = static_cast<unsigned char>(s[i + 2]);
            unsigned char b3 = static_cast<unsigned char>(s[i + 3]);
            if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) return false;
            char32_t cp = (static_cast<char32_t>(b0 & 0x07) << 18) |
                          (static_cast<char32_t>(b1 & 0x3F) << 12) |
                          (static_cast<char32_t>(b2 & 0x3F) << 6) |
                          static_cast<char32_t>(b3 & 0x3F);
            if (cp < 0x10000 || cp > 0x10FFFF) return false;
            out.push_back(cp);
            i += 4;
        } else {
            return false;
        }
    }
    return true;
}

std::string encode_utf8(const std::u32string& s) {
    std::string out;
    out.reserve(s.size());
    for (char32_t cp : s) {
        if (cp < 0x80) {
            out.push_back(static_cast<char>(cp));
        } else if (cp < 0x800) {
            out.push_back(static_cast<char>(0xC0 | (cp >> 6)));
            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
        } else if (cp < 0x10000) {
            out.push_back(static_cast<char>(0xE0 | (cp >> 12)));
            out.push_back(static_cast<char>(0x80 | ((cp >> 6) & 0x3F)));
            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
        } else {
            out.push_back(static_cast<char>(0xF0 | (cp >> 18)));
            out.push_back(static_cast<char>(0x80 | ((cp >> 12) & 0x3F)));
            out.push_back(static_cast<char>(0x80 | ((cp >> 6) & 0x3F)));
            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
        }
    }
    return out;
}

std::string py_repr(const std::string& s) {
    bool has_single = s.find('\'') != std::string::npos;
    bool has_double = s.find('"') != std::string::npos;
    char quote = (has_single && !has_double) ? '"' : '\'';

    static const char hex_digits[] = "0123456789abcdef";
    std::string res;
    res.push_back(quote);
    for (unsigned char c : s) {
        if (c == '\\') {
            res += "\\\\";
        } else if (c == static_cast<unsigned char>(quote)) {
            res.push_back('\\');
            res.push_back(quote);
        } else if (c == '\t') {
            res += "\\t";
        } else if (c == '\n') {
            res += "\\n";
        } else if (c == '\r') {
            res += "\\r";
        } else if (c < 32 || c == 127) {
            res += "\\x";
            res.push_back(hex_digits[c >> 4]);
            res.push_back(hex_digits[c & 0x0F]);
        } else {
            res.push_back(static_cast<char>(c));
        }
    }
    res.push_back(quote);
    return res;
}

bool parse_opening(const std::string& s, long long& out_cents) {
    size_t pos = 0;
    bool neg = false;
    if (pos < s.size() && s[pos] == '-') {
        neg = true;
        ++pos;
    }
    size_t dot = s.find('.', pos);
    if (dot == std::string::npos) return false;
    if (s.size() - dot != 3) return false;
    if (!is_ascii_digit(s[dot + 1]) || !is_ascii_digit(s[dot + 2])) return false;

    size_t int_len = dot - pos;
    if (int_len == 0 || int_len > 9) return false;
    if (int_len > 1 && s[pos] == '0') return false;

    long long dollars = 0;
    for (size_t k = pos; k < dot; ++k) {
        if (!is_ascii_digit(s[k])) return false;
        dollars = dollars * 10 + (s[k] - '0');
    }
    long long cents = (s[dot + 1] - '0') * 10 + (s[dot + 2] - '0');
    long long total = dollars * 100 + cents;
    out_cents = (neg && total != 0) ? -total : total;
    return true;
}

bool validate_date(const std::string& d) {
    if (d.size() != 10 || d[4] != '-' || d[7] != '-') return false;
    const int digit_positions[8] = {0, 1, 2, 3, 5, 6, 8, 9};
    for (int idx : digit_positions) {
        if (!is_ascii_digit(d[idx])) return false;
    }
    int year = (d[0] - '0') * 1000 + (d[1] - '0') * 100 + (d[2] - '0') * 10 + (d[3] - '0');
    int month = (d[5] - '0') * 10 + (d[6] - '0');
    int day = (d[8] - '0') * 10 + (d[9] - '0');

    if (year < 1900 || year > 2999) return false;
    if (month < 1 || month > 12) return false;

    bool leap = (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
    int days_in_month[12] = {31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    return day >= 1 && day <= days_in_month[month - 1];
}

bool parse_entry_amount(const std::string& s, long long& out_cents) {
    if (s.empty()) return false;
    size_t dot = s.find('.');
    size_t int_end = (dot == std::string::npos) ? s.size() : dot;
    if (int_end == 0 || int_end > 9) return false;
    if (int_end > 1 && s[0] == '0') return false;

    long long dollars = 0;
    for (size_t k = 0; k < int_end; ++k) {
        if (!is_ascii_digit(s[k])) return false;
        dollars = dollars * 10 + (s[k] - '0');
    }

    long long cents = 0;
    if (dot != std::string::npos) {
        size_t frac_len = s.size() - dot - 1;
        if (frac_len < 1 || frac_len > 2) return false;
        if (!is_ascii_digit(s[dot + 1])) return false;
        if (frac_len == 1) {
            cents = (s[dot + 1] - '0') * 10;
        } else {
            if (!is_ascii_digit(s[dot + 2])) return false;
            cents = (s[dot + 1] - '0') * 10 + (s[dot + 2] - '0');
        }
    }

    long long total = dollars * 100 + cents;
    if (total == 0) return false;
    out_cents = total;
    return true;
}

bool parse_and_format_memo(const std::string& memo, std::string& formatted_memo) {
    std::u32string cps;
    if (!decode_utf8(memo, cps)) return false;

    for (char32_t cp : cps) {
        if (cp < 32 || cp == 127) return false;
    }

    std::u32string norm;
    size_t i = 0;
    const size_t n = cps.size();
    while (i < n) {
        while (i < n && is_py_whitespace(cps[i])) ++i;
        if (i >= n) break;
        if (!norm.empty()) norm.push_back(U' ');
        while (i < n && !is_py_whitespace(cps[i])) {
            norm.push_back(cps[i]);
            ++i;
        }
    }

    if (norm.empty()) return false;

    if (norm.size() > 20) {
        norm.resize(19);
        norm.push_back(U'~');
    } else if (norm.size() < 20) {
        norm.append(20 - norm.size(), U' ');
    }

    formatted_memo = encode_utf8(norm);
    return true;
}

std::string format_money(long long x) {
    bool neg = x < 0;
    unsigned long long abs_x = neg ? (0ULL - static_cast<unsigned long long>(x))
                                   : static_cast<unsigned long long>(x);
    unsigned long long dollars = abs_x / 100;
    unsigned long long cents = abs_x % 100;

    std::string d_str = std::to_string(dollars);
    std::string grouped;
    grouped.reserve(d_str.size() + d_str.size() / 3);
    for (size_t i = 0; i < d_str.size(); ++i) {
        if (i > 0 && (d_str.size() - i) % 3 == 0) {
            grouped.push_back(',');
        }
        grouped.push_back(d_str[i]);
    }

    std::string res;
    if (neg) res.push_back('-');
    res += grouped;
    res.push_back('.');
    res.push_back(static_cast<char>('0' + (cents / 10)));
    res.push_back(static_cast<char>('0' + (cents % 10)));
    return res;
}

std::string rjust(const std::string& s, size_t width) {
    if (s.size() >= width) return s;
    return std::string(width - s.size(), ' ') + s;
}

enum class Kind { Credit, Debit, Fee };

struct ParsedEntry {
    std::string date;
    Kind kind;
    long long amount_cents;
    std::string formatted_memo;
};

std::string render_entry_line(const std::string& date,
                              const std::string& formatted_memo,
                              Kind kind,
                              long long amount_cents,
                              long long balance_after) {
    char sign = (kind == Kind::Credit) ? '+' : '-';
    std::string amt = rjust(sign + format_money(amount_cents), 14);
    std::string bal = rjust(format_money(balance_after), 15);

    std::string line;
    line.reserve(72);
    line += date;
    line += "  ";
    line += formatted_memo;
    line += "  ";
    line += amt;
    line += "  ";
    line += bal;
    if (balance_after < 0) {
        line += " OD";
    }
    return line;
}

}  // namespace

std::vector<std::string> render_statement(
    const std::string& opening,
    const std::vector<std::tuple<std::string, std::string, std::string, std::string>>& entries) {

    long long opening_cents = 0;
    if (!parse_opening(opening, opening_cents)) {
        throw std::invalid_argument("opening: bad amount " + py_repr(opening));
    }

    std::vector<ParsedEntry> parsed;
    parsed.reserve(entries.size());

    for (size_t i = 0; i < entries.size(); ++i) {
        const auto& [date, kind_str, amount_str, memo_str] = entries[i];

        if (!validate_date(date)) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad date " + py_repr(date));
        }

        if (i > 0 && date < parsed[i - 1].date) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": date out of order");
        }

        Kind kind;
        if (kind_str == "credit") {
            kind = Kind::Credit;
        } else if (kind_str == "debit") {
            kind = Kind::Debit;
        } else if (kind_str == "fee") {
            kind = Kind::Fee;
        } else {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad kind " + py_repr(kind_str));
        }

        long long amount_cents = 0;
        if (!parse_entry_amount(amount_str, amount_cents)) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad amount " + py_repr(amount_str));
        }

        std::string formatted_memo;
        if (!parse_and_format_memo(memo_str, formatted_memo)) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad memo");
        }

        parsed.push_back(ParsedEntry{date, kind, amount_cents, std::move(formatted_memo)});
    }

    std::vector<std::string> output;
    output.reserve(parsed.size() + 3);
    output.push_back("Opening balance: " + format_money(opening_cents));

    long long balance = opening_cents;
    long long credits_count = 0;
    long long debits_count = 0;
    long long fees_count = 0;
    std::unordered_set<std::string> auto_fee_dates;
    const std::string overdraft_memo = "OVERDRAFT FEE       ";
    constexpr long long kOverdraftFeeCents = 2500;

    for (const auto& entry : parsed) {
        if (entry.kind == Kind::Credit) {
            balance += entry.amount_cents;
            ++credits_count;
        } else if (entry.kind == Kind::Debit) {
            balance -= entry.amount_cents;
            ++debits_count;
        } else {
            balance -= entry.amount_cents;
            ++fees_count;
        }

        output.push_back(render_entry_line(entry.date, entry.formatted_memo, entry.kind,
                                           entry.amount_cents, balance));

        if (entry.kind == Kind::Debit && balance < 0 &&
            auto_fee_dates.find(entry.date) == auto_fee_dates.end()) {
            auto_fee_dates.insert(entry.date);
            balance -= kOverdraftFeeCents;
            ++fees_count;
            output.push_back(render_entry_line(entry.date, overdraft_memo, Kind::Fee,
                                               kOverdraftFeeCents, balance));
        }
    }

    output.push_back("Closing balance: " + format_money(balance));
    output.push_back("Credits: " + std::to_string(credits_count) +
                     "  Debits: " + std::to_string(debits_count) +
                     "  Fees: " + std::to_string(fees_count));

    return output;
}

const OPENING_RE = /^-?(0|[1-9][0-9]{0,8})\.[0-9]{2}$/;
const DATE_RE = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
const AMOUNT_RE = /^(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?$/;
const PY_WS_LEAD_RE = /^[\u0020\u0085\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+/;
const PY_WS_TRAIL_RE = /[\u0020\u0085\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+$/;
const PY_WS_RUN_RE = /[\u0020\u0085\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+/g;

type EntryKind = "credit" | "debit" | "fee";

interface ParsedEntry {
  date: string;
  kind: EntryKind;
  cents: bigint;
  normalizedMemo: string;
}

function pyRepr(val: unknown): string {
  if (typeof val === "string") {
    return `'${val.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
  }
  return String(val);
}

function isValidGregorianDate(date: string): boolean {
  if (!DATE_RE.test(date)) {
    return false;
  }
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  const day = Number(date.slice(8, 10));

  if (year < 1900 || year > 2999) {
    return false;
  }
  if (month < 1 || month > 12) {
    return false;
  }

  let maxDay = 31;
  if (month === 4 || month === 6 || month === 9 || month === 11) {
    maxDay = 30;
  } else if (month === 2) {
    const isLeap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
    maxDay = isLeap ? 29 : 28;
  }

  return day >= 1 && day <= maxDay;
}

function parseOpeningCents(opening: string): bigint {
  const negative = opening.startsWith("-");
  const unsigned = negative ? opening.slice(1) : opening;
  const [intPart, decPart] = unsigned.split(".");
  const cents = BigInt(intPart) * 100n + BigInt(decPart);
  return negative && cents > 0n ? -cents : cents;
}

function parseEntryAmountCents(amount: string): bigint {
  const parts = amount.split(".");
  const intPart = parts[0];
  const decPart = (parts[1] ?? "").padEnd(2, "0");
  return BigInt(intPart) * 100n + BigInt(decPart);
}

function normalizeAndValidateMemo(memo: unknown, index: number): string {
  if (typeof memo !== "string") {
    throw new Error(`entry ${index}: bad memo`);
  }
  for (let i = 0; i < memo.length; i++) {
    const code = memo.charCodeAt(i);
    if (code < 32 || code === 127) {
      throw new Error(`entry ${index}: bad memo`);
    }
  }
  const normalized = memo
    .replace(PY_WS_LEAD_RE, "")
    .replace(PY_WS_TRAIL_RE, "")
    .replace(PY_WS_RUN_RE, " ");
  if (normalized.length === 0) {
    throw new Error(`entry ${index}: bad memo`);
  }
  return normalized;
}

function formatMoney(cents: bigint): string {
  const negative = cents < 0n;
  const abs = negative ? -cents : cents;
  const intStr = (abs / 100n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  const decStr = (abs % 100n).toString().padStart(2, "0");
  return `${negative ? "-" : ""}${intStr}.${decStr}`;
}

function formatMemoColumn(normalizedMemo: string): string {
  const codePoints = Array.from(normalizedMemo);
  if (codePoints.length > 20) {
    return codePoints.slice(0, 19).join("") + "~";
  }
  return normalizedMemo + " ".repeat(20 - codePoints.length);
}

export function renderStatement(
  opening: string,
  entries: [string, string, string, string][],
): string[] {
  if (typeof opening !== "string") {
    throw new Error("opening must be a str");
  }
  if (!OPENING_RE.test(opening)) {
    throw new Error(`opening: bad amount ${pyRepr(opening)}`);
  }
  if (!Array.isArray(entries)) {
    throw new Error("entries must be a list");
  }

  const parsedEntries: ParsedEntry[] = [];
  let prevDate = "";

  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i] as unknown;
    if (!Array.isArray(entry) || entry.length !== 4) {
      throw new Error(`entry ${i}: expected 4-tuple`);
    }

    const [date, kind, amount, memo] = entry as [unknown, unknown, unknown, unknown];

    if (typeof date !== "string" || !isValidGregorianDate(date)) {
      throw new Error(`entry ${i}: bad date ${pyRepr(date)}`);
    }
    if (i > 0 && date < prevDate) {
      throw new Error(`entry ${i}: date out of order`);
    }
    prevDate = date;

    if (typeof kind !== "string" || (kind !== "credit" && kind !== "debit" && kind !== "fee")) {
      throw new Error(`entry ${i}: bad kind ${pyRepr(kind)}`);
    }

    if (typeof amount !== "string" || !AMOUNT_RE.test(amount)) {
      throw new Error(`entry ${i}: bad amount ${pyRepr(amount)}`);
    }
    const cents = parseEntryAmountCents(amount);
    if (cents === 0n) {
      throw new Error(`entry ${i}: bad amount ${pyRepr(amount)}`);
    }

    const normalizedMemo = normalizeAndValidateMemo(memo, i);

    parsedEntries.push({
      date,
      kind,
      cents,
      normalizedMemo,
    });
  }

  let balance = parseOpeningCents(opening);
  const lines: string[] = [`Opening balance: ${formatMoney(balance)}`];
  const overdraftDates = new Set<string>();

  let creditCount = 0;
  let debitCount = 0;
  let feeCount = 0;

  const applyAndRender = (item: ParsedEntry): void => {
    if (item.kind === "credit") {
      balance += item.cents;
      creditCount++;
    } else if (item.kind === "debit") {
      balance -= item.cents;
      debitCount++;
    } else {
      balance -= item.cents;
      feeCount++;
    }

    const memoCol = formatMemoColumn(item.normalizedMemo);
    const sign = item.kind === "credit" ? "+" : "-";
    const amtCol = `${sign}${formatMoney(item.cents)}`.padStart(14, " ");
    const balCol = formatMoney(balance).padStart(15, " ");
    const flag = balance < 0n ? " OD" : "";

    lines.push(`${item.date}  ${memoCol}  ${amtCol}  ${balCol}${flag}`);
  };

  for (const item of parsedEntries) {
    applyAndRender(item);

    if (item.kind === "debit" && balance < 0n && !overdraftDates.has(item.date)) {
      overdraftDates.add(item.date);
      applyAndRender({
        date: item.date,
        kind: "fee",
        cents: 2500n,
        normalizedMemo: "OVERDRAFT FEE",
      });
    }
  }

  lines.push(`Closing balance: ${formatMoney(balance)}`);
  lines.push(`Credits: ${creditCount}  Debits: ${debitCount}  Fees: ${feeCount}`);

  return lines;
}

package main

import (
	"errors"
	"fmt"
	"strings"
)

type version struct {
	x, y, z string
	isRC    bool
	rc      string
	raw     string
}

type clauseKind int

const (
	clauseAny clauseKind = iota
	clauseEq
	clauseNe
	clauseGt
	clauseGe
	clauseLt
	clauseLe
	clauseMajorWild
	clauseMinorWild
	clauseCompatible
)

type parsedClause struct {
	kind clauseKind
	ver  version
	x, y string
}

type alternative struct {
	allowRC bool
	clauses []parsedClause
}

func trimSpaces(s string) string {
	return strings.Trim(s, " ")
}

func isValidUint(s string) bool {
	if len(s) == 0 {
		return false
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func cmpUint(a, b string) int {
	if len(a) != len(b) {
		if len(a) < len(b) {
			return -1
		}
		return 1
	}
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func parseVersion(s string) (version, bool) {
	xyz := s
	isRC := false
	rc := ""
	if idx := strings.IndexByte(s, '~'); idx != -1 {
		xyz = s[:idx]
		rest := s[idx+1:]
		if !strings.HasPrefix(rest, "rc") {
			return version{}, false
		}
		rc = rest[2:]
		if !isValidUint(rc) || rc == "0" {
			return version{}, false
		}
		isRC = true
	}
	parts := strings.Split(xyz, ".")
	if len(parts) != 3 {
		return version{}, false
	}
	if !isValidUint(parts[0]) || !isValidUint(parts[1]) || !isValidUint(parts[2]) {
		return version{}, false
	}
	return version{
		x:    parts[0],
		y:    parts[1],
		z:    parts[2],
		isRC: isRC,
		rc:   rc,
		raw:  s,
	}, true
}

func cmpVersion(a, b version) int {
	if c := cmpUint(a.x, b.x); c != 0 {
		return c
	}
	if c := cmpUint(a.y, b.y); c != 0 {
		return c
	}
	if c := cmpUint(a.z, b.z); c != 0 {
		return c
	}
	if a.isRC != b.isRC {
		if a.isRC {
			return -1
		}
		return 1
	}
	if a.isRC {
		return cmpUint(a.rc, b.rc)
	}
	return 0
}

func parseClause(s string) (parsedClause, bool) {
	if s == "*" {
		return parsedClause{kind: clauseAny}, true
	}
	if strings.HasPrefix(s, "!=") {
		v, ok := parseVersion(s[2:])
		if !ok {
			return parsedClause{}, false
		}
		return parsedClause{kind: clauseNe, ver: v}, true
	}
	if strings.HasPrefix(s, ">=") {
		v, ok := parseVersion(s[2:])
		if !ok {
			return parsedClause{}, false
		}
		return parsedClause{kind: clauseGe, ver: v}, true
	}
	if strings.HasPrefix(s, "<=") {
		v, ok := parseVersion(s[2:])
		if !ok {
			return parsedClause{}, false
		}
		return parsedClause{kind: clauseLe, ver: v}, true
	}
	if strings.HasPrefix(s, ">") {
		v, ok := parseVersion(s[1:])
		if !ok {
			return parsedClause{}, false
		}
		return parsedClause{kind: clauseGt, ver: v}, true
	}
	if strings.HasPrefix(s, "<") {
		v, ok := parseVersion(s[1:])
		if !ok {
			return parsedClause{}, false
		}
		return parsedClause{kind: clauseLt, ver: v}, true
	}
	if strings.HasPrefix(s, "=") {
		v, ok := parseVersion(s[1:])
		if !ok {
			return parsedClause{}, false
		}
		return parsedClause{kind: clauseEq, ver: v}, true
	}
	if strings.HasPrefix(s, "@") {
		parts := strings.Split(s[1:], ".")
		if len(parts) != 2 || !isValidUint(parts[0]) || !isValidUint(parts[1]) {
			return parsedClause{}, false
		}
		return parsedClause{kind: clauseCompatible, x: parts[0], y: parts[1]}, true
	}
	if strings.HasSuffix(s, ".*") {
		prefix := s[:len(s)-2]
		parts := strings.Split(prefix, ".")
		if len(parts) == 1 && isValidUint(parts[0]) {
			return parsedClause{kind: clauseMajorWild, x: parts[0]}, true
		}
		if len(parts) == 2 && isValidUint(parts[0]) && isValidUint(parts[1]) {
			return parsedClause{kind: clauseMinorWild, x: parts[0], y: parts[1]}, true
		}
		return parsedClause{}, false
	}
	v, ok := parseVersion(s)
	if !ok {
		return parsedClause{}, false
	}
	return parsedClause{kind: clauseEq, ver: v}, true
}

func matchClause(c parsedClause, v version) bool {
	switch c.kind {
	case clauseAny:
		return true
	case clauseEq:
		return cmpVersion(v, c.ver) == 0
	case clauseNe:
		return cmpVersion(v, c.ver) != 0
	case clauseGt:
		return cmpVersion(v, c.ver) > 0
	case clauseGe:
		return cmpVersion(v, c.ver) >= 0
	case clauseLt:
		return cmpVersion(v, c.ver) < 0
	case clauseLe:
		return cmpVersion(v, c.ver) <= 0
	case clauseMajorWild:
		return v.x == c.x
	case clauseMinorWild:
		return v.x == c.x && v.y == c.y
	case clauseCompatible:
		return v.x == c.x && cmpUint(v.y, c.y) >= 0
	default:
		return false
	}
}

func matchAlternative(alt alternative, v version) bool {
	if v.isRC && !alt.allowRC {
		return false
	}
	for _, c := range alt.clauses {
		if !matchClause(c, v) {
			return false
		}
	}
	return true
}

func PickVersion(available []string, constraint string) (*string, error) {
	versions := make([]version, len(available))
	for i, s := range available {
		v, ok := parseVersion(s)
		if !ok {
			return nil, fmt.Errorf("invalid version at index %d: %q", i, s)
		}
		versions[i] = v
	}

	if trimSpaces(constraint) == "" {
		return nil, errors.New("empty constraint")
	}

	rawAlts := strings.Split(constraint, "|")
	alts := make([]alternative, len(rawAlts))
	for i, rawAlt := range rawAlts {
		altIdx := i + 1
		s := trimSpaces(rawAlt)
		allowRC := false
		if strings.HasPrefix(s, "?") {
			allowRC = true
			s = trimSpaces(s[1:])
		}
		if s == "" {
			return nil, fmt.Errorf("alternative %d is empty", altIdx)
		}

		rawClauses := strings.Split(s, ",")
		clauses := make([]parsedClause, len(rawClauses))
		for j, rawClause := range rawClauses {
			clauseIdx := j + 1
			cText := trimSpaces(rawClause)
			pc, ok := parseClause(cText)
			if !ok {
				return nil, fmt.Errorf("alternative %d, clause %d: invalid clause %q", altIdx, clauseIdx, cText)
			}
			clauses[j] = pc
		}
		alts[i] = alternative{
			allowRC: allowRC,
			clauses: clauses,
		}
	}

	var best *version
	for i := range versions {
		v := &versions[i]
		matched := false
		for _, alt := range alts {
			if matchAlternative(alt, *v) {
				matched = true
				break
			}
		}
		if matched {
			if best == nil || cmpVersion(*v, *best) > 0 {
				best = v
			}
		}
	}

	if best == nil {
		return nil, nil
	}
	res := best.raw
	return &res, nil
}

import java.util.*;

public final class Solution {
    private Solution() {}

    public static String pickVersion(List<String> available, String constraint) {
        if (available == null) {
            throw new IllegalArgumentException("available must be a list");
        }
        List<ParsedVersion> versions = new ArrayList<>(available.size());
        for (int i = 0; i < available.size(); i++) {
            String el = available.get(i);
            if (el == null) {
                throw new IllegalArgumentException("invalid version at index " + i + ": null");
            }
            ParsedVersion pv = parseVersion(el);
            if (pv == null) {
                throw new IllegalArgumentException("invalid version at index " + i + ": '" + el + "'");
            }
            versions.add(pv);
        }

        if (constraint == null) {
            throw new IllegalArgumentException("constraint must be a str");
        }
        if (trimSpaces(constraint).isEmpty()) {
            throw new IllegalArgumentException("empty constraint");
        }

        String[] rawAlts = constraint.split("\\|", -1);
        List<Alternative> alternatives = new ArrayList<>(rawAlts.length);
        for (int a = 0; a < rawAlts.length; a++) {
            int altNum = a + 1;
            String altStr = trimSpaces(rawAlts[a]);
            boolean allowsRc = false;
            if (altStr.startsWith("?")) {
                allowsRc = true;
                altStr = trimSpaces(altStr.substring(1));
            }
            if (altStr.isEmpty()) {
                throw new IllegalArgumentException("alternative " + altNum + " is empty");
            }

            String[] rawClauses = altStr.split(",", -1);
            List<Clause> clauses = new ArrayList<>(rawClauses.length);
            for (int c = 0; c < rawClauses.length; c++) {
                int clauseNum = c + 1;
                String clauseStr = trimSpaces(rawClauses[c]);
                Clause clause = parseClause(clauseStr);
                if (clause == null) {
                    throw new IllegalArgumentException(
                            "alternative " + altNum + ", clause " + clauseNum + ": invalid clause '" + clauseStr + "'");
                }
                clauses.add(clause);
            }
            alternatives.add(new Alternative(allowsRc, clauses));
        }

        ParsedVersion best = null;
        for (ParsedVersion v : versions) {
            if (matchesConstraint(v, alternatives)) {
                if (best == null || v.compareTo(best) > 0) {
                    best = v;
                }
            }
        }
        return best == null ? null : best.raw();
    }

    private static boolean matchesConstraint(ParsedVersion v, List<Alternative> alternatives) {
        for (Alternative alt : alternatives) {
            if (alt.matches(v)) {
                return true;
            }
        }
        return false;
    }

    private static String trimSpaces(String s) {
        int start = 0;
        int end = s.length();
        while (start < end && s.charAt(start) == ' ') {
            start++;
        }
        while (end > start && s.charAt(end - 1) == ' ') {
            end--;
        }
        return s.substring(start, end);
    }

    private static boolean isValidUint(String s) {
        if (s.isEmpty()) {
            return false;
        }
        if (s.equals("0")) {
            return true;
        }
        return isValidPosInt(s);
    }

    private static boolean isValidPosInt(String s) {
        if (s.isEmpty()) {
            return false;
        }
        char first = s.charAt(0);
        if (first < '1' || first > '9') {
            return false;
        }
        for (int i = 1; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch < '0' || ch > '9') {
                return false;
            }
        }
        return true;
    }

    private static int compareNum(String a, String b) {
        if (a.length() != b.length()) {
            return Integer.compare(a.length(), b.length());
        }
        return a.compareTo(b);
    }

    private record ParsedVersion(String raw, String x, String y, String z, String rc)
            implements Comparable<ParsedVersion> {
        boolean isRc() {
            return rc != null;
        }

        @Override
        public int compareTo(ParsedVersion o) {
            int cmp = compareNum(this.x, o.x);
            if (cmp != 0) return cmp;
            cmp = compareNum(this.y, o.y);
            if (cmp != 0) return cmp;
            cmp = compareNum(this.z, o.z);
            if (cmp != 0) return cmp;
            if (this.rc == null && o.rc == null) return 0;
            if (this.rc == null) return 1;
            if (o.rc == null) return -1;
            return compareNum(this.rc, o.rc);
        }
    }

    private static ParsedVersion parseVersion(String s) {
        if (s.isEmpty()) {
            return null;
        }
        int tildeIdx = s.indexOf('~');
        String xyzPart;
        String rcPart = null;
        if (tildeIdx == -1) {
            xyzPart = s;
        } else {
            if (!s.startsWith("~rc", tildeIdx)) {
                return null;
            }
            xyzPart = s.substring(0, tildeIdx);
            rcPart = s.substring(tildeIdx + 3);
            if (!isValidPosInt(rcPart)) {
                return null;
            }
        }

        String[] parts = xyzPart.split("\\.", -1);
        if (parts.length != 3) {
            return null;
        }
        if (!isValidUint(parts[0]) || !isValidUint(parts[1]) || !isValidUint(parts[2])) {
            return null;
        }
        return new ParsedVersion(s, parts[0], parts[1], parts[2], rcPart);
    }

    @FunctionalInterface
    private interface Clause {
        boolean matches(ParsedVersion v);
    }

    private record Alternative(boolean allowsRc, List<Clause> clauses) {
        boolean matches(ParsedVersion v) {
            if (v.isRc() && !allowsRc) {
                return false;
            }
            for (Clause c : clauses) {
                if (!c.matches(v)) {
                    return false;
                }
            }
            return true;
        }
    }

    private static Clause parseClause(String s) {
        if (s.isEmpty()) {
            return null;
        }
        if (s.equals("*")) {
            return v -> true;
        }
        if (s.startsWith("!=")) {
            ParsedVersion target = parseVersion(s.substring(2));
            return target == null ? null : v -> v.compareTo(target) != 0;
        }
        if (s.startsWith(">=")) {
            ParsedVersion target = parseVersion(s.substring(2));
            return target == null ? null : v -> v.compareTo(target) >= 0;
        }
        if (s.startsWith("<=")) {
            ParsedVersion target = parseVersion(s.substring(2));
            return target == null ? null : v -> v.compareTo(target) <= 0;
        }
        if (s.startsWith(">")) {
            ParsedVersion target = parseVersion(s.substring(1));
            return target == null ? null : v -> v.compareTo(target) > 0;
        }
        if (s.startsWith("<")) {
            ParsedVersion target = parseVersion(s.substring(1));
            return target == null ? null : v -> v.compareTo(target) < 0;
        }
        if (s.startsWith("=")) {
            ParsedVersion target = parseVersion(s.substring(1));
            return target == null ? null : v -> v.compareTo(target) == 0;
        }
        if (s.startsWith("@")) {
            String[] parts = s.substring(1).split("\\.", -1);
            if (parts.length != 2 || !isValidUint(parts[0]) || !isValidUint(parts[1])) {
                return null;
            }
            String x = parts[0];
            String y = parts[1];
            return v -> v.x().equals(x) && compareNum(v.y(), y) >= 0;
        }
        if (s.endsWith(".*")) {
            String[] parts = s.split("\\.", -1);
            if (parts.length == 2 && parts[1].equals("*") && isValidUint(parts[0])) {
                String x = parts[0];
                return v -> v.x().equals(x);
            }
            if (parts.length == 3 && parts[2].equals("*") && isValidUint(parts[0]) && isValidUint(parts[1])) {
                String x = parts[0];
                String y = parts[1];
                return v -> v.x().equals(x) && v.y().equals(y);
            }
            return null;
        }
        ParsedVersion target = parseVersion(s);
        return target == null ? null : v -> v.compareTo(target) == 0;
    }
}

#include <compare>
#include <optional>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

namespace {

struct IntStr {
    std::string s;

    friend std::strong_ordering operator<=>(const IntStr& a, const IntStr& b) noexcept {
        if (a.s.size() != b.s.size()) {
            return a.s.size() < b.s.size() ? std::strong_ordering::less
                                           : std::strong_ordering::greater;
        }
        int cmp = a.s.compare(b.s);
        if (cmp < 0) return std::strong_ordering::less;
        if (cmp > 0) return std::strong_ordering::greater;
        return std::strong_ordering::equal;
    }

    friend bool operator==(const IntStr& a, const IntStr& b) noexcept = default;
};

struct Version {
    IntStr x;
    IntStr y;
    IntStr z;
    bool is_plain;  // false for release candidate (~rcN), true for plain release
    IntStr rc;      // N if !is_plain, empty otherwise

    friend std::strong_ordering operator<=>(const Version& a, const Version& b) noexcept {
        if (auto cmp = a.x <=> b.x; cmp != 0) return cmp;
        if (auto cmp = a.y <=> b.y; cmp != 0) return cmp;
        if (auto cmp = a.z <=> b.z; cmp != 0) return cmp;
        if (a.is_plain != b.is_plain) {
            return a.is_plain ? std::strong_ordering::greater : std::strong_ordering::less;
        }
        return a.rc <=> b.rc;
    }

    friend bool operator==(const Version& a, const Version& b) noexcept = default;
};

enum class ClauseKind {
    Any,
    Eq,
    Ne,
    Gt,
    Ge,
    Lt,
    Le,
    MajorWild,
    MajorMinorWild,
    Compat
};

struct Clause {
    ClauseKind kind;
    Version ver;
    IntStr x;
    IntStr y;
};

struct Alternative {
    bool allow_rc = false;
    std::vector<Clause> clauses;
};

bool is_digits(std::string_view sv) noexcept {
    if (sv.empty()) return false;
    for (unsigned char c : sv) {
        if (c < '0' || c > '9') return false;
    }
    return true;
}

bool is_uint(std::string_view sv) noexcept {
    return is_digits(sv) && (sv.size() == 1 || sv[0] != '0');
}

bool is_pos_int(std::string_view sv) noexcept {
    return is_digits(sv) && sv[0] != '0';
}

std::string_view strip_spaces(std::string_view sv) noexcept {
    while (!sv.empty() && sv.front() == ' ') sv.remove_prefix(1);
    while (!sv.empty() && sv.back() == ' ') sv.remove_suffix(1);
    return sv;
}

std::vector<std::string_view> split_char(std::string_view sv, char delim) {
    std::vector<std::string_view> parts;
    std::size_t start = 0;
    while (true) {
        std::size_t pos = sv.find(delim, start);
        if (pos == std::string_view::npos) {
            parts.push_back(sv.substr(start));
            break;
        }
        parts.push_back(sv.substr(start, pos - start));
        start = pos + 1;
    }
    return parts;
}

std::string py_repr(std::string_view sv) {
    bool has_single = sv.find('\'') != std::string_view::npos;
    bool has_double = sv.find('"') != std::string_view::npos;
    char quote = (has_single && !has_double) ? '"' : '\'';
    std::string out;
    out.push_back(quote);
    for (unsigned char c : sv) {
        if (c == '\\') {
            out += "\\\\";
        } else if (c == quote) {
            out.push_back('\\');
            out.push_back(quote);
        } else if (c == '\n') {
            out += "\\n";
        } else if (c == '\r') {
            out += "\\r";
        } else if (c == '\t') {
            out += "\\t";
        } else if (c < 0x20 || c >= 0x7f) {
            const char* hex = "0123456789abcdef";
            out += "\\x";
            out.push_back(hex[c >> 4]);
            out.push_back(hex[c & 0xf]);
        } else {
            out.push_back(static_cast<char>(c));
        }
    }
    out.push_back(quote);
    return out;
}

std::optional<Version> parse_version(std::string_view sv) {
    std::size_t p1 = sv.find('.');
    if (p1 == std::string_view::npos) return std::nullopt;
    std::size_t p2 = sv.find('.', p1 + 1);
    if (p2 == std::string_view::npos) return std::nullopt;

    std::string_view x = sv.substr(0, p1);
    std::string_view y = sv.substr(p1 + 1, p2 - (p1 + 1));
    std::string_view rest = sv.substr(p2 + 1);

    if (!is_uint(x) || !is_uint(y)) return std::nullopt;

    std::size_t pt = rest.find('~');
    if (pt == std::string_view::npos) {
        if (!is_uint(rest)) return std::nullopt;
        return Version{IntStr{std::string(x)}, IntStr{std::string(y)}, IntStr{std::string(rest)},
                       true, IntStr{""}};
    }

    std::string_view z = rest.substr(0, pt);
    std::string_view suffix = rest.substr(pt);
    if (!is_uint(z)) return std::nullopt;
    if (!suffix.starts_with("~rc")) return std::nullopt;

    std::string_view n = suffix.substr(3);
    if (!is_pos_int(n)) return std::nullopt;

    return Version{IntStr{std::string(x)}, IntStr{std::string(y)}, IntStr{std::string(z)},
                   false, IntStr{std::string(n)}};
}

std::optional<Clause> parse_clause(std::string_view sv) {
    if (sv == "*") {
        return Clause{ClauseKind::Any, {}, {}, {}};
    }

    auto make_ver_clause = [](ClauseKind kind, std::string_view ver_sv) -> std::optional<Clause> {
        auto v = parse_version(ver_sv);
        if (!v) return std::nullopt;
        return Clause{kind, std::move(*v), {}, {}};
    };

    if (sv.starts_with("!=")) return make_ver_clause(ClauseKind::Ne, sv.substr(2));
    if (sv.starts_with(">=")) return make_ver_clause(ClauseKind::Ge, sv.substr(2));
    if (sv.starts_with("<=")) return make_ver_clause(ClauseKind::Le, sv.substr(2));
    if (sv.starts_with(">")) return make_ver_clause(ClauseKind::Gt, sv.substr(1));
    if (sv.starts_with("<")) return make_ver_clause(ClauseKind::Lt, sv.substr(1));
    if (sv.starts_with("=")) return make_ver_clause(ClauseKind::Eq, sv.substr(1));

    if (sv.starts_with("@")) {
        std::string_view rest = sv.substr(1);
        std::size_t dot = rest.find('.');
        if (dot == std::string_view::npos) return std::nullopt;
        std::string_view x = rest.substr(0, dot);
        std::string_view y = rest.substr(dot + 1);
        if (!is_uint(x) || !is_uint(y)) return std::nullopt;
        return Clause{ClauseKind::Compat, {}, IntStr{std::string(x)}, IntStr{std::string(y)}};
    }

    if (sv.ends_with(".*")) {
        std::string_view prefix = sv.substr(0, sv.size() - 2);
        std::size_t dot = prefix.find('.');
        if (dot == std::string_view::npos) {
            if (!is_uint(prefix)) return std::nullopt;
            return Clause{ClauseKind::MajorWild, {}, IntStr{std::string(prefix)}, {}};
        }
        std::string_view x = prefix.substr(0, dot);
        std::string_view y = prefix.substr(dot + 1);
        if (!is_uint(x) || !is_uint(y)) return std::nullopt;
        return Clause{ClauseKind::MajorMinorWild, {}, IntStr{std::string(x)}, IntStr{std::string(y)}};
    }

    return make_ver_clause(ClauseKind::Eq, sv);
}

bool satisfies_clause(const Version& v, const Clause& c) noexcept {
    switch (c.kind) {
        case ClauseKind::Any:
            return true;
        case ClauseKind::Eq:
            return v == c.ver;
        case ClauseKind::Ne:
            return v != c.ver;
        case ClauseKind::Gt:
            return v > c.ver;
        case ClauseKind::Ge:
            return v >= c.ver;
        case ClauseKind::Lt:
            return v < c.ver;
        case ClauseKind::Le:
            return v <= c.ver;
        case ClauseKind::MajorWild:
            return v.x == c.x;
        case ClauseKind::MajorMinorWild:
            return v.x == c.x && v.y == c.y;
        case ClauseKind::Compat:
            return v.x == c.x && v.y >= c.y;
    }
    return false;
}

bool satisfies_alternative(const Version& v, const Alternative& alt) noexcept {
    if (!v.is_plain && !alt.allow_rc) {
        return false;
    }
    for (const auto& clause : alt.clauses) {
        if (!satisfies_clause(v, clause)) {
            return false;
        }
    }
    return true;
}

}  // namespace

std::optional<std::string> pick_version(const std::vector<std::string>& available,
                                        const std::string& constraint) {
    std::vector<Version> parsed_versions;
    parsed_versions.reserve(available.size());

    for (std::size_t i = 0; i < available.size(); ++i) {
        auto parsed = parse_version(available[i]);
        if (!parsed) {
            throw std::invalid_argument("invalid version at index " + std::to_string(i) + ": " +
                                        py_repr(available[i]));
        }
        parsed_versions.push_back(std::move(*parsed));
    }

    if (strip_spaces(constraint).empty()) {
        throw std::invalid_argument("empty constraint");
    }

    auto raw_alts = split_char(constraint, '|');
    std::vector<Alternative> alternatives;
    alternatives.reserve(raw_alts.size());

    for (std::size_t a = 0; a < raw_alts.size(); ++a) {
        std::string_view alt_sv = strip_spaces(raw_alts[a]);
        Alternative alt;
        if (!alt_sv.empty() && alt_sv.front() == '?') {
            alt.allow_rc = true;
            alt_sv.remove_prefix(1);
            alt_sv = strip_spaces(alt_sv);
        }
        if (alt_sv.empty()) {
            throw std::invalid_argument("alternative " + std::to_string(a + 1) + " is empty");
        }

        auto raw_clauses = split_char(alt_sv, ',');
        alt.clauses.reserve(raw_clauses.size());
        for (std::size_t c = 0; c < raw_clauses.size(); ++c) {
            std::string_view clause_sv = strip_spaces(raw_clauses[c]);
            auto parsed_clause = parse_clause(clause_sv);
            if (!parsed_clause) {
                throw std::invalid_argument("alternative " + std::to_string(a + 1) + ", clause " +
                                            std::to_string(c + 1) + ": invalid clause " +
                                            py_repr(clause_sv));
            }
            alt.clauses.push_back(std::move(*parsed_clause));
        }

        alternatives.push_back(std::move(alt));
    }

    std::optional<std::size_t> best_idx;
    for (std::size_t i = 0; i < parsed_versions.size(); ++i) {
        bool matched = false;
        for (const auto& alt : alternatives) {
            if (satisfies_alternative(parsed_versions[i], alt)) {
                matched = true;
                break;
            }
        }
        if (matched) {
            if (!best_idx || parsed_versions[i] > parsed_versions[*best_idx]) {
                best_idx = i;
            }
        }
    }

    if (!best_idx) {
        return std::nullopt;
    }
    return available[*best_idx];
}

interface ParsedVersion {
  raw: string;
  major: number;
  minor: number;
  patch: number;
  rc: number | null;
}

type ClausePredicate = (v: ParsedVersion) => boolean;

interface Alternative {
  allowRc: boolean;
  clauses: ClausePredicate[];
}

const VERSION_RE = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:~rc([1-9][0-9]*))?$/;
const X_WILDCARD_RE = /^(0|[1-9][0-9]*)\.\*$/;
const XY_WILDCARD_RE = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.\*$/;
const AT_XY_RE = /^@(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function trimSpaces(s: string): string {
  let start = 0;
  let end = s.length;
  while (start < end && s.charCodeAt(start) === 32) {
    start++;
  }
  while (end > start && s.charCodeAt(end - 1) === 32) {
    end--;
  }
  return s.slice(start, end);
}

function parseVersion(s: string): ParsedVersion | null {
  const m = VERSION_RE.exec(s);
  if (!m) {
    return null;
  }
  return {
    raw: s,
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    rc: m[4] !== undefined ? Number(m[4]) : null,
  };
}

function compareVersions(a: ParsedVersion, b: ParsedVersion): number {
  if (a.major !== b.major) return a.major - b.major;
  if (a.minor !== b.minor) return a.minor - b.minor;
  if (a.patch !== b.patch) return a.patch - b.patch;
  if (a.rc === b.rc) return 0;
  if (a.rc === null) return 1;
  if (b.rc === null) return -1;
  return a.rc - b.rc;
}

function parseClause(clause: string): ClausePredicate | null {
  if (clause === "*") {
    return () => true;
  }

  if (
    clause.startsWith(">=") ||
    clause.startsWith("<=") ||
    clause.startsWith("!=")
  ) {
    const op = clause.slice(0, 2);
    const target = parseVersion(clause.slice(2));
    if (!target) return null;
    if (op === ">=") return (v) => compareVersions(v, target) >= 0;
    if (op === "<=") return (v) => compareVersions(v, target) <= 0;
    return (v) => compareVersions(v, target) !== 0;
  }

  if (
    clause.startsWith(">") ||
    clause.startsWith("<") ||
    clause.startsWith("=")
  ) {
    const op = clause[0];
    const target = parseVersion(clause.slice(1));
    if (!target) return null;
    if (op === ">") return (v) => compareVersions(v, target) > 0;
    if (op === "<") return (v) => compareVersions(v, target) < 0;
    return (v) => compareVersions(v, target) === 0;
  }

  const mAt = AT_XY_RE.exec(clause);
  if (mAt) {
    const major = Number(mAt[1]);
    const minor = Number(mAt[2]);
    return (v) => v.major === major && v.minor >= minor;
  }

  const mX = X_WILDCARD_RE.exec(clause);
  if (mX) {
    const major = Number(mX[1]);
    return (v) => v.major === major;
  }

  const mXY = XY_WILDCARD_RE.exec(clause);
  if (mXY) {
    const major = Number(mXY[1]);
    const minor = Number(mXY[2]);
    return (v) => v.major === major && v.minor === minor;
  }

  const exact = parseVersion(clause);
  if (exact) {
    return (v) => compareVersions(v, exact) === 0;
  }

  return null;
}

export function pickVersion(available: string[], constraint: string): string | null {
  if (!Array.isArray(available)) {
    throw new Error("available must be a list");
  }

  const parsedAvailable: ParsedVersion[] = [];
  for (let i = 0; i < available.length; i++) {
    const el: unknown = available[i];
    if (typeof el !== "string") {
      throw new Error(`invalid version at index ${i}: ${String(el)}`);
    }
    const pv = parseVersion(el);
    if (!pv) {
      throw new Error(`invalid version at index ${i}: '${el}'`);
    }
    parsedAvailable.push(pv);
  }

  if (typeof constraint !== "string") {
    throw new Error("constraint must be a str");
  }

  if (trimSpaces(constraint) === "") {
    throw new Error("empty constraint");
  }

  const rawAlternatives = constraint.split("|");
  const alternatives: Alternative[] = [];

  for (let aIdx = 0; aIdx < rawAlternatives.length; aIdx++) {
    const aNum = aIdx + 1;
    let altText = trimSpaces(rawAlternatives[aIdx]);
    let allowRc = false;
    if (altText.startsWith("?")) {
      allowRc = true;
      altText = trimSpaces(altText.slice(1));
    }
    if (altText === "") {
      throw new Error(`alternative ${aNum} is empty`);
    }

    const rawClauses = altText.split(",");
    const clauses: ClausePredicate[] = [];
    for (let cIdx = 0; cIdx < rawClauses.length; cIdx++) {
      const cNum = cIdx + 1;
      const clauseText = trimSpaces(rawClauses[cIdx]);
      const pred = parseClause(clauseText);
      if (!pred) {
        throw new Error(
          `alternative ${aNum}, clause ${cNum}: invalid clause '${clauseText}'`
        );
      }
      clauses.push(pred);
    }

    alternatives.push({ allowRc, clauses });
  }

  let best: ParsedVersion | null = null;

  for (const v of parsedAvailable) {
    const matchesConstraint = alternatives.some((alt) => {
      if (v.rc !== null && !alt.allowRc) {
        return false;
      }
      return alt.clauses.every((pred) => pred(v));
    });

    if (matchesConstraint) {
      if (best === null || compareVersions(v, best) > 0) {
        best = v;
      }
    }
  }

  return best !== null ? best.raw : null;
}

