import "sort"

type Tuple1 struct {
	F0 string
	F1 int
}

func LeaderboardRanks(submissions []Tuple1) []int {
	n := len(submissions)
	if n == 0 {
		return []int{}
	}

	playerBestTime := make(map[string]int, minInt(n, 1024))
	remTime := make([]int, n)
	curTime := make([]int, n)
	states := make([]int, 0, n)

	for i, sub := range submissions {
		if prevTime, ok := playerBestTime[sub.F0]; ok {
			if sub.F1 > submissions[prevTime].F1 {
				remTime[i] = prevTime
				playerBestTime[sub.F0] = i
				curTime[i] = i
				states = append(states, i)
			} else {
				remTime[i] = -1
				curTime[i] = prevTime
			}
		} else {
			remTime[i] = -1
			playerBestTime[sub.F0] = i
			curTime[i] = i
			states = append(states, i)
		}
	}

	sort.Slice(states, func(i, j int) bool {
		ti, tj := states[i], states[j]
		si, sj := submissions[ti].F1, submissions[tj].F1
		if si != sj {
			return si > sj
		}
		return ti < tj
	})

	pos := make([]int, n)
	for idx, t := range states {
		pos[t] = idx + 1
	}

	m := len(states)
	bit := make([]int, m+1)
	add := func(idx, delta int) {
		for ; idx <= m; idx += idx & -idx {
			bit[idx] += delta
		}
	}
	sum := func(idx int) int {
		s := 0
		for ; idx > 0; idx -= idx & -idx {
			s += bit[idx]
		}
		return s
	}

	ans := make([]int, n)
	for i := 0; i < n; i++ {
		if r := remTime[i]; r != -1 {
			add(pos[r], -1)
		}
		if curTime[i] == i {
			add(pos[i], 1)
		}
		ans[i] = 1 + sum(pos[curTime[i]]-1)
	}

	return ans
}

