	if a < b {
		return a
	}
	return b
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, long f1) {}

    public static List<Long> leaderboardRanks(List<Tuple1> submissions) {
        int n = submissions.size();
        if (n == 0) {
            return new ArrayList<>();
        }

        long[] scores = new long[n];
        int[] order = new int[n];
        for (int i = 0; i < n; i++) {
            scores[i] = submissions.get(i).f1();
            order[i] = i;
        }

        int[] temp = new int[n];
        mergeSort(order, temp, scores, 0, n);

        int[] pos = new int[n];
        for (int rank = 0; rank < n; rank++) {
            pos[order[rank]] = rank + 1;
        }

        int[] bit = new int[n + 1];
        Map<String, Integer> bestTimeByPlayer = HashMap.newHashMap(n);
        List<Long> result = new ArrayList<>(n);

        for (int i = 0; i < n; i++) {
            Tuple1 sub = submissions.get(i);
            String player = sub.f0();
            long score = scores[i];

            Integer prevTimeObj = bestTimeByPlayer.get(player);
            int activeTime;
            if (prevTimeObj == null) {
                activeTime = i;
                bestTimeByPlayer.put(player, i);
                bitAdd(bit, n, pos[i], 1);
            } else {
                int prevTime = prevTimeObj;
                if (score > scores[prevTime]) {
                    bitAdd(bit, n, pos[prevTime], -1);
                    activeTime = i;
                    bestTimeByPlayer.put(player, i);
                    bitAdd(bit, n, pos[i], 1);
                } else {
                    activeTime = prevTime;
                }
            }

            result.add((long) bitSum(bit, pos[activeTime]));
        }

        return result;
    }

    private static void mergeSort(int[] arr, int[] temp, long[] scores, int left, int right) {
        if (right - left <= 1) {
            return;
        }
        int mid = (left + right) >>> 1;
        mergeSort(arr, temp, scores, left, mid);
        mergeSort(arr, temp, scores, mid, right);

        int i = left;
        int j = mid;
        int k = left;
        while (i < mid && j < right) {
            int a = arr[i];
            int b = arr[j];
            if (scores[a] > scores[b] || (scores[a] == scores[b] && a < b)) {
                temp[k++] = a;
                i++;
            } else {
                temp[k++] = b;
                j++;
            }
        }
        while (i < mid) {
            temp[k++] = arr[i++];
        }
        while (j < right) {
            temp[k++] = arr[j++];
        }
        System.arraycopy(temp, left, arr, left, right - left);
    }

    private static void bitAdd(int[] bit, int n, int idx, int delta) {
        for (; idx <= n; idx += idx & -idx) {
            bit[idx] += delta;
        }
    }

    private static int bitSum(int[] bit, int idx) {
        int sum = 0;
        for (; idx > 0; idx -= idx & -idx) {
            sum += bit[idx];
        }
        return sum;
    }
}

#include <algorithm>
#include <numeric>
#include <string>
#include <tuple>
#include <unordered_map>
#include <vector>

std::vector<long long> leaderboard_ranks(
    const std::vector<std::tuple<std::string, long long>>& submissions) {
    const std::size_t n = submissions.size();
    if (n == 0) {
        return {};
    }

    // Order all submission indices by (score descending, index ascending).
    // Every valid (BEST, BEST_TIME) pair corresponds to a unique submission index.
    std::vector<int> order(n);
    std::iota(order.begin(), order.end(), 0);
    std::sort(order.begin(), order.end(), [&](int a, int b) {
        const long long score_a = std::get<1>(submissions[a]);
        const long long score_b = std::get<1>(submissions[b]);
        if (score_a != score_b) {
            return score_a > score_b;
        }
        return a < b;
    });

    // 1-based coordinate-compressed rank position for each submission index.
    std::vector<int> pos(n);
    for (std::size_t r = 0; r < n; ++r) {
        pos[order[r]] = static_cast<int>(r + 1);
    }

    // Fenwick tree (Binary Indexed Tree) to count active players up to a position.
    std::vector<int> bit(n + 1, 0);
    auto bit_add = [&](int idx, int delta) {
        for (std::size_t i = static_cast<std::size_t>(idx); i <= n; i += i & (~i + 1)) {
            bit[i] += delta;
        }
    };
    auto bit_sum = [&](int idx) {
        long long sum = 0;
        for (std::size_t i = static_cast<std::size_t>(idx); i > 0; i -= i & (~i + 1)) {
            sum += bit[i];
        }
        return sum;
    };

    struct PlayerState {
        long long best_score;
        int current_pos;
    };

    std::unordered_map<std::string, int> player_to_id;
    player_to_id.reserve(n);
    std::vector<PlayerState> players;
    players.reserve(n);

    std::vector<long long> result(n);

    for (std::size_t i = 0; i < n; ++i) {
        const auto& [name, score] = submissions[i];
        auto [it, inserted] = player_to_id.try_emplace(name, static_cast<int>(players.size()));

        if (inserted) {
            int p = pos[i];
            players.push_back({score, p});
            bit_add(p, 1);
            result[i] = bit_sum(p);
        } else {
            PlayerState& st = players[it->second];
            if (score > st.best_score) {
                bit_add(st.current_pos, -1);
                st.best_score = score;
                st.current_pos = pos[i];
                bit_add(st.current_pos, 1);
            }
            result[i] = bit_sum(st.current_pos);
        }
    }

    return result;
}

export function leaderboardRanks(submissions: [string, number][]): number[] {
  const n = submissions.length;
  if (n === 0) {
    return [];
  }

  const bestSub = new Map<string, number>();
  const stateAt = new Int32Array(n);
  const prevState = new Int32Array(n);
  const usedIndices: number[] = [];

  for (let i = 0; i < n; i++) {
    const [player, score] = submissions[i];
    const old = bestSub.get(player);
    if (old === undefined) {
      bestSub.set(player, i);
      stateAt[i] = i;
      prevState[i] = -1;
      usedIndices.push(i);
    } else if (score > submissions[old][1]) {
      bestSub.set(player, i);
      stateAt[i] = i;
      prevState[i] = old;
      usedIndices.push(i);
    } else {
      stateAt[i] = old;
      prevState[i] = -2;
    }
  }

  usedIndices.sort((a, b) => {
    const diff = submissions[b][1] - submissions[a][1];
    return diff !== 0 ? diff : a - b;
  });

  const m = usedIndices.length;
  const pos = new Int32Array(n);
  for (let r = 0; r < m; r++) {
    pos[usedIndices[r]] = r + 1;
  }

  const bit = new Int32Array(m + 1);
  const result = new Array<number>(n);

  for (let i = 0; i < n; i++) {
    const prev = prevState[i];
    if (prev !== -2) {
      if (prev >= 0) {
        for (let idx = pos[prev]; idx <= m; idx += idx & -idx) {
          bit[idx] -= 1;
        }
      }
      for (let idx = pos[i]; idx <= m; idx += idx & -idx) {
        bit[idx] += 1;
      }
    }

    let rank = 0;
    for (let idx = pos[stateAt[i]]; idx > 0; idx -= idx & -idx) {
      rank += bit[idx];
    }
    result[i] = rank;
  }

  return result;
}

package main

import "sort"

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
}

type Tuple2 struct {
	F0 int
	F1 int
}

type pstNode struct {
	sum   int64
	left  int32
	right int32
	cnt   int32
}

func BudgetPurchases(prices []int, queries []Tuple1) []Tuple2 {
	qLen := len(queries)
	res := make([]Tuple2, qLen)
	if qLen == 0 {
		return res
	}

	n := len(prices)
	if n == 0 {
		return res
	}

	// Coordinate compression of prices
	uniq := make([]int, n)
	copy(uniq, prices)
	sort.Ints(uniq)
	m := 0
	for i := 0; i < n; i++ {
		if i == 0 || uniq[i] != uniq[i-1] {
			uniq[m] = uniq[i]
			m++
		}
	}
	uniq = uniq[:m]

	// Build Persistent Segment Tree
	// Node 0 is the implicit empty node (all fields zero).
	tree := make([]pstNode, 1, 1+n*19)
	roots := make([]int32, n+1)

	for i, p := range prices {
		// Binary search for compressed index of p
		lo, hi := 0, m-1
		for lo < hi {
			mid := (lo + hi) >> 1
			if uniq[mid] < p {
				lo = mid + 1
			} else {
				hi = mid
			}
		}
		idx := lo
		val := int64(p)

		prev := roots[i]
		newRoot := int32(len(tree))
		tree = append(tree, pstNode{
			sum:   tree[prev].sum + val,
			left:  tree[prev].left,
			right: tree[prev].right,
			cnt:   tree[prev].cnt + 1,
		})
		roots[i+1] = newRoot

		curr := newRoot
		lo, hi = 0, m-1
		for lo < hi {
			mid := (lo + hi) >> 1
			nextIdx := int32(len(tree))
			if idx <= mid {
				prev = tree[prev].left
				tree[curr].left = nextIdx
				hi = mid
			} else {
				prev = tree[prev].right
				tree[curr].right = nextIdx
				lo = mid + 1
			}
			tree = append(tree, pstNode{
				sum:   tree[prev].sum + val,
				left:  tree[prev].left,
				right: tree[prev].right,
				cnt:   tree[prev].cnt + 1,
			})
			curr = nextIdx
		}
	}

	// Answer queries
	for qi, q := range queries {
		l, r, budget := q.F0, q.F1, int64(q.F2)
		if budget == 0 {
			res[qi] = Tuple2{F0: 0, F1: 0}
			continue
		}

		u := roots[l]
		v := roots[r+1]

		totSum := tree[v].sum - tree[u].sum
		if totSum <= budget {
			res[qi] = Tuple2{
				F0: int(tree[v].cnt - tree[u].cnt),
				F1: int(totSum),
			}
			continue
		}

		rem := budget
		var count int
		var spent int64

		lo, hi := 0, m-1
		for lo < hi {
			mid := (lo + hi) >> 1
			lu := tree[u].left
			lv := tree[v].left
			leftSum := tree[lv].sum - tree[lu].sum
			if leftSum <= rem {
				rem -= leftSum
				spent += leftSum
				count += int(tree[lv].cnt - tree[lu].cnt)
				u = tree[u].right
				v = tree[v].right
				lo = mid + 1
			} else {
				u = lu
				v = lv
				hi = mid
			}
		}

		p := int64(uniq[lo])
		avail := int64(tree[v].cnt - tree[u].cnt)
		take := rem / p
		if take > avail {
			take = avail
		}
		count += int(take)
		spent += take * p

		res[qi] = Tuple2{
			F0: count,
			F1: int(spent),
		}
	}

	return res
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2) {}

    public record Tuple2(long f0, long f1) {}

    public static List<Tuple2> budgetPurchases(List<Long> prices, List<Tuple1> queries) {
        int qCount = queries.size();
        if (qCount == 0) {
            return new ArrayList<>();
        }

        int n = prices.size();
        long[] priceArr = new long[n];
        long[] sorted = new long[n];
        for (int i = 0; i < n; i++) {
            long p = prices.get(i);
            priceArr[i] = p;
            sorted[i] = p;
        }

        Arrays.sort(sorted);
        long[] uniq = new long[n];
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) {
                uniq[m++] = sorted[i];
            }
        }

        int maxNodes = n * 20 + 5;
        int[] left = new int[maxNodes];
        int[] right = new int[maxNodes];
        int[] cnt = new int[maxNodes];
        long[] sum = new long[maxNodes];
        int[] roots = new int[n + 1];
        int ptr = 0;

        for (int i = 0; i < n; i++) {
            long val = priceArr[i];
            int idx = Arrays.binarySearch(uniq, 0, m, val);
            int prev = roots[i];
            int newRoot = ++ptr;
            roots[i + 1] = newRoot;

            int curr = newRoot;
            int tl = 0;
            int tr = m - 1;
            while (tl < tr) {
                cnt[curr] = cnt[prev] + 1;
                sum[curr] = sum[prev] + val;
                int mid = (tl + tr) >>> 1;
                if (idx <= mid) {
                    right[curr] = right[prev];
                    int next = ++ptr;
                    left[curr] = next;
                    curr = next;
                    prev = left[prev];
                    tr = mid;
                } else {
                    left[curr] = left[prev];
                    int next = ++ptr;
                    right[curr] = next;
                    curr = next;
                    prev = right[prev];
                    tl = mid + 1;
                }
            }
            cnt[curr] = cnt[prev] + 1;
            sum[curr] = sum[prev] + val;
        }

        List<Tuple2> result = new ArrayList<>(qCount);
        for (int qi = 0; qi < qCount; qi++) {
            Tuple1 query = queries.get(qi);
            int l = (int) query.f0();
            int r = (int) query.f1();
            long budget = query.f2();

            int u = roots[r + 1];
            int v = roots[l];
            long totalSum = sum[u] - sum[v];
            if (totalSum <= budget) {
                result.add(new Tuple2(cnt[u] - cnt[v], totalSum));
                continue;
            }
            if (budget == 0) {
                result.add(new Tuple2(0L, 0L));
                continue;
            }

            long rem = budget;
            long ansCnt = 0;
            long ansSpent = 0;
            int tl = 0;
            int tr = m - 1;
            while (tl < tr) {
                int lu = left[u];
                int lv = left[v];
                long lSum = sum[lu] - sum[lv];
                int mid = (tl + tr) >>> 1;
                if (lSum <= rem) {
                    ansCnt += cnt[lu] - cnt[lv];
                    ansSpent += lSum;
                    rem -= lSum;
                    if (rem == 0) {
                        break;
                    }
                    u = right[u];
                    v = right[v];
                    tl = mid + 1;
                } else {
                    u = lu;
                    v = lv;
                    tr = mid;
                }
            }

            if (rem > 0) {
                long p = uniq[tl];
                long take = Math.min((long) (cnt[u] - cnt[v]), rem / p);
                ansCnt += take;
                ansSpent += take * p;
            }

            result.add(new Tuple2(ansCnt, ansSpent));
        }

        return result;
    }
}

#include <algorithm>
#include <tuple>
#include <vector>

std::vector<std::tuple<long long, long long>> budget_purchases(
    const std::vector<long long>& prices,
    const std::vector<std::tuple<long long, long long, long long>>& queries) {
    if (queries.empty()) {
        return {};
    }

    const int n = static_cast<int>(prices.size());

    std::vector<long long> vals = prices;
    std::sort(vals.begin(), vals.end());
    vals.erase(std::unique(vals.begin(), vals.end()), vals.end());
    const int m = static_cast<int>(vals.size());

    struct Node {
        int lc = 0;
        int rc = 0;
        int cnt = 0;
        long long sum = 0;
    };

    int tree_depth = 1;
    while ((1 << (tree_depth - 1)) < m) {
        ++tree_depth;
    }

    std::vector<Node> nodes;
    nodes.reserve(1 + static_cast<std::size_t>(n) * (tree_depth + 1));
    nodes.push_back(Node{});  // Node 0 is the null node.

    std::vector<int> roots(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        long long val = prices[i];
        int idx = static_cast<int>(
            std::lower_bound(vals.begin(), vals.end(), val) - vals.begin());

        int prev = roots[i];
        int new_root = static_cast<int>(nodes.size());
        Node root_copy = nodes[prev];
        root_copy.cnt += 1;
        root_copy.sum += val;
        nodes.push_back(root_copy);

        int cur = new_root;
        int p = prev;
        int tl = 0, tr = m - 1;
        while (tl < tr) {
            int tm = tl + (tr - tl) / 2;
            int next_node = static_cast<int>(nodes.size());
            if (idx <= tm) {
                p = nodes[p].lc;
                Node child = nodes[p];
                child.cnt += 1;
                child.sum += val;
                nodes.push_back(child);
                nodes[cur].lc = next_node;
                cur = next_node;
                tr = tm;
            } else {
                p = nodes[p].rc;
                Node child = nodes[p];
                child.cnt += 1;
                child.sum += val;
                nodes.push_back(child);
                nodes[cur].rc = next_node;
                cur = next_node;
                tl = tm + 1;
            }
        }
        roots[i + 1] = new_root;
    }

    std::vector<std::tuple<long long, long long>> results;
    results.reserve(queries.size());

    for (const auto& [l, r, budget] : queries) {
        if (budget <= 0) {
            results.emplace_back(0LL, 0LL);
            continue;
        }

        int u_l = roots[static_cast<std::size_t>(l)];
        int u_r = roots[static_cast<std::size_t>(r) + 1];

        long long range_sum = nodes[u_r].sum - nodes[u_l].sum;
        if (budget >= range_sum) {
            long long range_cnt = nodes[u_r].cnt - nodes[u_l].cnt;
            results.emplace_back(range_cnt, range_sum);
            continue;
        }

        long long total_cnt = 0;
        long long total_spent = 0;
        long long rem = budget;
        int tl = 0, tr = m - 1;

        while (tl < tr) {
            int tm = tl + (tr - tl) / 2;
            int ll = nodes[u_l].lc;
            int lr = nodes[u_r].lc;
            long long l_sum = nodes[lr].sum - nodes[ll].sum;
            if (rem >= l_sum) {
                rem -= l_sum;
                total_spent += l_sum;
                total_cnt += nodes[lr].cnt - nodes[ll].cnt;
                u_l = nodes[u_l].rc;
                u_r = nodes[u_r].rc;
                tl = tm + 1;
            } else {
                u_l = ll;
                u_r = lr;
                tr = tm;
            }
        }

        long long v = vals[tl];
        long long c = nodes[u_r].cnt - nodes[u_l].cnt;
        long long take = std::min(c, rem / v);
        total_cnt += take;
        total_spent += take * v;

        results.emplace_back(total_cnt, total_spent);
    }

    return results;
}

export function budgetPurchases(
  prices: number[],
  queries: [number, number, number][],
): [number, number][] {
  const qLen = queries.length;
  const n = prices.length;
  if (qLen === 0 || n === 0) {
    return [];
  }

  // Coordinate-compress prices using typed array numeric sort.
  const sorted = new Int32Array(n);
  for (let i = 0; i < n; i++) {
    sorted[i] = prices[i];
  }
  sorted.sort();

  let m = 1;
  for (let i = 1; i < n; i++) {
    if (sorted[i] !== sorted[m - 1]) {
      sorted[m++] = sorted[i];
    }
  }
  const unique = sorted.subarray(0, m);

  // Determine tree height H such that (1 << H) >= m.
  let h = 0;
  while ((1 << h) < m) {
    h++;
  }

  // Persistent segment tree stored in flat typed arrays.
  // Node 0 is the implicit empty node (children 0, count 0, sum 0).
  const maxNodes = n * (h + 1) + 1;
  const left = new Int32Array(maxNodes);
  const right = new Int32Array(maxNodes);
  const cnt = new Int32Array(maxNodes);
  const sum = new Float64Array(maxNodes);
  const roots = new Int32Array(n + 1);

  let ptr = 0;
  for (let i = 0; i < n; i++) {
    const v = prices[i];
    let lo = 0;
    let hi = m - 1;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (unique[mid] < v) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    const idx = lo;

    let prev = roots[i];
    const newRoot = ++ptr;
    roots[i + 1] = newRoot;
    cnt[newRoot] = cnt[prev] + 1;
    sum[newRoot] = sum[prev] + v;

    let curr = newRoot;
    for (let bit = h - 1; bit >= 0; bit--) {
      const child = ++ptr;
      if (((idx >>> bit) & 1) === 0) {
        left[curr] = child;
        right[curr] = right[prev];
        prev = left[prev];
      } else {
        left[curr] = left[prev];
        right[curr] = child;
        prev = right[prev];
      }
      curr = child;
      cnt[curr] = cnt[prev] + 1;
      sum[curr] = sum[prev] + v;
    }
  }

  const results: [number, number][] = new Array(qLen);

  for (let q = 0; q < qLen; q++) {
    const query = queries[q];
    const l = query[0];
    const r = query[1];
    const budget = query[2];

    if (budget === 0) {
      results[q] = [0, 0];
      continue;
    }

    let uL = roots[l];
    let uR = roots[r + 1];

    const rangeSum = sum[uR] - sum[uL];
    if (rangeSum <= budget) {
      results[q] = [cnt[uR] - cnt[uL], rangeSum];
      continue;
    }

    let rem = budget;
    let totalCnt = 0;
    let totalSpent = 0;
    let idx = 0;

    for (let bit = h - 1; bit >= 0; bit--) {
      const lL = left[uL];
      const lR = left[uR];
      const lSum = sum[lR] - sum[lL];
      if (rem >= lSum) {
        rem -= lSum;
        totalSpent += lSum;
        totalCnt += cnt[lR] - cnt[lL];
        uL = right[uL];
        uR = right[uR];
        idx |= 1 << bit;
      } else {
        uL = lL;
        uR = lR;
      }
    }

    const price = unique[idx];
    const avail = cnt[uR] - cnt[uL];
    let take = Math.floor(rem / price);
    if ((take + 1) * price <= rem) {
      take++;
    } else if (take * price > rem) {
      take--;
    }
    if (take > avail) {
      take = avail;
    }

    totalCnt += take;
    totalSpent += take * price;
    results[q] = [totalCnt, totalSpent];
  }

  return results;
}

package main

import (
	"math"
	"math/bits"
)

type Tuple1 struct {
	F0 int
	F1 int
}

func CountRecords(levels []int, margin int, queries []Tuple1) []int {
	if len(queries) == 0 {
		return []int{}
	}

	n := len(levels)
	size := 1
	for size < n {
		size <<= 1
	}

	const negInf = math.MinInt / 2
	tree := make([]int, 2*size)
	for i := 0; i < n; i++ {
		tree[size+i] = levels[i]
	}
	for i := n; i < size; i++ {
		tree[size+i] = negInf
	}
	for i := size - 1; i >= 1; i-- {
		left, right := tree[2*i], tree[2*i+1]
		if left >= right {
			tree[i] = left
		} else {
			tree[i] = right
		}
	}

	logN := bits.Len(uint(n))
	up := make([][20]int32, n+1)
	for k := 0; k < logN; k++ {
		up[n][k] = int32(n)
	}

	for i := n - 1; i >= 0; i-- {
		nxt := n
		if i+1 < n {
			target := levels[i] + margin
			u := size + i + 1
			for {
				u >>= bits.TrailingZeros(uint(u))
				if tree[u] >= target {
					for u < size {
						u <<= 1
						if tree[u] < target {
							u++
						}
					}
					nxt = u - size
					break
				}
				u++
				if (u & (u - 1)) == 0 {
					break
				}
			}
		}
		up[i][0] = int32(nxt)
		for k := 1; k < logN; k++ {
			up[i][k] = up[up[i][k-1]][k-1]
		}
	}

	ans := make([]int, len(queries))
	for qi, q := range queries {
		curr := int32(q.F0)
		r := int32(q.F1)
		cnt := 1
		for k := logN - 1; k >= 0; k-- {
			if up[curr][k] <= r {
				curr = up[curr][k]
				cnt += 1 << k
			}
		}
		ans[qi] = cnt
	}

	return ans
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1) {}

    public static List<Long> countRecords(List<Long> levels, long margin, List<Tuple1> queries) {
        int qSize = queries.size();
        if (qSize == 0) {
            return new ArrayList<>();
        }

        int n = levels.size();
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            arr[i] = levels.get(i);
        }

        long[] tree = new long[4 * n];
        build(tree, arr, 1, 0, n - 1);

        int log = 1;
        while ((1 << log) <= n) {
            log++;
        }

        int[][] up = new int[log][n + 1];
        for (int i = 0; i < n; i++) {
            long target = arr[i] + margin;
            up[0][i] = findFirst(tree, 1, 0, n - 1, i + 1, target, n);
        }
        up[0][n] = n;

        for (int k = 1; k < log; k++) {
            int[] prev = up[k - 1];
            int[] curr = up[k];
            for (int i = 0; i <= n; i++) {
                curr[i] = prev[prev[i]];
            }
        }

        List<Long> result = new ArrayList<>(qSize);
        for (int qIdx = 0; qIdx < qSize; qIdx++) {
            Tuple1 q = queries.get(qIdx);
            int curr = (int) q.f0();
            int r = (int) q.f1();
            long count = 1L;
            for (int k = log - 1; k >= 0; k--) {
                int nxt = up[k][curr];
                if (nxt <= r) {
                    count += 1L << k;
                    curr = nxt;
                }
            }
            result.add(count);
        }

        return result;
    }

    private static void build(long[] tree, long[] arr, int node, int start, int end) {
        if (start == end) {
            tree[node] = arr[start];
            return;
        }
        int mid = (start + end) >>> 1;
        int left = node << 1;
        int right = left | 1;
        build(tree, arr, left, start, mid);
        build(tree, arr, right, mid + 1, end);
        tree[node] = Math.max(tree[left], tree[right]);
    }

    private static int findFirst(long[] tree, int node, int start, int end, int ql, long target, int n) {
        if (end < ql || tree[node] < target) {
            return n;
        }
        if (start == end) {
            return start;
        }
        int mid = (start + end) >>> 1;
        int left = node << 1;
        int res = findFirst(tree, left, start, mid, ql, target, n);
        if (res != n) {
            return res;
        }
        return findFirst(tree, left | 1, mid + 1, end, ql, target, n);
    }
}

#include <algorithm>
#include <array>
#include <limits>
#include <tuple>
#include <vector>

std::vector<long long> count_records(
    const std::vector<long long>& levels,
    long long margin,
    const std::vector<std::tuple<long long, long long>>& queries) {
    if (queries.empty()) {
        return {};
    }

    const int n = static_cast<int>(levels.size());
    if (n == 0) {
        return {};
    }

    int size = 1;
    while (size < n) {
        size <<= 1;
    }

    constexpr long long kNegInf = std::numeric_limits<long long>::min();
    std::vector<long long> tree(2 * size, kNegInf);
    for (int i = 0; i < n; ++i) {
        tree[size + i] = levels[i];
    }
    for (int p = size - 1; p >= 1; --p) {
        tree[p] = std::max(tree[2 * p], tree[2 * p + 1]);
    }

    auto find_next = [&](int pos, long long target) -> int {
        if (pos >= n) {
            return n;
        }
        int p = size + pos;
        if (tree[p] >= target) {
            return pos;
        }
        while (p > 1) {
            if ((p & 1) == 0 && tree[p + 1] >= target) {
                p = p + 1;
                while (p < size) {
                    if (tree[2 * p] >= target) {
                        p = 2 * p;
                    } else {
                        p = 2 * p + 1;
                    }
                }
                return p - size;
            }
            p >>= 1;
        }
        return n;
    };

    constexpr int kLog = 19;
    std::vector<std::array<int, kLog>> up(n + 1);
    up[n].fill(n);

    for (int i = n - 1; i >= 0; --i) {
        int nxt = find_next(i + 1, levels[i] + margin);
        up[i][0] = nxt;
        for (int k = 1; k < kLog; ++k) {
            up[i][k] = up[up[i][k - 1]][k - 1];
        }
    }

    std::vector<long long> results;
    results.reserve(queries.size());

    for (const auto& [l_ll, r_ll] : queries) {
        int curr = static_cast<int>(l_ll);
        int right = static_cast<int>(r_ll);
        long long count = 1;
        for (int k = kLog - 1; k >= 0; --k) {
            if (up[curr][k] <= right) {
                count += (1LL << k);
                curr = up[curr][k];
            }
        }
        results.push_back(count);
    }

    return results;
}

export function countRecords(
  levels: number[],
  margin: number,
  queries: [number, number][]
): number[] {
  const qCount = queries.length;
  if (qCount === 0) {
    return [];
  }

  const n = levels.length;
  if (n === 0) {
    return [];
  }

  let log = 1;
  while ((1 << log) <= n) {
    log++;
  }

  let size = 1;
  while (size < n) {
    size <<= 1;
  }

  const seg = new Int32Array(size << 1);
  seg.fill(-2000000000);
  for (let i = 0; i < n; i++) {
    seg[size + i] = levels[i];
  }
  for (let i = size - 1; i >= 1; i--) {
    const left = seg[i << 1];
    const right = seg[(i << 1) | 1];
    seg[i] = left > right ? left : right;
  }

  const up = new Int32Array((n + 1) * log);
  const endBase = n * log;
  const lastBase = (n - 1) * log;
  for (let k = 0; k < log; k++) {
    up[endBase + k] = n;
    up[lastBase + k] = n;
  }

  let suffixMax = levels[n - 1];
  for (let i = n - 2; i >= 0; i--) {
    const val = levels[i];
    const target = val + margin;
    let nxt = n;

    if (target <= suffixMax) {
      let pos = size + i + 1;
      while (true) {
        while ((pos & 1) === 0) {
          pos >>= 1;
        }
        if (seg[pos] >= target) {
          while (pos < size) {
            pos <<= 1;
            if (seg[pos] < target) {
              pos |= 1;
            }
          }
          nxt = pos - size;
          break;
        }
        pos++;
        if ((pos & (pos - 1)) === 0) {
          break;
        }
      }
    }

    const base = i * log;
    up[base] = nxt;
    for (let k = 1; k < log; k++) {
      const mid = up[base + k - 1];
      up[base + k] = up[mid * log + k - 1];
    }

    if (val > suffixMax) {
      suffixMax = val;
    }
  }

  const result: number[] = new Array(qCount);
  for (let q = 0; q < qCount; q++) {
    const query = queries[q];
    let curr = query[0];
    const r = query[1];
    let count = 1;

    for (let k = log - 1; k >= 0; k--) {
      const nxt = up[curr * log + k];
      if (nxt <= r) {
        curr = nxt;
        count += 1 << k;
      }
    }

    result[q] = count;
  }

  return result;
}

package main

import (
	"errors"
	"math/big"
	"strings"
)

type Tuple1 struct {
	F0 string
	F1 string
	F2 string
}

func isAllDigits(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func parsePrincipalCents(s string) (*big.Int, error) {
	var centsStr string
	dot := strings.IndexByte(s, '.')
	if dot == -1 {
		if !isAllDigits(s) {
			return nil, errors.New("invalid principal")
		}
		centsStr = s + "00"
	} else {
		before := s[:dot]
		after := s[dot+1:]
		if !isAllDigits(before) || !isAllDigits(after) || len(after) < 1 || len(after) > 2 {
			return nil, errors.New("invalid principal")
		}
		if len(after) == 1 {
			centsStr = before + after + "0"
		} else {
			centsStr = before + after
		}
	}
	val, ok := new(big.Int).SetString(centsStr, 10)
	if !ok || val.Sign() <= 0 {
		return nil, errors.New("principal must be > 0")
	}
	return val, nil
}

func parseRateMicro(s string) (int64, error) {
	var microStr string
	dot := strings.IndexByte(s, '.')
	if dot == -1 {
		if !isAllDigits(s) {
			return 0, errors.New("invalid annual_rate_pct")
		}
		microStr = s + "000000"
	} else {
		before := s[:dot]
		after := s[dot+1:]
		if !isAllDigits(before) || !isAllDigits(after) || len(after) < 1 || len(after) > 6 {
			return 0, errors.New("invalid annual_rate_pct")
		}
		microStr = before + after + strings.Repeat("0", 6-len(after))
	}
	val, ok := new(big.Int).SetString(microStr, 10)
	if !ok {
		return 0, errors.New("invalid annual_rate_pct")
	}
	maxRate := big.NewInt(100_000_000)
	if val.Cmp(maxRate) > 0 {
		return 0, errors.New("annual_rate_pct must be <= 100")
	}
	return val.Int64(), nil
}

func gcd64(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func formatCents(c *big.Int) string {
	s := c.String()
	switch len(s) {
	case 1:
		return "0.0" + s
	case 2:
		return "0." + s
	default:
		return s[:len(s)-2] + "." + s[len(s)-2:]
	}
}

func ceilDiv(num, den *big.Int) *big.Int {
	one := big.NewInt(1)
	res := new(big.Int).Add(num, den)
	res.Sub(res, one)
	res.Quo(res, den)
	return res
}

func roundHalfEven(num, den *big.Int) *big.Int {
	quo, rem := new(big.Int), new(big.Int)
	quo.QuoRem(num, den, rem)
	twiceRem := new(big.Int).Lsh(rem, 1)
	cmp := twiceRem.Cmp(den)
	if cmp > 0 || (cmp == 0 && quo.Bit(0) == 1) {
		quo.Add(quo, big.NewInt(1))
	}
	return quo
}

func Amortize(principal string, annual_rate_pct string, months int) ([]Tuple1, error) {
	if months < 1 || months > 1200 {
		return nil, errors.New("months must be between 1 and 1200")
	}
	pCents, err := parsePrincipalCents(principal)
	if err != nil {
		return nil, err
	}
	rateMicro, err := parseRateMicro(annual_rate_pct)
	if err != nil {
		return nil, err
	}

	const denomBase int64 = 1_200_000_000
	var pBig, qBig *big.Int
	if rateMicro == 0 {
		pBig = big.NewInt(0)
		qBig = big.NewInt(1)
	} else {
		g := gcd64(rateMicro, denomBase)
		pBig = big.NewInt(rateMicro / g)
		qBig = big.NewInt(denomBase / g)
	}

	nBig := big.NewInt(int64(months))
	var payCents *big.Int
	if rateMicro == 0 {
		payCents = ceilDiv(pCents, nBig)
	} else {
		qp := new(big.Int).Add(qBig, pBig)
		qpPow := new(big.Int).Exp(qp, nBig, nil)
		qPow := new(big.Int).Exp(qBig, nBig, nil)

		num := new(big.Int).Mul(pCents, pBig)
		num.Mul(num, qpPow)

		diff := new(big.Int).Sub(qpPow, qPow)
		den := new(big.Int).Mul(qBig, diff)

		payCents = ceilDiv(num, den)
	}

	payStr := formatCents(payCents)
	bal := new(big.Int).Set(pCents)
	rows := make([]Tuple1, 0, months)
	prod := new(big.Int)
	totalDue := new(big.Int)

	for t := 1; t <= months; t++ {
		var interest *big.Int
		if rateMicro == 0 {
			interest = big.NewInt(0)
		} else {
			prod.Mul(bal, pBig)
			interest = roundHalfEven(prod, qBig)
		}

		totalDue.Add(bal, interest)
		if t == months || totalDue.Cmp(payCents) <= 0 {
			rows = append(rows, Tuple1{
				F0: formatCents(totalDue),
				F1: formatCents(interest),
				F2: "0.00",
			})
			break
		}

		bal.Sub(totalDue, payCents)
		rows = append(rows, Tuple1{
			F0: payStr,
			F1: formatCents(interest),
			F2: formatCents(bal),
		})
	}

	return rows, nil
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    public record Tuple1(String f0, String f1, String f2) {}

    private static final BigInteger MAX_RATE_MICRO = BigInteger.valueOf(100_000_000L);
    private static final BigInteger RATE_DENOM = BigInteger.valueOf(1_200_000_000L);

    public static List<Tuple1> amortize(String principal, String annual_rate_pct, long months) {
        BigInteger pCents = parseFixedDecimal(principal, 2);
        if (pCents.signum() <= 0) {
            throw new IllegalArgumentException("Principal must be > 0");
        }

        BigInteger rMicro = parseFixedDecimal(annual_rate_pct, 6);
        if (rMicro.compareTo(MAX_RATE_MICRO) > 0) {
            throw new IllegalArgumentException("Annual rate must be <= 100");
        }

        if (months < 1 || months > 1200) {
            throw new IllegalArgumentException("Months must be between 1 and 1200");
        }
        int n = (int) months;

        BigInteger mNum;
        BigInteger mDen;
        if (rMicro.signum() == 0) {
            mNum = BigInteger.ZERO;
            mDen = BigInteger.ONE;
        } else {
            BigInteger g = rMicro.gcd(RATE_DENOM);
            mNum = rMicro.divide(g);
            mDen = RATE_DENOM.divide(g);
        }

        BigInteger payCents;
        if (mNum.signum() == 0) {
            BigInteger nBig = BigInteger.valueOf(n);
            payCents = ceilDiv(pCents, nBig);
        } else {
            BigInteger u = mDen.add(mNum);
            BigInteger uPowN = u.pow(n);
            BigInteger vPowN = mDen.pow(n);
            BigInteger aNum = pCents.multiply(mNum).multiply(uPowN);
            BigInteger aDen = mDen.multiply(uPowN.subtract(vPowN));
            payCents = ceilDiv(aNum, aDen);
        }

        List<Tuple1> schedule = new ArrayList<>(n);
        String payFormatted = formatCents(payCents);
        BigInteger bal = pCents;

        for (int t = 1; t <= n; t++) {
            BigInteger interest = mNum.signum() == 0
                    ? BigInteger.ZERO
                    : roundHalfEvenDiv(bal.multiply(mNum), mDen);
            BigInteger totalDue = bal.add(interest);

            if (t == n || totalDue.compareTo(payCents) <= 0) {
                schedule.add(new Tuple1(formatCents(totalDue), formatCents(interest), "0.00"));
                break;
            } else {
                bal = totalDue.subtract(payCents);
                schedule.add(new Tuple1(payFormatted, formatCents(interest), formatCents(bal)));
            }
        }

        return schedule;
    }

    private static BigInteger parseFixedDecimal(String s, int maxFracDigits) {
        if (s == null || s.isEmpty()) {
            throw new IllegalArgumentException("Invalid numeric string");
        }
        int len = s.length();
        int dotIdx = -1;
        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);
            if (c == '.') {
                if (dotIdx != -1) {
                    throw new IllegalArgumentException("Multiple decimal points");
                }
                dotIdx = i;
            } else if (c < '0' || c > '9') {
                throw new IllegalArgumentException("Non-ASCII-digit character");
            }
        }

        StringBuilder sb = new StringBuilder(len + maxFracDigits);
        if (dotIdx == -1) {
            sb.append(s);
            for (int i = 0; i < maxFracDigits; i++) {
                sb.append('0');
            }
        } else {
            int fracLen = len - 1 - dotIdx;
            if (dotIdx == 0 || fracLen < 1 || fracLen > maxFracDigits) {
                throw new IllegalArgumentException("Invalid decimal format");
            }
            sb.append(s, 0, dotIdx);
            sb.append(s, dotIdx + 1, len);
            for (int i = fracLen; i < maxFracDigits; i++) {
                sb.append('0');
            }
        }

        return new BigInteger(sb.toString());
    }

    private static BigInteger ceilDiv(BigInteger num, BigInteger den) {
        BigInteger[] qr = num.divideAndRemainder(den);
        return qr[1].signum() == 0 ? qr[0] : qr[0].add(BigInteger.ONE);
    }

    private static BigInteger roundHalfEvenDiv(BigInteger num, BigInteger den) {
        BigInteger[] qr = num.divideAndRemainder(den);
        BigInteger q = qr[0];
        BigInteger r = qr[1];
        int cmp = r.shiftLeft(1).compareTo(den);
        if (cmp < 0) {
            return q;
        } else if (cmp > 0) {
            return q.add(BigInteger.ONE);
        } else {
            return q.testBit(0) ? q.add(BigInteger.ONE) : q;
        }
    }

    private static String formatCents(BigInteger cents) {
        String s = cents.toString();
        int len = s.length();
        if (len == 1) {
            return "0.0" + s;
        }
        if (len == 2) {
            return "0." + s;
        }
        return s.substring(0, len - 2) + "." + s.substring(len - 2);
    }
}

#include <algorithm>
#include <cstdint>
#include <numeric>
#include <stdexcept>
#include <string>
#include <tuple>
#include <utility>
#include <vector>

namespace {

class BigUInt {
public:
    static constexpr uint32_t BASE = 1'000'000'000U;

    BigUInt() = default;

    explicit BigUInt(uint64_t v) {
        while (v > 0) {
            limbs_.push_back(static_cast<uint32_t>(v % BASE));
            v /= BASE;
        }
    }

    static BigUInt from_decimal(const std::string& digits) {
        BigUInt res;
        size_t first_nonzero = 0;
        while (first_nonzero < digits.size() && digits[first_nonzero] == '0') {
            ++first_nonzero;
        }
        if (first_nonzero == digits.size()) {
            return res;
        }
        for (size_t end = digits.size(); end > first_nonzero;) {
            size_t start = (end - first_nonzero > 9) ? (end - 9) : first_nonzero;
            uint32_t val = 0;
            for (size_t i = start; i < end; ++i) {
                val = val * 10 + static_cast<uint32_t>(digits[i] - '0');
            }
            res.limbs_.push_back(val);
            end = start;
        }
        res.normalize();
        return res;
    }

    bool is_zero() const { return limbs_.empty(); }

    bool is_odd() const { return !limbs_.empty() && ((limbs_[0] & 1U) != 0U); }

    static int cmp(const BigUInt& a, const BigUInt& b) {
        if (a.limbs_.size() != b.limbs_.size()) {
            return a.limbs_.size() < b.limbs_.size() ? -1 : 1;
        }
        for (size_t i = a.limbs_.size(); i > 0; --i) {
            if (a.limbs_[i - 1] != b.limbs_[i - 1]) {
                return a.limbs_[i - 1] < b.limbs_[i - 1] ? -1 : 1;
            }
        }
        return 0;
    }

    static BigUInt add(const BigUInt& a, const BigUInt& b) {
        BigUInt res;
        size_t n = std::max(a.limbs_.size(), b.limbs_.size());
        res.limbs_.reserve(n + 1);
        uint64_t carry = 0;
        for (size_t i = 0; i < n || carry > 0; ++i) {
            uint64_t sum = carry;
            if (i < a.limbs_.size()) sum += a.limbs_[i];
            if (i < b.limbs_.size()) sum += b.limbs_[i];
            res.limbs_.push_back(static_cast<uint32_t>(sum % BASE));
            carry = sum / BASE;
        }
        return res;
    }

    static BigUInt add_u64(const BigUInt& a, uint64_t v) {
        if (v == 0) return a;
        return add(a, BigUInt(v));
    }

    // Precondition: a >= b
    static BigUInt sub(const BigUInt& a, const BigUInt& b) {
        BigUInt res;
        res.limbs_.resize(a.limbs_.size());
        int64_t borrow = 0;
        for (size_t i = 0; i < a.limbs_.size(); ++i) {
            int64_t diff = static_cast<int64_t>(a.limbs_[i]) - borrow;
            if (i < b.limbs_.size()) {
                diff -= static_cast<int64_t>(b.limbs_[i]);
            }
            if (diff < 0) {
                diff += BASE;
                borrow = 1;
            } else {
                borrow = 0;
            }
            res.limbs_[i] = static_cast<uint32_t>(diff);
        }
        res.normalize();
        return res;
    }

    // Precondition: v <= 2 * 10^9 so limb * v + carry fits in uint64_t
    static BigUInt mul_u64(const BigUInt& a, uint64_t v) {
        if (a.is_zero() || v == 0) return BigUInt();
        BigUInt res;
        res.limbs_.reserve(a.limbs_.size() + 2);
        uint64_t carry = 0;
        for (uint32_t limb : a.limbs_) {
            uint64_t prod = static_cast<uint64_t>(limb) * v + carry;
            res.limbs_.push_back(static_cast<uint32_t>(prod % BASE));
            carry = prod / BASE;
        }
        while (carry > 0) {
            res.limbs_.push_back(static_cast<uint32_t>(carry % BASE));
            carry /= BASE;
        }
        return res;
    }

    static BigUInt mul(const BigUInt& a, const BigUInt& b) {
        if (a.is_zero() || b.is_zero()) return BigUInt();
        BigUInt res;
        res.limbs_.assign(a.limbs_.size() + b.limbs_.size(), 0);
        for (size_t i = 0; i < a.limbs_.size(); ++i) {
            uint64_t carry = 0;
            uint64_t ai = a.limbs_[i];
            for (size_t j = 0; j < b.limbs_.size(); ++j) {
                uint64_t cur = res.limbs_[i + j] + ai * b.limbs_[j] + carry;
                res.limbs_[i + j] = static_cast<uint32_t>(cur % BASE);
                carry = cur / BASE;
            }
            size_t idx = i + b.limbs_.size();
            while (carry > 0) {
                uint64_t cur = res.limbs_[idx] + carry;
                res.limbs_[idx] = static_cast<uint32_t>(cur % BASE);
                carry = cur / BASE;
                ++idx;
            }
        }
        res.normalize();
        return res;
    }

    // Precondition: 0 < v <= 2 * 10^9
    static std::pair<BigUInt, uint64_t> divmod_u64(const BigUInt& a, uint64_t v) {
        if (a.is_zero()) return {BigUInt(), 0};
        BigUInt quot;
        quot.limbs_.resize(a.limbs_.size());
        uint64_t rem = 0;
        for (size_t i = a.limbs_.size(); i > 0; --i) {
            uint64_t cur = rem * BASE + a.limbs_[i - 1];
            quot.limbs_[i - 1] = static_cast<uint32_t>(cur / v);
            rem = cur % v;
        }
        quot.normalize();
        return {quot, rem};
    }

    static BigUInt div2(const BigUInt& a) {
        return divmod_u64(a, 2).first;
    }

    static BigUInt pow_u64(uint64_t base_val, long long exp) {
        BigUInt result(1);
        BigUInt base(base_val);
        while (exp > 0) {
            if ((exp & 1LL) != 0LL) {
                result = mul(result, base);
            }
            exp >>= 1LL;
            if (exp > 0) {
                base = mul(base, base);
            }
        }
        return result;
    }

    std::string to_string() const {
        if (limbs_.empty()) return "0";
        std::string s = std::to_string(limbs_.back());
        for (size_t i = limbs_.size() - 1; i > 0; --i) {
            std::string part = std::to_string(limbs_[i - 1]);
            s.append(9 - part.size(), '0');
            s += part;
        }
        return s;
    }

    std::string format_cents() const {
        std::string s = to_string();
        if (s.size() < 3) {
            s.insert(0, 3 - s.size(), '0');
        }
        s.insert(s.size() - 2, 1, '.');
        return s;
    }

private:
    std::vector<uint32_t> limbs_;

    void normalize() {
        while (!limbs_.empty() && limbs_.back() == 0) {
            limbs_.pop_back();
        }
    }
};

bool is_ascii_digit(char c) {
    return c >= '0' && c <= '9';
}

std::pair<std::string, std::string> parse_decimal_parts(const std::string& s, size_t max_frac) {
    if (s.empty()) {
        throw std::invalid_argument("Empty numeric string");
    }
    size_t dot_pos = s.find('.');
    if (dot_pos == std::string::npos) {
        for (char c : s) {
            if (!is_ascii_digit(c)) {
                throw std::invalid_argument("Invalid character in numeric string");
            }
        }
        return {s, ""};
    }
    if (dot_pos == 0) {
        throw std::invalid_argument("Missing integer digits before decimal point");
    }
    size_t frac_len = s.size() - dot_pos - 1;
    if (frac_len < 1 || frac_len > max_frac) {
        throw std::invalid_argument("Invalid number of fractional digits");
    }
    for (size_t i = 0; i < dot_pos; ++i) {
        if (!is_ascii_digit(s[i])) {
            throw std::invalid_argument("Invalid character in integer part");
        }
    }
    for (size_t i = dot_pos + 1; i < s.size(); ++i) {
        if (!is_ascii_digit(s[i])) {
            throw std::invalid_argument("Invalid character in fractional part");
        }
    }
    return {s.substr(0, dot_pos), s.substr(dot_pos + 1)};
}

BigUInt parse_principal_cents(const std::string& principal) {
    auto [int_part, frac_part] = parse_decimal_parts(principal, 2);
    frac_part.append(2 - frac_part.size(), '0');
    BigUInt cents = BigUInt::from_decimal(int_part + frac_part);
    if (cents.is_zero()) {
        throw std::invalid_argument("Principal must be greater than 0");
    }
    return cents;
}

uint64_t parse_rate_micro(const std::string& annual_rate_pct) {
    auto [int_part, frac_part] = parse_decimal_parts(annual_rate_pct, 6);
    frac_part.append(6 - frac_part.size(), '0');

    size_t nz = 0;
    while (nz < int_part.size() && int_part[nz] == '0') {
        ++nz;
    }
    std::string trimmed_int = int_part.substr(nz);
    if (trimmed_int.size() > 3) {
        throw std::invalid_argument("Annual rate exceeds 100%");
    }
    uint64_t int_val = 0;
    for (char c : trimmed_int) {
        int_val = int_val * 10 + static_cast<uint64_t>(c - '0');
    }
    uint64_t frac_val = 0;
    for (char c : frac_part) {
        frac_val = frac_val * 10 + static_cast<uint64_t>(c - '0');
    }
    uint64_t total_micro = int_val * 1'000'000ULL + frac_val;
    if (total_micro > 100'000'000ULL) {
        throw std::invalid_argument("Annual rate exceeds 100%");
    }
    return total_micro;
}

}  // namespace

std::vector<std::tuple<std::string, std::string, std::string>> amortize(
    const std::string& principal,
    const std::string& annual_rate_pct,
    long long months) {
    BigUInt p_cents = parse_principal_cents(principal);
    uint64_t rate_micro = parse_rate_micro(annual_rate_pct);
    if (months < 1 || months > 1200) {
        throw std::invalid_argument("Months must be between 1 and 1200");
    }

    // Monthly rate m = rate_micro / 1,200,000,000 = p / q in lowest terms
    constexpr uint64_t DENOM_RAW = 1'200'000'000ULL;
    uint64_t g = std::gcd(rate_micro, DENOM_RAW);
    uint64_t p = rate_micro / g;
    uint64_t q = DENOM_RAW / g;

    BigUInt pay_cents;
    if (p == 0) {
        auto [quot, rem] = BigUInt::divmod_u64(p_cents, static_cast<uint64_t>(months));
        pay_cents = (rem > 0) ? BigUInt::add_u64(quot, 1) : quot;
    } else {
        // A = P * p * (q + p)^n / (q * ((q + p)^n - q^n))
        BigUInt qp_pow = BigUInt::pow_u64(q + p, months);
        BigUInt q_pow = BigUInt::pow_u64(q, months);
        BigUInt num = BigUInt::mul(BigUInt::mul_u64(p_cents, p), qp_pow);
        BigUInt den = BigUInt::mul_u64(BigUInt::sub(qp_pow, q_pow), q);

        // Binary search for ceil(num / den); since m <= 1/12 and n >= 1, A <= P * 13/12 < 2 * P + 10
        BigUInt lo(1);
        BigUInt hi = BigUInt::add_u64(BigUInt::mul_u64(p_cents, 2), 10);
        while (BigUInt::cmp(lo, hi) < 0) {
            BigUInt mid = BigUInt::div2(BigUInt::add(lo, hi));
            if (BigUInt::cmp(BigUInt::mul(mid, den), num) >= 0) {
                hi = mid;
            } else {
                lo = BigUInt::add_u64(mid, 1);
            }
        }
        pay_cents = lo;
    }

    std::vector<std::tuple<std::string, std::string, std::string>> schedule;
    schedule.reserve(static_cast<size_t>(months));

    BigUInt bal = p_cents;
    std::string pay_str = pay_cents.format_cents();

    for (long long t = 1; t <= months; ++t) {
        BigUInt interest;
        if (p > 0) {
            auto [quot, rem] = BigUInt::divmod_u64(BigUInt::mul_u64(bal, p), q);
            uint64_t twice_rem = rem * 2;
            if (twice_rem > q || (twice_rem == q && quot.is_odd())) {
                interest = BigUInt::add_u64(quot, 1);
            } else {
                interest = std::move(quot);
            }
        }

        BigUInt total_due = BigUInt::add(bal, interest);
        if (t == months || BigUInt::cmp(total_due, pay_cents) <= 0) {
            schedule.emplace_back(total_due.format_cents(), interest.format_cents(), "0.00");
            break;
        }

        bal = BigUInt::sub(total_due, pay_cents);
        schedule.emplace_back(pay_str, interest.format_cents(), bal.format_cents());
    }

    return schedule;
}

const PRINCIPAL_RE = /^[0-9]+(?:\.[0-9]{1,2})?$/;
const RATE_RE = /^[0-9]+(?:\.[0-9]{1,6})?$/;

function gcd(a: bigint, b: bigint): bigint {
  while (b !== 0n) {
    const t = a % b;
    a = b;
    b = t;
  }
  return a;
}

function parseScaled(s: string, scaleDigits: number): bigint {
  const dot = s.indexOf(".");
  const intPart = dot === -1 ? s : s.slice(0, dot);
  const fracPart = (dot === -1 ? "" : s.slice(dot + 1)).padEnd(scaleDigits, "0");
  return BigInt(intPart) * 10n ** BigInt(scaleDigits) + BigInt(fracPart);
}

function roundHalfToEven(num: bigint, den: bigint): bigint {
  const quot = num / den;
  const rem = num % den;
  const twiceRem = rem * 2n;
  if (twiceRem < den) {
    return quot;
  }
  if (twiceRem > den) {
    return quot + 1n;
  }
  return quot % 2n === 0n ? quot : quot + 1n;
}

function formatCents(cents: bigint): string {
  const whole = cents / 100n;
  const rem = cents % 100n;
  return `${whole}.${rem < 10n ? "0" : ""}${rem}`;
}

export function amortize(
  principal: string,
  annual_rate_pct: string,
  months: number
): [string, string, string][] {
  if (
    typeof principal !== "string" ||
    typeof annual_rate_pct !== "string" ||
    typeof months !== "number" ||
    !Number.isInteger(months) ||
    months < 1 ||
    months > 1200
  ) {
    throw new Error("Invalid input");
  }

  if (!PRINCIPAL_RE.test(principal)) {
    throw new Error("Invalid principal format");
  }
  const principalCents = parseScaled(principal, 2);
  if (principalCents <= 0n) {
    throw new Error("Principal must be > 0");
  }

  if (!RATE_RE.test(annual_rate_pct)) {
    throw new Error("Invalid annual_rate_pct format");
  }
  const rateMicroPct = parseScaled(annual_rate_pct, 6);
  if (rateMicroPct > 100_000_000n) {
    throw new Error("Annual rate must be <= 100");
  }

  const n = BigInt(months);
  const rawDen = 1_200_000_000n;
  const g = gcd(rateMicroPct, rawDen);
  const p = rateMicroPct / g;
  const q = rawDen / g;

  let pay: bigint;
  if (p === 0n) {
    pay = (principalCents + n - 1n) / n;
  } else {
    const qpPowN = (q + p) ** n;
    const qPowN = q ** n;
    const num = principalCents * p * qpPowN;
    const den = q * (qpPowN - qPowN);
    pay = (num + den - 1n) / den;
  }

  const schedule: [string, string, string][] = [];
  let bal = principalCents;

  for (let t = 1; t <= months; t++) {
    const interest = p === 0n ? 0n : roundHalfToEven(bal * p, q);
    if (t === months || bal + interest <= pay) {
      const payment = bal + interest;
      bal = 0n;
      schedule.push([formatCents(payment), formatCents(interest), formatCents(bal)]);
      break;
    } else {
      const payment = pay;
      bal -= payment - interest;
      schedule.push([formatCents(payment), formatCents(interest), formatCents(bal)]);
    }
  }

  return schedule;
}

package main

import (
	"errors"
	"math/bits"
)

const alphabet = "0123456789abcdefghijklmnopqrstuvwxyz"

func absUint64(x int) uint64 {
	if x < 0 {
		return ^uint64(x) + 1
	}
	return uint64(x)
}

func FormatBase(p int, q int, base int, k int) (string, error) {
	if q == 0 {
		return "", errors.New("q must not be zero")
	}
	if base < 2 || base > 36 {
		return "", errors.New("base must be between 2 and 36")
	}
	if k < 0 {
		return "", errors.New("k must be non-negative")
	}
	if p == 0 {
		return "0", nil
	}

	neg := (p < 0) != (q < 0)
	up := absUint64(p)
	uq := absUint64(q)
	ub := uint64(base)

	intPart := up / uq
	rem := up % uq

	var intTmp [64]byte
	intLen := 0
	if intPart == 0 {
		intTmp[0] = 0
		intLen = 1
	} else {
		for intPart > 0 {
			intTmp[intLen] = byte(intPart % ub)
			intPart /= ub
			intLen++
		}
	}

	// buf[0] is a guard zero for carry propagation; buf[1:1+intLen] holds integer digits;
	// buf[1+intLen:1+intLen+k] holds the k fractional digits.
	buf := make([]byte, 1+intLen+k)
	for i := 0; i < intLen; i++ {
		buf[1+i] = intTmp[intLen-1-i]
	}

	fracOffset := 1 + intLen
	for i := 0; i < k && rem != 0; i++ {
		hi, lo := bits.Mul64(rem, ub)
		var d uint64
		d, rem = bits.Div64(hi, lo, uq)
		buf[fracOffset+i] = byte(d)
	}

	roundUp := false
	if rem > uq-rem {
		roundUp = true
	} else if rem == uq-rem && rem != 0 {
		// Exact tie: round up iff N_floor is odd.
		if base&1 == 0 {
			roundUp = (buf[len(buf)-1] & 1) == 1
		} else {
			var parity byte
			for _, d := range buf {
				parity ^= d & 1
			}
			roundUp = parity == 1
		}
	}

	if roundUp {
		idx := len(buf) - 1
		maxDigit := byte(base - 1)
		for buf[idx] == maxDigit {
			buf[idx] = 0
			idx--
		}
		buf[idx]++
	}

	intStart := 1
	if buf[0] != 0 {
		intStart = 0
	}
	intDigits := buf[intStart:fracOffset]

	fracDigits := buf[fracOffset:]
	fracEnd := len(fracDigits)
	for fracEnd > 0 && fracDigits[fracEnd-1] == 0 {
		fracEnd--
	}
	fracDigits = fracDigits[:fracEnd]

	if len(intDigits) == 1 && intDigits[0] == 0 && len(fracDigits) == 0 {
		return "0", nil
	}

	outLen := len(intDigits)
	if neg {
		outLen++
	}
	if len(fracDigits) > 0 {
		outLen += 1 + len(fracDigits)
	}

	out := make([]byte, 0, outLen)
	if neg {
		out = append(out, '-')
	}
	for _, d := range intDigits {
		out = append(out, alphabet[d])
	}
	if len(fracDigits) > 0 {
		out = append(out, '.')
		for _, d := range fracDigits {
			out = append(out, alphabet[d])
		}
	}

	return string(out), nil
}

import java.util.*;

public final class Solution {
    private static final char[] DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz".toCharArray();

    private Solution() {}

    public static String formatBase(long p, long q, long base, long k) {
        if (q == 0 || base < 2 || base > 36 || k < 0) {
            throw new IllegalArgumentException();
        }
        if (p == 0) {
            return "0";
        }

        boolean negative = (p < 0) ^ (q < 0);
        long up = p < 0 ? -p : p;
        long uq = q < 0 ? -q : q;
        int b = (int) base;

        long intPart = Long.divideUnsigned(up, uq);
        long r = Long.remainderUnsigned(up, uq);

        if (r == 0) {
            String intStr = Long.toUnsignedString(intPart, b);
            return negative ? "-" + intStr : intStr;
        }

        int cap = (int) Math.min(k, 4096L);
        byte[] frac = new byte[cap];
        int len = 0;
        int parity = (int) (intPart & 1L);
        int bParity = b & 1;

        if (uq > 0 && uq <= Long.MAX_VALUE / b) {
            while (len < k && r != 0) {
                if (len == frac.length) {
                    frac = Arrays.copyOf(frac, (int) Math.min(k, frac.length * 2L));
                }
                long prod = r * b;
                int d = (int) (prod / uq);
                r = prod % uq;
                frac[len++] = (byte) d;
                parity = (parity & bParity) ^ (d & 1);
            }
        } else {
            int msb = 31 - Integer.numberOfLeadingZeros(b);
            while (len < k && r != 0) {
                if (len == frac.length) {
                    frac = Arrays.copyOf(frac, (int) Math.min(k, frac.length * 2L));
                }
                int d = 0;
                long rem = 0;
                for (int bit = msb; bit >= 0; bit--) {
                    d <<= 1;
                    rem <<= 1;
                    if (Long.compareUnsigned(rem, uq) >= 0) {
                        rem -= uq;
                        d++;
                    }
                    if (((b >>> bit) & 1) != 0) {
                        rem += r;
                        if (Long.compareUnsigned(rem, uq) >= 0) {
                            rem -= uq;
                            d++;
                        }
                    }
                }
                r = rem;
                frac[len++] = (byte) d;
                parity = (parity & bParity) ^ (d & 1);
            }
        }

        if (r != 0) {
            int cmp = Long.compareUnsigned(r << 1, uq);
            if (cmp > 0 || (cmp == 0 && parity == 1)) {
                int i = len - 1;
                while (i >= 0 && frac[i] == b - 1) {
                    frac[i] = 0;
                    i--;
                }
                if (i >= 0) {
                    frac[i]++;
                } else {
                    intPart++;
                }
            }
        }

        while (len > 0 && frac[len - 1] == 0) {
            len--;
        }

        if (intPart == 0 && len == 0) {
            return "0";
        }

        String intStr = Long.toUnsignedString(intPart, b);
        if (len == 0) {
            return negative ? "-" + intStr : intStr;
        }

        int signLen = negative ? 1 : 0;
        int intLen = intStr.length();
        char[] out = new char[signLen + intLen + 1 + len];
        int pos = 0;
        if (negative) {
            out[pos++] = '-';
        }
        intStr.getChars(0, intLen, out, pos);
        pos += intLen;
        out[pos++] = '.';
        for (int i = 0; i < len; i++) {
            out[pos + i] = DIGITS[frac[i]];
        }
        return new String(out);
    }
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <limits>
#include <stdexcept>
#include <string>
#include <vector>

std::string format_base(long long p, long long q, long long base, long long k) {
    if (q == 0) {
        throw std::invalid_argument("q must not be zero");
    }
    if (base < 2 || base > 36) {
        throw std::invalid_argument("base must be in 2..36");
    }
    if (k < 0) {
        throw std::invalid_argument("k must be non-negative");
    }

    if (p == 0) {
        return "0";
    }

    const bool negative = (p < 0) != (q < 0);
    const unsigned long long up = (p < 0)
        ? (0ULL - static_cast<unsigned long long>(p))
        : static_cast<unsigned long long>(p);
    const unsigned long long uq = (q < 0)
        ? (0ULL - static_cast<unsigned long long>(q))
        : static_cast<unsigned long long>(q);
    const unsigned long long ub = static_cast<unsigned long long>(base);

    unsigned long long int_part = up / uq;
    unsigned long long rem = up % uq;
    unsigned long long parity = int_part & 1ULL;
    const unsigned long long base_parity = ub & 1ULL;

    std::vector<std::uint8_t> frac_digits;
    if (rem != 0 && k > 0) {
        frac_digits.reserve(static_cast<std::size_t>(std::min<long long>(k, 350000LL)));
    }

    if (uq <= std::numeric_limits<unsigned long long>::max() / ub) {
        for (long long i = 0; i < k && rem != 0; ++i) {
            const unsigned long long prod = rem * ub;
            const unsigned long long d = prod / uq;
            rem = prod % uq;
            frac_digits.push_back(static_cast<std::uint8_t>(d));
            parity = (parity & base_parity) ^ (d & 1ULL);
        }
    } else {
        for (long long i = 0; i < k && rem != 0; ++i) {
#ifdef __SIZEOF_INT128__
            const unsigned __int128 prod = static_cast<unsigned __int128>(rem) * ub;
            const unsigned long long d = static_cast<unsigned long long>(prod / uq);
            rem = static_cast<unsigned long long>(prod % uq);
#else
            unsigned long long d = 0;
            unsigned long long r = 0;
            for (int bit = 5; bit >= 0; --bit) {
                d <<= 1;
                r <<= 1;
                if (r >= uq) {
                    r -= uq;
                    ++d;
                }
                if ((ub >> bit) & 1ULL) {
                    r += rem;
                    if (r >= uq) {
                        r -= uq;
                        ++d;
                    }
                }
            }
            rem = r;
#endif
            frac_digits.push_back(static_cast<std::uint8_t>(d));
            parity = (parity & base_parity) ^ (d & 1ULL);
        }
    }

    const unsigned long long twice_rem = rem << 1;
    const bool round_up = (twice_rem > uq) || (twice_rem == uq && parity == 1ULL);

    if (round_up) {
        unsigned long long carry = 1;
        for (std::size_t i = frac_digits.size(); i > 0; --i) {
            const unsigned long long val = static_cast<unsigned long long>(frac_digits[i - 1]) + carry;
            if (val == ub) {
                frac_digits[i - 1] = 0;
            } else {
                frac_digits[i - 1] = static_cast<std::uint8_t>(val);
                carry = 0;
                break;
            }
        }
        if (carry != 0) {
            ++int_part;
        }
    }

    while (!frac_digits.empty() && frac_digits.back() == 0) {
        frac_digits.pop_back();
    }

    if (int_part == 0 && frac_digits.empty()) {
        return "0";
    }

    static constexpr char DIGITS[] = "0123456789abcdefghijklmnopqrstuvwxyz";

    std::string int_str;
    if (int_part == 0) {
        int_str = "0";
    } else {
        while (int_part > 0) {
            int_str.push_back(DIGITS[int_part % ub]);
            int_part /= ub;
        }
        std::reverse(int_str.begin(), int_str.end());
    }

    std::string result;
    result.reserve((negative ? 1U : 0U) + int_str.size() +
                   (frac_digits.empty() ? 0U : 1U + frac_digits.size()));
    if (negative) {
        result.push_back('-');
    }
    result.append(int_str);
    if (!frac_digits.empty()) {
        result.push_back('.');
        for (std::uint8_t d : frac_digits) {
            result.push_back(DIGITS[d]);
        }
    }

    return result;
}

function powBase(base: number, k: number): bigint {
  if (k === 0) return 1n;
  let tz = 0;
  let odd = base;
  while ((odd & 1) === 0) {
    odd >>= 1;
    tz++;
  }
  const oddPow = odd === 1 ? 1n : BigInt(odd) ** BigInt(k);
  return tz === 0 ? oddPow : oddPow << (BigInt(tz) * BigInt(k));
}

export function formatBase(p: number, q: number, base: number, k: number): string {
  if (
    !Number.isInteger(p) ||
    !Number.isInteger(q) ||
    !Number.isInteger(base) ||
    !Number.isInteger(k)
  ) {
    throw new Error("All arguments must be integers");
  }
  if (q === 0 || base < 2 || base > 36 || k < 0) {
    throw new Error("Invalid arguments");
  }

  if (p === 0) {
    return "0";
  }

  const negative = p < 0 !== q < 0;
  let absP = BigInt(p);
  if (absP < 0n) absP = -absP;
  let absQ = BigInt(q);
  if (absQ < 0n) absQ = -absQ;

  let intPart = absP / absQ;
  const remP = absP % absQ;

  if (remP === 0n) {
    return (negative ? "-" : "") + intPart.toString(base);
  }

  const scale = powBase(base, k);
  const scaledRem = remP * scale;
  let fracPart = scaledRem / absQ;
  const r = scaledRem % absQ;

  const twoR = r << 1n;
  if (twoR > absQ) {
    fracPart += 1n;
  } else if (twoR === absQ) {
    const isOdd = (((intPart * (scale & 1n)) ^ fracPart) & 1n) === 1n;
    if (isOdd) {
      fracPart += 1n;
    }
  }

  if (fracPart === scale) {
    intPart += 1n;
    fracPart = 0n;
  }

  if (intPart === 0n && fracPart === 0n) {
    return "0";
  }

  const sign = negative ? "-" : "";
  const intStr = intPart.toString(base);

  if (fracPart === 0n) {
    return sign + intStr;
  }

  const rawFrac = fracPart.toString(base);
  const leadingZeros = "0".repeat(k - rawFrac.length);
  let end = rawFrac.length;
  while (end > 0 && rawFrac.charCodeAt(end - 1) === 48) {
    end--;
  }

  return sign + intStr + "." + leadingZeros + rawFrac.slice(0, end);
}

package main

import (
	"errors"
	"math/big"
	"strconv"
)

func parseDecimal(x string) (neg bool, digits string, shift int64, err error) {
	n := len(x)
	if n == 0 {
		return false, "", 0, errors.New("empty string")
	}
	i := 0
	if x[i] == '+' || x[i] == '-' {
		neg = x[i] == '-'
		i++
	}

	intStart := i
	for i < n && x[i] >= '0' && x[i] <= '9' {
		i++
	}
	intEnd := i

	var fracStart, fracEnd int
	if i < n && x[i] == '.' {
		i++
		fracStart = i
		for i < n && x[i] >= '0' && x[i] <= '9' {
			i++
		}
		fracEnd = i
	}

	intLen := intEnd - intStart
	fracLen := fracEnd - fracStart
	if intLen+fracLen == 0 {
		return false, "", 0, errors.New("invalid mantissa")
	}

	var exp int64
	if i < n && (x[i] == 'e' || x[i] == 'E') {
		i++
		expNeg := false
		if i < n && (x[i] == '+' || x[i] == '-') {
			expNeg = x[i] == '-'
			i++
		}
		expStart := i
		capExp := int64(n) + 50
		var expVal int64
		for i < n && x[i] >= '0' && x[i] <= '9' {
			if expVal < capExp {
				expVal = expVal*10 + int64(x[i]-'0')
			}
			i++
		}
		if i == expStart {
			return false, "", 0, errors.New("invalid exponent")
		}
		if expNeg {
			exp = -expVal
		} else {
			exp = expVal
		}
	}

	if i != n {
		return false, "", 0, errors.New("unexpected trailing characters")
	}

	raw := x[intStart:intEnd] + x[fracStart:fracEnd]
	start := 0
	for start < len(raw) && raw[start] == '0' {
		start++
	}
	if start == len(raw) {
		return false, "", 0, nil
	}

	end := len(raw)
	var trailingZeros int64
	for end > start && raw[end-1] == '0' {
		end--
		trailingZeros++
	}

	digits = raw[start:end]
	shift = exp - int64(fracLen) + trailingZeros
	return neg, digits, shift, nil
}

func formatFrac(neg bool, a, b int64) string {
	if a == 0 {
		return "0/1"
	}
	if neg {
		return "-" + strconv.FormatInt(a, 10) + "/" + strconv.FormatInt(b, 10)
	}
	return strconv.FormatInt(a, 10) + "/" + strconv.FormatInt(b, 10)
}

func ClosestFraction(x string, max_num int, max_den int) (string, error) {
	if max_num < 0 || max_den < 1 {
		return "", errors.New("invalid bounds")
	}

	neg, digits, shift, err := parseDecimal(x)
	if err != nil {
		return "", err
	}

	if digits == "" || max_num == 0 {
		return "0/1", nil
	}

	maxNum := int64(max_num)
	maxDen := int64(max_den)

	ld := int64(len(digits))
	if ld-1+shift >= 20 {
		return formatFrac(neg, maxNum, 1), nil
	}
	if ld+shift <= -20 {
		return "0/1", nil
	}

	D, ok := new(big.Int).SetString(digits, 10)
	if !ok {
		return "", errors.New("failed to parse digits")
	}

	var P, Q *big.Int
	if shift >= 0 {
		pow10 := new(big.Int).Exp(big.NewInt(10), big.NewInt(shift), nil)
		P = new(big.Int).Mul(D, pow10)
		Q = big.NewInt(1)
	} else {
		P = D
		Q = new(big.Int).Exp(big.NewInt(10), big.NewInt(-shift), nil)
	}

	maxP := new(big.Int).Mul(big.NewInt(maxNum), Q)
	if P.Cmp(maxP) >= 0 {
		return formatFrac(neg, maxNum, 1), nil
	}

	var a1, b1, a2, b2 int64
	var numL, numR *big.Int

	cmpPQ := P.Cmp(Q)
	if cmpPQ == 0 {
		return formatFrac(neg, 1, 1), nil
	} else if cmpPQ > 0 {
		qBig, rem := new(big.Int).QuoRem(P, Q, new(big.Int))
		q := qBig.Int64()
		if rem.Sign() == 0 {
			return formatFrac(neg, q, 1), nil
		}
		a1, b1 = q, 1
		a2, b2 = q+1, 1
		numL = rem
		numR = new(big.Int).Sub(Q, rem)
	} else {
		a1, b1 = 0, 1
		a2, b2 = 1, 1
		numL = new(big.Int).Set(P)
		numR = new(big.Int).Sub(Q, P)
	}

	qBig := new(big.Int)
	rem := new(big.Int)
	kMaxBig := new(big.Int)
	tmp := new(big.Int)

	for {
		if a1 > maxNum-a2 || b1 > maxDen-b2 {
			break
		}

		c := numL.Cmp(numR)
		if c == 0 {
			return formatFrac(neg, a1+a2, b1+b2), nil
		} else if c > 0 {
			kMax := (maxDen - b1) / b2
			if a2 > 0 {
				if ka := (maxNum - a1) / a2; ka < kMax {
					kMax = ka
				}
			}
			kMaxBig.SetInt64(kMax)
			qBig.QuoRem(numL, numR, rem)
			if qBig.Cmp(kMaxBig) <= 0 {
				k := qBig.Int64()
				a1 += k * a2
				b1 += k * b2
				numL, rem = rem, numL
				if numL.Sign() == 0 {
					return formatFrac(neg, a1, b1), nil
				}
			} else {
				k := kMax
				a1 += k * a2
				b1 += k * b2
				numL.Sub(numL, tmp.Mul(kMaxBig, numR))
				break
			}
		} else {
			kMax := (maxDen - b2) / b1
			if a1 > 0 {
				if ka := (maxNum - a2) / a1; ka < kMax {
					kMax = ka
				}
			}
			kMaxBig.SetInt64(kMax)
			qBig.QuoRem(numR, numL, rem)
			if qBig.Cmp(kMaxBig) <= 0 {
				k := qBig.Int64()
				a2 += k * a1
				b2 += k * b1
				numR, rem = rem, numR
				if numR.Sign() == 0 {
					return formatFrac(neg, a2, b2), nil
				}
			} else {
				k := kMax
				a2 += k * a1
				b2 += k * b1
				numR.Sub(numR, tmp.Mul(kMaxBig, numL))
				break
			}
		}
	}

	lhs := new(big.Int).Mul(numL, big.NewInt(b2))
	rhs := new(big.Int).Mul(numR, big.NewInt(b1))
	c := lhs.Cmp(rhs)
	if c < 0 {
		return formatFrac(neg, a1, b1), nil
	}
	if c > 0 {
		return formatFrac(neg, a2, b2), nil
	}
	if b2 < b1 {
		return formatFrac(neg, a2, b2), nil
	}
	return formatFrac(neg, a1, b1), nil
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    private Solution() {}

    public static String closestFraction(String x, long max_num, long max_den) {
        if (x == null || max_num < 0 || max_den < 1) {
            throw new IllegalArgumentException("Invalid arguments");
        }

        int n = x.length();
        if (n == 0) {
            throw new IllegalArgumentException("Empty literal");
        }

        int i = 0;
        boolean negative = false;
        char c0 = x.charAt(0);
        if (c0 == '+' || c0 == '-') {
            negative = (c0 == '-');
            i++;
            if (i == n) {
                throw new IllegalArgumentException("Missing mantissa");
            }
        }

        int intStart = i;
        while (i < n && isAsciiDigit(x.charAt(i))) {
            i++;
        }
        int intLen = i - intStart;

        int fracStart = -1;
        int fracLen = 0;
        if (i < n && x.charAt(i) == '.') {
            i++;
            fracStart = i;
            while (i < n && isAsciiDigit(x.charAt(i))) {
                i++;
            }
            fracLen = i - fracStart;
        }

        if (intLen + fracLen == 0) {
            throw new IllegalArgumentException("Invalid mantissa");
        }

        BigInteger exp = BigInteger.ZERO;
        if (i < n && (x.charAt(i) == 'e' || x.charAt(i) == 'E')) {
            i++;
            if (i == n) {
                throw new IllegalArgumentException("Empty exponent");
            }
            boolean expNeg = false;
            char ce = x.charAt(i);
            if (ce == '+' || ce == '-') {
                expNeg = (ce == '-');
                i++;
            }
            int expStart = i;
            while (i < n && isAsciiDigit(x.charAt(i))) {
                i++;
            }
            if (i == expStart) {
                throw new IllegalArgumentException("Missing exponent digits");
            }
            exp = new BigInteger(x.substring(expStart, i));
            if (expNeg) {
                exp = exp.negate();
            }
        }

        if (i != n) {
            throw new IllegalArgumentException("Unexpected trailing characters");
        }

        StringBuilder rawDigits = new StringBuilder(intLen + fracLen);
        rawDigits.append(x, intStart, intStart + intLen);
        if (fracLen > 0) {
            rawDigits.append(x, fracStart, fracStart + fracLen);
        }

        int firstNonZero = 0;
        int totalDigits = rawDigits.length();
        while (firstNonZero < totalDigits && rawDigits.charAt(firstNonZero) == '0') {
            firstNonZero++;
        }

        if (firstNonZero == totalDigits || max_num == 0) {
            return "0/1";
        }

        int lastNonZero = totalDigits - 1;
        while (lastNonZero > firstNonZero && rawDigits.charAt(lastNonZero) == '0') {
            lastNonZero--;
        }

        int trailingZeros = (totalDigits - 1) - lastNonZero;
        String sigDigits = rawDigits.substring(firstNonZero, lastNonZero + 1);
        int d = sigDigits.length();

        // Exact value |x| = sigInt * 10^scale10, with 10^(d-1) <= sigInt < 10^d
        BigInteger scale10 = exp.subtract(BigInteger.valueOf(fracLen)).add(BigInteger.valueOf(trailingZeros));

        if (scale10.add(BigInteger.valueOf(d - 1)).compareTo(BigInteger.valueOf(20)) >= 0) {
            return formatFraction(negative, max_num, 1);
        }
        if (scale10.add(BigInteger.valueOf(d)).compareTo(BigInteger.valueOf(-20)) <= 0) {
            return "0/1";
        }

        int s = scale10.intValueExact();
        BigInteger sigInt = new BigInteger(sigDigits);
        BigInteger P;
        BigInteger Q;
        if (s >= 0) {
            P = sigInt.multiply(BigInteger.TEN.pow(s));
            Q = BigInteger.ONE;
        } else {
            P = sigInt;
            Q = BigInteger.TEN.pow(-s);
        }

        // Stern-Brocot search with bounds [0, max_num] for numerator and [1, max_den] for denominator.
        // L = p1/q1 (valid), R = p2/q2 (1/0 represents +infinity; valid once q2 > 0).
        long p1 = 0, q1 = 1;
        long p2 = 1, q2 = 0;

        BigInteger numL;
        BigInteger numR;

        while (true) {
            numL = BigInteger.valueOf(q1).multiply(P).subtract(BigInteger.valueOf(p1).multiply(Q));
            if (numL.signum() == 0) {
                return formatFraction(negative, p1, q1);
            }
            if (q2 == 0) {
                numR = Q;
            } else {
                numR = BigInteger.valueOf(p2).multiply(Q).subtract(BigInteger.valueOf(q2).multiply(P));
                if (numR.signum() == 0) {
                    return formatFraction(negative, p2, q2);
                }
            }

            if (p1 > max_num - p2 || q1 > max_den - q2) {
                break;
            }

            if (numR.compareTo(numL) <= 0) {
                // Mediant (p1 + p2)/(q1 + q2) <= P/Q; advance L
                long kLimit = (max_num - p1) / p2;
                if (q2 > 0) {
                    kLimit = Math.min(kLimit, (max_den - q1) / q2);
                }
                BigInteger kRat = numL.divide(numR);
                long k = kRat.compareTo(BigInteger.valueOf(kLimit)) > 0 ? kLimit : kRat.longValue();
                p1 += k * p2;
                q1 += k * q2;
            } else {
                // Mediant (p1 + p2)/(q1 + q2) > P/Q; advance R
                long kLimit = (max_den - q2) / q1;
                if (p1 > 0) {
                    kLimit = Math.min(kLimit, (max_num - p2) / p1);
                }
                BigInteger kRat = numR.divide(numL);
                long k = kRat.compareTo(BigInteger.valueOf(kLimit)) > 0 ? kLimit : kRat.longValue();
                p2 += k * p1;
                q2 += k * q1;
            }
        }

        if (q2 == 0) {
            return formatFraction(negative, p1, q1);
        }

        BigInteger dL = BigInteger.valueOf(q2).multiply(numL);
        BigInteger dR = BigInteger.valueOf(q1).multiply(numR);
        int cmp = dL.compareTo(dR);
        if (cmp < 0) {
            return formatFraction(negative, p1, q1);
        } else if (cmp > 0) {
            return formatFraction(negative, p2, q2);
        } else {
            // Tie: smaller denominator wins; if equal, smaller absolute value (L < R) wins.
            if (q2 < q1) {
                return formatFraction(negative, p2, q2);
            }
            return formatFraction(negative, p1, q1);
        }
    }

    private static boolean isAsciiDigit(char c) {
        return c >= '0' && c <= '9';
    }

    private static String formatFraction(boolean negative, long p, long q) {
        if (p == 0) {
            return "0/1";
        }
        return (negative ? "-" : "") + p + "/" + q;
    }
}

#include <algorithm>
#include <bit>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

namespace {

__extension__ using u128 = unsigned __int128;

struct BigInt {
    std::vector<uint64_t> d;

    void normalize() {
        while (!d.empty() && d.back() == 0) {
            d.pop_back();
        }
    }

    void mul_add(uint64_t m, uint64_t a) {
        u128 carry = a;
        for (size_t i = 0; i < d.size(); ++i) {
            u128 cur = (u128)d[i] * m + carry;
            d[i] = (uint64_t)cur;
            carry = cur >> 64;
        }
        if (carry > 0) {
            d.push_back((uint64_t)carry);
        }
        normalize();
    }
};

int cmp(const BigInt& a, const BigInt& b) {
    if (a.d.size() != b.d.size()) {
        return a.d.size() < b.d.size() ? -1 : 1;
    }
    for (size_t i = a.d.size(); i-- > 0;) {
        if (a.d[i] != b.d[i]) {
            return a.d[i] < b.d[i] ? -1 : 1;
        }
    }
    return 0;
}

BigInt mul_u64(const BigInt& x, uint64_t m) {
    BigInt res;
    if (m == 0 || x.d.empty()) {
        return res;
    }
    res.d.resize(x.d.size());
    u128 carry = 0;
    for (size_t i = 0; i < x.d.size(); ++i) {
        u128 cur = (u128)x.d[i] * m + carry;
        res.d[i] = (uint64_t)cur;
        carry = cur >> 64;
    }
    if (carry > 0) {
        res.d.push_back((uint64_t)carry);
    }
    return res;
}

void sub_assign(BigInt& a, const BigInt& b) {
    uint64_t borrow = 0;
    for (size_t i = 0; i < a.d.size(); ++i) {
        uint64_t bi = (i < b.d.size()) ? b.d[i] : 0ULL;
        u128 sub = (u128)bi + borrow;
        if (a.d[i] >= sub) {
            a.d[i] -= (uint64_t)sub;
            borrow = 0;
        } else {
            a.d[i] = (uint64_t)(((u128)1 << 64) + a.d[i] - sub);
            borrow = 1;
        }
    }
    a.normalize();
}

constexpr uint64_t POW10[19] = {
    1ULL,
    10ULL,
    100ULL,
    1000ULL,
    10000ULL,
    100000ULL,
    1000000ULL,
    10000000ULL,
    100000000ULL,
    1000000000ULL,
    10000000000ULL,
    100000000000ULL,
    1000000000000ULL,
    10000000000000ULL,
    100000000000000ULL,
    1000000000000000ULL,
    10000000000000000ULL,
    100000000000000000ULL,
    1000000000000000000ULL
};

void mul_pow10(BigInt& x, long long e) {
    while (e >= 18) {
        x.mul_add(POW10[18], 0);
        e -= 18;
    }
    if (e > 0) {
        x.mul_add(POW10[e], 0);
    }
}

uint64_t div_step(BigInt& A, const BigInt& B, uint64_t k_lim, bool& exceeded) {
    uint64_t lim = k_lim + 1ULL;
    BigInt limB = mul_u64(B, lim);
    if (cmp(A, limB) > 0) {
        exceeded = true;
        if (k_lim > 0) {
            sub_assign(A, mul_u64(B, k_lim));
        }
        return k_lim;
    }

    exceeded = false;
    size_t m = B.d.size();
    if (m == 1) {
        u128 a128 = (u128)A.d[0] + (A.d.size() > 1 ? ((u128)A.d[1] << 64) : 0);
        uint64_t q = (uint64_t)((a128 - 1) / B.d[0]);
        uint64_t rem = (uint64_t)(a128 - (u128)q * B.d[0]);
        A.d.assign(1, rem);
        return q;
    }

    uint64_t top = B.d[m - 1];
    int z = std::countl_zero(top);
    uint64_t b_hi = 0;
    u128 a_hi = 0;
    auto get = [&](size_t idx) -> uint64_t {
        return idx < A.d.size() ? A.d[idx] : 0ULL;
    };

    if (z == 0) {
        b_hi = top;
        a_hi = (u128)get(m - 1) | ((u128)get(m) << 64);
    } else {
        b_hi = (top << z) | (B.d[m - 2] >> (64 - z));
        uint64_t w0 = get(m - 2);
        uint64_t w1 = get(m - 1);
        uint64_t w2 = get(m);
        uint64_t lo = (w0 >> (64 - z)) | (w1 << z);
        uint64_t hi = (w1 >> (64 - z)) | (w2 << z);
        a_hi = (u128)lo | ((u128)hi << 64);
    }

    uint64_t q = (uint64_t)(a_hi / ((u128)b_hi + 1));
    if (q > 0) {
        sub_assign(A, mul_u64(B, q));
    }
    while (cmp(A, B) > 0) {
        sub_assign(A, B);
        ++q;
    }
    return q;
}

bool is_ascii_digit(char c) {
    return c >= '0' && c <= '9';
}

}  // namespace

std::string closest_fraction(const std::string& x, long long max_num, long long max_den) {
    if (max_num < 0 || max_den < 1) {
        throw std::invalid_argument("Invalid numerator or denominator bound");
    }

    const size_t n = x.size();
    if (n == 0) {
        throw std::invalid_argument("Empty decimal literal");
    }

    size_t i = 0;
    bool neg = false;
    if (x[i] == '+' || x[i] == '-') {
        neg = (x[i] == '-');
        ++i;
    }
    if (i == n) {
        throw std::invalid_argument("Invalid decimal literal");
    }

    size_t int_start = i;
    while (i < n && is_ascii_digit(x[i])) {
        ++i;
    }
    size_t int_len = i - int_start;

    size_t frac_start = 0;
    size_t frac_len = 0;
    if (i < n && x[i] == '.') {
        ++i;
        frac_start = i;
        while (i < n && is_ascii_digit(x[i])) {
            ++i;
        }
        frac_len = i - frac_start;
    }

    if (int_len + frac_len == 0) {
        throw std::invalid_argument("Invalid mantissa in decimal literal");
    }

    long long exp_val = 0;
    if (i < n && (x[i] == 'e' || x[i] == 'E')) {
        ++i;
        bool exp_neg = false;
        if (i < n && (x[i] == '+' || x[i] == '-')) {
            exp_neg = (x[i] == '-');
            ++i;
        }
        size_t exp_start = i;
        while (i < n && is_ascii_digit(x[i])) {
            if (exp_val < 1000000LL) {
                exp_val = exp_val * 10 + (x[i] - '0');
            }
            ++i;
        }
        if (i == exp_start) {
            throw std::invalid_argument("Invalid exponent in decimal literal");
        }
        if (exp_neg) {
            exp_val = -exp_val;
        }
    }

    if (i != n) {
        throw std::invalid_argument("Trailing characters in decimal literal");
    }

    if (max_num == 0) {
        return "0/1";
    }

    std::string digits;
    digits.reserve(int_len + frac_len);
    digits.append(x, int_start, int_len);
    if (frac_len > 0) {
        digits.append(x, frac_start, frac_len);
    }

    size_t first_nz = digits.find_first_not_of('0');
    if (first_nz == std::string::npos) {
        return "0/1";
    }
    size_t last_nz = digits.find_last_not_of('0');
    size_t tz = digits.size() - 1 - last_nz;
    std::string sig = digits.substr(first_nz, last_nz - first_nz + 1);

    long long E = exp_val - (long long)frac_len + (long long)tz;
    long long L_digits = (long long)sig.size();

    if (L_digits - 1 + E >= 20) {
        return (neg ? "-" : "") + std::to_string(max_num) + "/1";
    }
    if (L_digits + E <= -20) {
        return "0/1";
    }

    BigInt P;
    for (size_t pos = 0; pos < sig.size(); pos += 18) {
        size_t len = std::min<size_t>(18, sig.size() - pos);
        uint64_t chunk = 0;
        for (size_t j = 0; j < len; ++j) {
            chunk = chunk * 10 + (uint64_t)(sig[pos + j] - '0');
        }
        P.mul_add(POW10[len], chunk);
    }

    BigInt Q;
    Q.d.push_back(1ULL);
    if (E > 0) {
        mul_pow10(P, E);
    } else if (E < 0) {
        mul_pow10(Q, -E);
    }

    uint64_t N = (uint64_t)max_num;
    uint64_t D = (uint64_t)max_den;
    uint64_t aL = 0, bL = 1;
    uint64_t aR = 1, bR = 0;

    while (true) {
        int c = cmp(P, Q);
        if (c == 0) {
            u128 aM = (u128)aL + aR;
            u128 bM = (u128)bL + bR;
            if (aM <= N && bM <= D) {
                return (neg ? "-" : "") + std::to_string((uint64_t)aM) + "/" + std::to_string((uint64_t)bM);
            }
            break;
        } else if (c > 0) {
            uint64_t k_a = (N - aL) / aR;
            uint64_t k_lim = (bR == 0) ? k_a : std::min(k_a, (D - bL) / bR);
            bool exceeded = false;
            uint64_t k = div_step(P, Q, k_lim, exceeded);
            aL += k * aR;
            bL += k * bR;
            if (exceeded) {
                break;
            }
        } else {
            uint64_t k_b = (D - bR) / bL;
            uint64_t k_lim = (aL == 0) ? k_b : std::min(k_b, (N - aR) / aL);
            bool exceeded = false;
            uint64_t k = div_step(Q, P, k_lim, exceeded);
            aR += k * aL;
            bR += k * bL;
            if (exceeded) {
                break;
            }
        }
    }

    uint64_t ans_a = aL;
    uint64_t ans_b = bL;
    if (bR != 0) {
        BigInt lhs = mul_u64(P, bR);
        BigInt rhs = mul_u64(Q, bL);
        int dc = cmp(lhs, rhs);
        if (dc > 0 || (dc == 0 && bR < bL)) {
            ans_a = aR;
            ans_b = bR;
        }
    }

    if (ans_a == 0) {
        return "0/1";
    }
    return (neg ? "-" : "") + std::to_string(ans_a) + "/" + std::to_string(ans_b);
}

const LITERAL_RE = /^([+-])?(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?[0-9]+))?$/;

function formatFraction(isNeg: boolean, p: bigint, q: bigint): string {
  if (p === 0n) {
    return "0/1";
  }
  return isNeg ? `-${p}/${q}` : `${p}/${q}`;
}

export function closestFraction(x: string, max_num: number, max_den: number): string {
  if (
    typeof x !== "string" ||
    typeof max_num !== "number" ||
    typeof max_den !== "number" ||
    !Number.isInteger(max_num) ||
    !Number.isInteger(max_den) ||
    max_num < 0 ||
    max_den < 1
  ) {
    throw new Error("Invalid arguments");
  }

  const match = LITERAL_RE.exec(x);
  if (match === null) {
    throw new Error("Invalid decimal literal");
  }

  const isNeg = match[1] === "-";
  const intPart = match[2] ?? "";
  const fracPart = match[3] ?? match[4] ?? "";

  let expVal = 0n;
  if (match[5] !== undefined) {
    const s = match[5];
    if (s[0] === "-") {
      expVal = -BigInt(s.slice(1));
    } else if (s[0] === "+") {
      expVal = BigInt(s.slice(1));
    } else {
      expVal = BigInt(s);
    }
  }

  const rawDigits = intPart + fracPart;
  let start = 0;
  while (start < rawDigits.length && rawDigits.charCodeAt(start) === 48) {
    start++;
  }
  if (start === rawDigits.length) {
    return "0/1";
  }

  const M = BigInt(max_num);
  const N = BigInt(max_den);
  if (M === 0n) {
    return "0/1";
  }

  let end = rawDigits.length;
  while (end > start && rawDigits.charCodeAt(end - 1) === 48) {
    end--;
  }

  const sigDigits = rawDigits.slice(start, end);
  const exp = expVal - BigInt(fracPart.length) + BigInt(rawDigits.length - end);
  const sigLen = BigInt(sigDigits.length);

  // Fast bounds check to avoid constructing huge powers of 10 on extreme exponents
  const mDigits = BigInt(M.toString().length);
  if (sigLen - 1n + exp >= mDigits) {
    return formatFraction(isNeg, M, 1n);
  }
  const twoNDigits = BigInt((2n * N).toString().length);
  if (twoNDigits + sigLen + exp <= 0n) {
    return "0/1";
  }

  const D = BigInt(sigDigits);
  let P: bigint;
  let Q: bigint;
  if (exp >= 0n) {
    P = D * 10n ** exp;
    Q = 1n;
  } else {
    P = D;
    Q = 10n ** -exp;
  }

  // Stern-Brocot search maintaining Farey neighbors p0/q0 <= P/Q <= p1/q1
  // with invariants r0 = P*q0 - Q*p0 and r1 = Q*p1 - P*q1.
  let p0 = 0n;
  let q0 = 1n;
  let r0 = P;

  let p1 = 1n;
  let q1 = 0n;
  let r1 = Q;

  while (p0 + p1 <= M && q0 + q1 <= N) {
    if (r0 >= r1) {
      let k = r0 / r1;
      const km = (M - p0) / p1;
      if (km < k) k = km;
      if (q1 > 0n) {
        const kn = (N - q0) / q1;
        if (kn < k) k = kn;
      }
      p0 += k * p1;
      q0 += k * q1;
      r0 -= k * r1;
      if (r0 === 0n) {
        return formatFraction(isNeg, p0, q0);
      }
    } else {
      let k = r1 / r0;
      if (p0 > 0n) {
        const km = (M - p1) / p0;
        if (km < k) k = km;
      }
      const kn = (N - q1) / q0;
      if (kn < k) k = kn;
      p1 += k * p0;
      q1 += k * q0;
      r1 -= k * r0;
      if (r1 === 0n) {
        return formatFraction(isNeg, p1, q1);
      }
    }
  }

  if (q1 === 0n) {
    return formatFraction(isNeg, p0, q0);
  }

  const lhs = r0 * q1;
  const rhs = r1 * q0;
  if (lhs < rhs) {
    return formatFraction(isNeg, p0, q0);
  }
  if (lhs > rhs) {
    return formatFraction(isNeg, p1, q1);
  }
  if (q0 <= q1) {
    return formatFraction(isNeg, p0, q0);
  }
  return formatFraction(isNeg, p1, q1);
}

package main

import (
	"errors"
	"math/big"
)

func roundDivEven(N, D *big.Int) int {
	quo := new(big.Int)
	rem := new(big.Int)
	quo.QuoRem(N, D, rem)
	q := int(quo.Int64())
	twoRem := new(big.Int).Lsh(rem, 1)
	cmp := twoRem.Cmp(D)
	if cmp > 0 || (cmp == 0 && (q&1) == 1) {
		q++
	}
	return q
}

func DecimalToHalfBits(s string) (int, error) {
	n := len(s)
	if n == 0 {
		return 0, errors.New("empty string")
	}

	i := 0
	neg := false
	if s[i] == '+' || s[i] == '-' {
		neg = s[i] == '-'
		i++
		if i == n {
			return 0, errors.New("missing mantissa")
		}
	}

	const maxSig = 50
	totalDigits := 0
	intDigits := 0
	seenDot := false
	firstNZ := -1
	sig := make([]byte, 0, maxSig+2)
	sticky := false

	for i < n && s[i] != 'e' && s[i] != 'E' {
		c := s[i]
		if c == '.' {
			if seenDot {
				return 0, errors.New("multiple decimal points")
			}
			seenDot = true
			i++
			continue
		}
		if c < '0' || c > '9' {
			return 0, errors.New("invalid character in mantissa")
		}
		if !seenDot {
			intDigits++
		}
		if firstNZ == -1 {
			if c != '0' {
				firstNZ = totalDigits
				sig = append(sig, c)
			}
		} else {
			if len(sig) < maxSig {
				sig = append(sig, c)
			} else if c != '0' {
				sticky = true
			}
		}
		totalDigits++
		i++
	}

	if totalDigits == 0 {
		return 0, errors.New("no digits in mantissa")
	}

	var signedExp int64
	if i < n {
		i++ // skip 'e' or 'E'
		if i == n {
			return 0, errors.New("empty exponent")
		}
		expNeg := false
		if s[i] == '+' || s[i] == '-' {
			expNeg = s[i] == '-'
			i++
			if i == n {
				return 0, errors.New("missing exponent digits")
			}
		}
		expDigits := 0
		var absExp int64
		expCap := int64(n) + 1000
		for i < n {
			c := s[i]
			if c < '0' || c > '9' {
				return 0, errors.New("invalid character in exponent")
			}
			expDigits++
			if absExp < expCap {
				absExp = absExp*10 + int64(c-'0')
			}
			i++
		}
		if expDigits == 0 {
			return 0, errors.New("no digits in exponent")
		}
		if expNeg {
			signedExp = -absExp
		} else {
			signedExp = absExp
		}
	}

	signBit := 0
	if neg {
		signBit = 0x8000
	}

	if firstNZ == -1 {
		return signBit, nil
	}

	sciExp := int64(intDigits-1-firstNZ) + signedExp
	if sciExp >= 5 {
		return signBit | 0x7C00, nil
	}
	if sciExp <= -9 {
		return signBit, nil
	}

	if sticky {
		sig = append(sig, '1')
	}

	decExp := sciExp - int64(len(sig)-1)
	P, ok := new(big.Int).SetString(string(sig), 10)
	if !ok {
		return 0, errors.New("failed to parse significant digits")
	}
	Q := big.NewInt(1)
	ten := big.NewInt(10)
	if decExp > 0 {
		pow10 := new(big.Int).Exp(ten, big.NewInt(decExp), nil)
		P.Mul(P, pow10)
	} else if decExp < 0 {
		Q = new(big.Int).Exp(ten, big.NewInt(-decExp), nil)
	}

	qShift16 := new(big.Int).Lsh(Q, 16)
	if P.Cmp(qShift16) >= 0 {
		return signBit | 0x7C00, nil
	}

	pShift14 := new(big.Int).Lsh(P, 14)
	if pShift14.Cmp(Q) < 0 {
		N := new(big.Int).Lsh(P, 24)
		m := roundDivEven(N, Q)
		return signBit | m, nil
	}

	diff := P.BitLen() - Q.BitLen()
	e := diff
	if diff >= 0 {
		tmp := new(big.Int).Lsh(Q, uint(diff))
		if P.Cmp(tmp) < 0 {
			e = diff - 1
		}
	} else {
		tmp := new(big.Int).Lsh(P, uint(-diff))
		if tmp.Cmp(Q) < 0 {
			e = diff - 1
		}
	}

	E := e + 15
	var N, D *big.Int
	if e >= 10 {
		N = P
		D = new(big.Int).Lsh(Q, uint(e-10))
	} else {
		N = new(big.Int).Lsh(P, uint(10-e))
		D = Q
	}

	m := roundDivEven(N, D)
	bits := (E << 10) + (m - 1024)
	return signBit | bits, nil
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    private Solution() {}

    public static long decimalToHalfBits(String s) {
        if (s == null) {
            throw new IllegalArgumentException("Input must not be null");
        }
        int n = s.length();
        if (n == 0) {
            throw new IllegalArgumentException("Empty literal");
        }

        int i = 0;
        boolean neg = false;
        char c0 = s.charAt(0);
        if (c0 == '+' || c0 == '-') {
            neg = (c0 == '-');
            i++;
            if (i == n) {
                throw new IllegalArgumentException("Missing mantissa");
            }
        }

        final int MAX_SIG = 45;
        char[] sigBuf = new char[MAX_SIG + 1];
        int sigLen = 0;
        boolean sticky = false;
        int firstNonZeroPos = -1;
        int mantissaDigits = 0;
        int intDigits = 0;
        boolean seenDot = false;

        while (i < n) {
            char c = s.charAt(i);
            if (c >= '0' && c <= '9') {
                if (!seenDot) {
                    intDigits++;
                }
                if (firstNonZeroPos < 0) {
                    if (c != '0') {
                        firstNonZeroPos = mantissaDigits;
                        sigBuf[sigLen++] = c;
                    }
                } else if (sigLen < MAX_SIG) {
                    sigBuf[sigLen++] = c;
                } else if (c != '0') {
                    sticky = true;
                }
                mantissaDigits++;
                i++;
            } else if (c == '.' && !seenDot) {
                seenDot = true;
                i++;
            } else {
                break;
            }
        }

        if (mantissaDigits == 0) {
            throw new IllegalArgumentException("Invalid mantissa");
        }

        long expVal = 0;
        if (i < n) {
            char ec = s.charAt(i);
            if (ec != 'e' && ec != 'E') {
                throw new IllegalArgumentException("Unexpected character: " + ec);
            }
            i++;
            if (i == n) {
                throw new IllegalArgumentException("Missing exponent");
            }
            boolean expNeg = false;
            char es = s.charAt(i);
            if (es == '+' || es == '-') {
                expNeg = (es == '-');
                i++;
            }
            int expStart = i;
            long expMag = 0;
            final long EXP_CAP = 1_000_000L;
            while (i < n) {
                char d = s.charAt(i);
                if (d < '0' || d > '9') {
                    throw new IllegalArgumentException("Invalid exponent character: " + d);
                }
                if (expMag < EXP_CAP) {
                    expMag = expMag * 10 + (d - '0');
                }
                i++;
            }
            if (i == expStart) {
                throw new IllegalArgumentException("Missing exponent digits");
            }
            expVal = expNeg ? -expMag : expMag;
        }

        long signBit = neg ? 0x8000L : 0x0000L;
        if (firstNonZeroPos < 0) {
            return signBit;
        }

        long totalSciExp = (long) intDigits - 1L - firstNonZeroPos + expVal;
        if (totalSciExp >= 5) {
            return signBit | 0x7C00L;
        }
        if (totalSciExp <= -9) {
            return signBit;
        }

        if (sticky) {
            sigBuf[sigLen++] = '1';
        }

        BigInteger digitsVal = new BigInteger(new String(sigBuf, 0, sigLen));
        int decExp = (int) totalSciExp - (sigLen - 1);

        BigInteger qBig;
        boolean hasFrac;
        if (decExp >= 0) {
            qBig = digitsVal.multiply(BigInteger.TEN.pow(decExp)).shiftLeft(25);
            hasFrac = false;
        } else {
            BigInteger denom = BigInteger.TEN.pow(-decExp);
            BigInteger[] qr = digitsVal.shiftLeft(25).divideAndRemainder(denom);
            qBig = qr[0];
            hasFrac = qr[1].signum() > 0;
        }

        long infScaled = 65536L << 25;
        if (qBig.compareTo(BigInteger.valueOf(infScaled)) >= 0) {
            return signBit | 0x7C00L;
        }

        long q = qBig.longValueExact();
        int lo = 0;
        int hi = 0x7C00;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            long m = midScaled(mid);
            boolean goRight = (q > m) || (q == m && (hasFrac || (mid & 1) == 1));
            if (goRight) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }

        return signBit | lo;
    }

    private static long valScaled(int p) {
        if (p < 0x0400) {
            return (long) p << 1;
        }
        int e = p >>> 10;
        int f = p & 0x03FF;
        return (1024L + f) << e;
    }

    private static long midScaled(int p) {
        return (valScaled(p) + valScaled(p + 1)) >>> 1;
    }
}

#include <bit>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <string>

long long decimal_to_half_bits(const std::string& s) {
    const std::size_t n = s.size();
    if (n == 0) {
        throw std::invalid_argument("empty decimal literal");
    }

    auto is_ascii_digit = [](char c) -> bool {
        return c >= '0' && c <= '9';
    };

    std::size_t i = 0;
    bool neg = false;
    if (s[i] == '+' || s[i] == '-') {
        neg = (s[i] == '-');
        ++i;
        if (i == n) {
            throw std::invalid_argument("sign with no mantissa");
        }
    }

    const std::size_t int_start = i;
    while (i < n && is_ascii_digit(s[i])) {
        ++i;
    }
    const std::size_t int_len = i - int_start;

    std::size_t frac_start = i;
    std::size_t frac_len = 0;
    if (i < n && s[i] == '.') {
        ++i;
        frac_start = i;
        while (i < n && is_ascii_digit(s[i])) {
            ++i;
        }
        frac_len = i - frac_start;
    }

    const std::size_t total_digits = int_len + frac_len;
    if (total_digits == 0) {
        throw std::invalid_argument("invalid mantissa");
    }

    long long exp_val = 0;
    if (i < n && (s[i] == 'e' || s[i] == 'E')) {
        ++i;
        bool exp_neg = false;
        if (i < n && (s[i] == '+' || s[i] == '-')) {
            exp_neg = (s[i] == '-');
            ++i;
        }
        const std::size_t exp_start = i;
        const long long clamp = static_cast<long long>(n) + 100LL;
        long long exp_mag = 0;
        while (i < n && is_ascii_digit(s[i])) {
            if (exp_mag < clamp) {
                exp_mag = exp_mag * 10LL + static_cast<long long>(s[i] - '0');
            }
            ++i;
        }
        if (i == exp_start) {
            throw std::invalid_argument("empty exponent");
        }
        exp_val = exp_neg ? -exp_mag : exp_mag;
    }

    if (i != n) {
        throw std::invalid_argument("trailing characters in literal");
    }

    const std::uint64_t sign_bit = neg ? 0x8000ULL : 0x0000ULL;

    auto get_digit = [&](std::size_t idx) -> char {
        if (idx < int_len) {
            return s[int_start + idx];
        }
        return s[frac_start + (idx - int_len)];
    };

    std::size_t first_nz = 0;
    while (first_nz < total_digits && get_digit(first_nz) == '0') {
        ++first_nz;
    }
    if (first_nz == total_digits) {
        return static_cast<long long>(sign_bit);
    }

    // Exact value is v = 0.d_0 d_1 ... * 10^p with d_0 in 1..9.
    const long long p = static_cast<long long>(int_len) - static_cast<long long>(first_nz) + exp_val;
    if (p > 5) {
        return static_cast<long long>(sign_bit | 0x7C00ULL);
    }
    if (p < -7) {
        return static_cast<long long>(sign_bit);
    }

    // For -7 <= p <= 5, k = p + 25 is in 18..30.
    // v * 2^25 = (v * 10^25) / 5^25 = (Q + r) / 5^25, where Q = floor(v * 10^25)
    // consists of the first k significant digits (zero-padded) and 0 <= r < 1.
    constexpr std::uint64_t P = 298023223876953125ULL; // 5^25
    const int k = static_cast<int>(p) + 25;
    std::uint64_t K = 0;
    std::uint64_t R = 0;
    for (int step = 0; step < k; ++step) {
        const std::size_t idx = first_nz + static_cast<std::size_t>(step);
        const std::uint64_t digit =
            (idx < total_digits) ? static_cast<std::uint64_t>(get_digit(idx) - '0') : 0ULL;
        const std::uint64_t cur = R * 10ULL + digit;
        K = K * 10ULL + (cur / P);
        R = cur % P;
    }

    bool has_rem = false;
    for (std::size_t idx = first_nz + static_cast<std::size_t>(k); idx < total_digits; ++idx) {
        if (get_digit(idx) != '0') {
            has_rem = true;
            break;
        }
    }
    const bool has_frac = (R != 0) || has_rem;

    if (K >= (1ULL << 41)) {
        return static_cast<long long>(sign_bit | 0x7C00ULL);
    }

    if (K < 2048ULL) {
        std::uint64_t m = K >> 1;
        if ((K & 1ULL) && (has_frac || (m & 1ULL))) {
            ++m;
        }
        return static_cast<long long>(sign_bit | m);
    }

    const int b = std::bit_width(K) - 1; // 11..40
    const int E = b - 10;                // 1..30
    std::uint64_t M = K >> E;            // 1024..2047
    const std::uint64_t rem_bits = K & ((1ULL << E) - 1ULL);
    const std::uint64_t half = 1ULL << (E - 1);
    if (rem_bits > half || (rem_bits == half && (has_frac || (M & 1ULL)))) {
        ++M;
    }

    const std::uint64_t mag_bits = static_cast<std::uint64_t>(E - 1) * 1024ULL + M;
    return static_cast<long long>(sign_bit | mag_bits);
}

function isAsciiDigit(code: number): boolean {
  return code >= 48 && code <= 57;
}

export function decimalToHalfBits(s: string): number {
  if (typeof s !== "string") {
    throw new Error("Input must be a string");
  }

  const n = s.length;
  if (n === 0) {
    throw new Error("Empty string is not a valid decimal literal");
  }

  let i = 0;
  let signBit = 0;
  const firstChar = s.charCodeAt(0);
  if (firstChar === 45) {
    signBit = 0x8000;
    i = 1;
  } else if (firstChar === 43) {
    i = 1;
  }

  const intStart = i;
  while (i < n && isAsciiDigit(s.charCodeAt(i))) {
    i++;
  }
  const intEnd = i;

  let fracStart = i;
  let fracEnd = i;
  if (i < n && s.charCodeAt(i) === 46) {
    i++;
    fracStart = i;
    while (i < n && isAsciiDigit(s.charCodeAt(i))) {
      i++;
    }
    fracEnd = i;
  }

  if ((intEnd - intStart) + (fracEnd - fracStart) === 0) {
    throw new Error("Invalid mantissa in decimal literal");
  }

  let expSign = 1;
  let expStart = -1;
  let expEnd = -1;
  if (i < n) {
    const c = s.charCodeAt(i);
    if (c === 101 || c === 69) {
      i++;
      if (i < n) {
        const sc = s.charCodeAt(i);
        if (sc === 45) {
          expSign = -1;
          i++;
        } else if (sc === 43) {
          i++;
        }
      }
      expStart = i;
      while (i < n && isAsciiDigit(s.charCodeAt(i))) {
        i++;
      }
      expEnd = i;
      if (expEnd === expStart) {
        throw new Error("Invalid exponent in decimal literal");
      }
    }
  }

  if (i !== n) {
    throw new Error("Unexpected characters in decimal literal");
  }

  let firstPos = -1;
  let inInt = false;
  let mantExp = 0;

  for (let k = intStart; k < intEnd; k++) {
    if (s.charCodeAt(k) !== 48) {
      firstPos = k;
      inInt = true;
      mantExp = intEnd - 1 - k;
      break;
    }
  }

  if (firstPos === -1) {
    for (let k = fracStart; k < fracEnd; k++) {
      if (s.charCodeAt(k) !== 48) {
        firstPos = k;
        inInt = false;
        mantExp = -(k - fracStart + 1);
        break;
      }
    }
  }

  if (firstPos === -1) {
    return signBit;
  }

  let expVal = 0;
  if (expStart !== -1) {
    let es = expStart;
    while (es < expEnd && s.charCodeAt(es) === 48) {
      es++;
    }
    const expDigits = expEnd - es;
    if (expDigits > 7) {
      return expSign > 0 ? (signBit | 0x7c00) : signBit;
    }
    for (let k = es; k < expEnd; k++) {
      expVal = expVal * 10 + (s.charCodeAt(k) - 48);
    }
  }

  const p = mantExp + expSign * expVal;
  if (p >= 5) {
    return signBit | 0x7c00;
  }
  if (p <= -9) {
    return signBit;
  }

  // Every binary16 candidate and midpoint is an integer multiple of 2^-25 = 5^25 * 10^-25.
  // Since p <= 4, 40 significant digits reach <= 10^-35, well past 10^-25; collapsing any
  // remaining non-zero tail into a single sticky digit preserves exact comparisons.
  const MAX_SIG = 40;
  let sigVal = 0n;
  let sigLen = 0;
  let stickyTail = false;

  if (inInt) {
    for (let k = firstPos; k < intEnd; k++) {
      const d = s.charCodeAt(k) - 48;
      if (sigLen < MAX_SIG) {
        sigVal = sigVal * 10n + BigInt(d);
        sigLen++;
      } else if (d !== 0) {
        stickyTail = true;
        break;
      }
    }
  }

  if (!stickyTail) {
    const startK = inInt ? fracStart : firstPos;
    for (let k = startK; k < fracEnd; k++) {
      const d = s.charCodeAt(k) - 48;
      if (sigLen < MAX_SIG) {
        sigVal = sigVal * 10n + BigInt(d);
        sigLen++;
      } else if (d !== 0) {
        stickyTail = true;
        break;
      }
    }
  }

  let decExp = p - sigLen + 1;
  if (stickyTail) {
    sigVal = sigVal * 10n + 1n;
    decExp -= 1;
  }

  let q: bigint;
  let hasRem: boolean;
  if (decExp >= 0) {
    q = (sigVal * (10n ** BigInt(decExp))) << 25n;
    hasRem = false;
  } else {
    const num = sigVal << 25n;
    const den = 10n ** BigInt(-decExp);
    q = num / den;
    hasRem = (num % den) !== 0n;
  }

  if (q >= (65520n << 25n)) {
    return signBit | 0x7c00;
  }

  if (q < 4096n) {
    let pattern = Number(q >> 1n);
    if ((q & 1n) === 1n) {
      if (hasRem || (pattern & 1) === 1) {
        pattern += 1;
      }
    }
    return signBit | pattern;
  }

  const bitLen = q.toString(2).length - 1;
  const E = bitLen - 10;
  const eBig = BigInt(E);
  const k = Number(q >> eBig);
  let pattern = (E << 10) | (k - 1024);

  const r = q & ((1n << eBig) - 1n);
  const half = 1n << BigInt(E - 1);
  if (r > half || (r === half && (hasRem || (pattern & 1) === 1))) {
    pattern += 1;
  }

  return signBit | pattern;
}

package main

import (
	"container/heap"
	"fmt"
	"sort"
)

type Tuple1 struct {
	F0 string
	F1 int
	F2 int
	F3 int
	F4 *int
}

type Tuple2 struct {
	F0 string
	F1 int
	F2 int
}

type Tuple3 struct {
	F0 []Tuple2
	F1 []string
}

type jobHeap []Tuple1

func (h jobHeap) Len() int { return len(h) }

func (h jobHeap) Less(i, j int) bool {
	if h[i].F3 != h[j].F3 {
		return h[i].F3 > h[j].F3 // higher priority first
	}
	if h[i].F1 != h[j].F1 {
		return h[i].F1 < h[j].F1 // smaller release time first
	}
	return h[i].F0 < h[j].F0 // smaller job_id first
}

func (h jobHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

func (h *jobHeap) Push(x any) {
	*h = append(*h, x.(Tuple1))
}

func (h *jobHeap) Pop() any {
	old := *h
	n := len(old)
	item := old[n-1]
	*h = old[:n-1]
	return item
}

func Schedule(jobs []Tuple1) (Tuple3, error) {
	seen := make(map[string]struct{}, len(jobs))
	for _, job := range jobs {
		if _, exists := seen[job.F0]; exists {
			return Tuple3{}, fmt.Errorf("duplicate job id %q", job.F0)
		}
		seen[job.F0] = struct{}{}
		if job.F1 < 0 {
			return Tuple3{}, fmt.Errorf("job %q has a negative release time", job.F0)
		}
		if job.F2 < 1 {
			return Tuple3{}, fmt.Errorf("job %q has a non-positive duration", job.F0)
		}
	}

	sortedJobs := make([]Tuple1, len(jobs))
	copy(sortedJobs, jobs)
	sort.Slice(sortedJobs, func(i, j int) bool {
		return sortedJobs[i].F1 < sortedJobs[j].F1
	})

	runs := make([]Tuple2, 0)
	dropped := make([]string, 0)
	ready := make(jobHeap, 0)

	clock := 0
	nxt := 0
	for nxt < len(sortedJobs) || ready.Len() > 0 {
		if ready.Len() == 0 && clock < sortedJobs[nxt].F1 {
			clock = sortedJobs[nxt].F1
		}
		for nxt < len(sortedJobs) && sortedJobs[nxt].F1 <= clock {
			heap.Push(&ready, sortedJobs[nxt])
			nxt++
		}

		best := heap.Pop(&ready).(Tuple1)
		if best.F4 != nil && clock+best.F2 > *best.F4 {
			dropped = append(dropped, best.F0)
			continue
		}
		runs = append(runs, Tuple2{
			F0: best.F0,
			F1: clock,
			F2: clock + best.F2,
		})
		clock += best.F2
	}

	return Tuple3{
		F0: runs,
		F1: dropped,
	}, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, long f1, long f2, long f3, Long f4) {}

    public record Tuple2(String f0, long f1, long f2) {}

    public record Tuple3(List<Tuple2> f0, List<String> f1) {}

    public static Tuple3 schedule(List<Tuple1> jobs) {
        if (jobs == null) {
            throw new IllegalArgumentException("jobs must not be null");
        }

        int n = jobs.size();
        Set<String> seen = HashSet.newHashSet(n);
        Tuple1[] sorted = new Tuple1[n];

        int idx = 0;
        for (Tuple1 job : jobs) {
            if (job == null || job.f0() == null) {
                throw new IllegalArgumentException("each job must be a valid 5-tuple");
            }
            String jobId = job.f0();
            long release = job.f1();
            long duration = job.f2();

            if (!seen.add(jobId)) {
                throw new IllegalArgumentException("duplicate job id " + jobId);
            }
            if (release < 0) {
                throw new IllegalArgumentException("job " + jobId + " has a negative release time");
            }
            if (duration < 1) {
                throw new IllegalArgumentException("job " + jobId + " has a non-positive duration");
            }
            sorted[idx++] = job;
        }

        if (n == 0) {
            return new Tuple3(new ArrayList<>(), new ArrayList<>());
        }

        Arrays.sort(sorted, Comparator.comparingLong(Tuple1::f1));

        PriorityQueue<Tuple1> ready = new PriorityQueue<>((a, b) -> {
            int cmp = Long.compare(b.f3(), a.f3());
            if (cmp != 0) {
                return cmp;
            }
            cmp = Long.compare(a.f1(), b.f1());
            if (cmp != 0) {
                return cmp;
            }
            return compareCodePoints(a.f0(), b.f0());
        });

        List<Tuple2> runs = new ArrayList<>();
        List<String> dropped = new ArrayList<>();
        long clock = 0;
        int nxt = 0;

        while (nxt < n || !ready.isEmpty()) {
            if (ready.isEmpty() && clock < sorted[nxt].f1()) {
                clock = sorted[nxt].f1();
            }
            while (nxt < n && sorted[nxt].f1() <= clock) {
                ready.add(sorted[nxt]);
                nxt++;
            }

            Tuple1 best = ready.poll();
            String jobId = best.f0();
            long duration = best.f2();
            Long deadline = best.f4();

            if (deadline != null && (deadline <= 0 || clock > deadline - duration)) {
                dropped.add(jobId);
                continue;
            }

            long end = clock + duration;
            runs.add(new Tuple2(jobId, clock, end));
            clock = end;
        }

        return new Tuple3(runs, dropped);
    }

    private static int compareCodePoints(String a, String b) {
        int lenA = a.length();
        int lenB = b.length();
        int minLen = Math.min(lenA, lenB);
        for (int i = 0; i < minLen; i++) {
            char ca = a.charAt(i);
            char cb = b.charAt(i);
            if (ca != cb) {
                if (!Character.isSurrogate(ca) && !Character.isSurrogate(cb)) {
                    return Character.compare(ca, cb);
                }
                if (i > 0 && Character.isHighSurrogate(a.charAt(i - 1))) {
                    i--;
                }
                return Integer.compare(a.codePointAt(i), b.codePointAt(i));
            }
        }
        return Integer.compare(lenA, lenB);
    }
}

#include <algorithm>
#include <cstddef>
#include <numeric>
#include <optional>
#include <queue>
#include <stdexcept>
#include <string>
#include <string_view>
#include <tuple>
#include <unordered_set>
#include <vector>

std::tuple<std::vector<std::tuple<std::string, long long, long long>>, std::vector<std::string>>
schedule(const std::vector<std::tuple<std::string, long long, long long, long long, std::optional<long long>>>& jobs) {
    std::unordered_set<std::string_view> seen;
    seen.reserve(jobs.size());

    for (const auto& job : jobs) {
        const auto& [job_id, release, duration, priority, deadline] = job;
        if (!seen.insert(job_id).second) {
            throw std::invalid_argument("duplicate job id: " + job_id);
        }
        if (release < 0) {
            throw std::invalid_argument("job has a negative release time: " + job_id);
        }
        if (duration < 1) {
            throw std::invalid_argument("job has a non-positive duration: " + job_id);
        }
    }

    std::vector<std::tuple<std::string, long long, long long>> runs;
    std::vector<std::string> dropped;
    if (jobs.empty()) {
        return {runs, dropped};
    }

    const std::size_t n = jobs.size();
    std::vector<std::size_t> order(n);
    std::iota(order.begin(), order.end(), std::size_t{0});
    std::sort(order.begin(), order.end(), [&jobs](std::size_t a, std::size_t b) {
        return std::get<1>(jobs[a]) < std::get<1>(jobs[b]);
    });

    auto cmp = [&jobs](std::size_t a, std::size_t b) {
        const auto& [id_a, rel_a, dur_a, prio_a, dl_a] = jobs[a];
        const auto& [id_b, rel_b, dur_b, prio_b, dl_b] = jobs[b];
        if (prio_a != prio_b) {
            return prio_a < prio_b;
        }
        if (rel_a != rel_b) {
            return rel_a > rel_b;
        }
        return id_a > id_b;
    };

    std::priority_queue<std::size_t, std::vector<std::size_t>, decltype(cmp)> ready(cmp);

    long long clock = 0;
    std::size_t nxt = 0;

    while (nxt < n || !ready.empty()) {
        if (ready.empty() && std::get<1>(jobs[order[nxt]]) > clock) {
            clock = std::get<1>(jobs[order[nxt]]);
        }
        while (nxt < n && std::get<1>(jobs[order[nxt]]) <= clock) {
            ready.push(order[nxt]);
            ++nxt;
        }

        const std::size_t best_idx = ready.top();
        ready.pop();

        const auto& [job_id, release, duration, priority, deadline] = jobs[best_idx];
        if (deadline.has_value() && (*deadline < clock || duration > *deadline - clock)) {
            dropped.push_back(job_id);
            continue;
        }

        runs.emplace_back(job_id, clock, clock + duration);
        clock += duration;
    }

    return {runs, dropped};
}

type Job = [string, number, number, number, number | null];
type Run = [string, number, number];

function compareJobIds(a: string, b: string): number {
  const len = a.length < b.length ? a.length : b.length;
  for (let i = 0; i < len; i++) {
    const ca = a.charCodeAt(i);
    const cb = b.charCodeAt(i);
    if (ca !== cb) {
      if (ca >= 0xd800 && cb >= 0xd800) {
        return a.codePointAt(i)! - b.codePointAt(i)!;
      }
      return ca - cb;
    }
  }
  return a.length - b.length;
}

function isBetter(a: Job, b: Job): boolean {
  if (a[3] !== b[3]) {
    return a[3] > b[3];
  }
  if (a[1] !== b[1]) {
    return a[1] < b[1];
  }
  return compareJobIds(a[0], b[0]) < 0;
}

function heapPush(heap: Job[], item: Job): void {
  let idx = heap.length;
  heap.push(item);
  while (idx > 0) {
    const parent = (idx - 1) >>> 1;
    if (isBetter(item, heap[parent])) {
      heap[idx] = heap[parent];
      idx = parent;
    } else {
      break;
    }
  }
  heap[idx] = item;
}

function heapPop(heap: Job[]): Job {
  const top = heap[0];
  const last = heap.pop()!;
  const n = heap.length;
  if (n > 0) {
    let idx = 0;
    while (true) {
      const left = idx * 2 + 1;
      if (left >= n) {
        break;
      }
      let bestChild = left;
      const right = left + 1;
      if (right < n && isBetter(heap[right], heap[left])) {
        bestChild = right;
      }
      if (isBetter(heap[bestChild], last)) {
        heap[idx] = heap[bestChild];
        idx = bestChild;
      } else {
        break;
      }
    }
    heap[idx] = last;
  }
  return top;
}

export function schedule(jobs: ([string, number, number, number, number | null])[]): [[string, number, number][], string[]] {
  const seen = new Set<string>();
  for (let i = 0; i < jobs.length; i++) {
    const job = jobs[i];
    if (!Array.isArray(job) || job.length !== 5) {
      throw new Error("each job must be a 5-tuple");
    }
    const [jobId, release, duration] = job;
    if (seen.has(jobId)) {
      throw new Error(`duplicate job id ${JSON.stringify(jobId)}`);
    }
    seen.add(jobId);
    if (release < 0) {
      throw new Error(`job ${JSON.stringify(jobId)} has a negative release time`);
    }
    if (duration < 1) {
      throw new Error(`job ${JSON.stringify(jobId)} has a non-positive duration`);
    }
  }

  const sorted = jobs.slice();
  sorted.sort((a, b) => (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));

  const runs: Run[] = [];
  const dropped: string[] = [];
  const ready: Job[] = [];
  let clock = 0;
  let nxt = 0;
  const n = sorted.length;

  while (nxt < n || ready.length > 0) {
    if (ready.length === 0 && sorted[nxt][1] > clock) {
      clock = sorted[nxt][1];
    }
    while (nxt < n && sorted[nxt][1] <= clock) {
      heapPush(ready, sorted[nxt]);
      nxt++;
    }

    const best = heapPop(ready);
    const [jobId, , duration, , deadline] = best;
    if (deadline !== null && clock + duration > deadline) {
      dropped.push(jobId);
      continue;
    }
    runs.push([jobId, clock, clock + duration]);
    clock += duration;
  }

  return [runs, dropped];
}

package main

import "errors"

type entry struct {
	val int
	idx int
}

func lessEntry(a, b entry) bool {
	if a.val != b.val {
		return a.val < b.val
	}
	return a.idx < b.idx
}

func pushLow(h *[]entry, e entry) {
	*h = append(*h, e)
	s := *h
	i := len(s) - 1
	for i > 0 {
		p := (i - 1) / 2
		if !lessEntry(s[p], s[i]) {
			break
		}
		s[p], s[i] = s[i], s[p]
		i = p
	}
}

func popLow(h *[]entry) entry {
	s := *h
	top := s[0]
	last := len(s) - 1
	s[0] = s[last]
	*h = s[:last]
	s = *h
	n := len(s)
	i := 0
	for {
		l := 2*i + 1
		if l >= n {
			break
		}
		best := l
		if r := l + 1; r < n && lessEntry(s[l], s[r]) {
			best = r
		}
		if !lessEntry(s[i], s[best]) {
			break
		}
		s[i], s[best] = s[best], s[i]
		i = best
	}
	return top
}

func pushHigh(h *[]entry, e entry) {
	*h = append(*h, e)
	s := *h
	i := len(s) - 1
	for i > 0 {
		p := (i - 1) / 2
		if !lessEntry(s[i], s[p]) {
			break
		}
		s[p], s[i] = s[i], s[p]
		i = p
	}
}

func popHigh(h *[]entry) entry {
	s := *h
	top := s[0]
	last := len(s) - 1
	s[0] = s[last]
	*h = s[:last]
	s = *h
	n := len(s)
	i := 0
	for {
		l := 2*i + 1
		if l >= n {
			break
		}
		best := l
		if r := l + 1; r < n && lessEntry(s[r], s[l]) {
			best = r
		}
		if !lessEntry(s[best], s[i]) {
			break
		}
		s[i], s[best] = s[best], s[i]
		i = best
	}
	return top
}

func WindowMedians(readings []*int, k int) ([]*int, error) {
	if k < 1 {
		return nil, errors.New("k must be a positive int")
	}

	n := len(readings)
	out := make([]*int, n)
	if n == 0 {
		return out, nil
	}

	vals := make([]int, n)
	deleted := make([]bool, n)
	var low, high []entry
	lowSize, highSize := 0, 0

	pruneLow := func() {
		for len(low) > 0 && deleted[low[0].idx] {
			popLow(&low)
		}
	}

	pruneHigh := func() {
		for len(high) > 0 && deleted[high[0].idx] {
			popHigh(&high)
		}
	}

	rebalance := func() {
		if lowSize > highSize+1 {
			pushHigh(&high, popLow(&low))
			lowSize--
			highSize++
			pruneLow()
		} else if lowSize < highSize {
			pushLow(&low, popHigh(&high))
			highSize--
			lowSize++
			pruneHigh()
		}
	}

	add := func(e entry) {
		if lowSize == 0 || !lessEntry(low[0], e) {
			pushLow(&low, e)
			lowSize++
		} else {
			pushHigh(&high, e)
			highSize++
		}
		rebalance()
	}

	remove := func(e entry) {
		deleted[e.idx] = true
		if !lessEntry(low[0], e) {
			lowSize--
			if e.idx == low[0].idx {
				pruneLow()
			}
		} else {
			highSize--
			if e.idx == high[0].idx {
				pruneHigh()
			}
		}
		rebalance()
	}

	for i, r := range readings {
		if i >= k && readings[i-k] != nil {
			remove(entry{val: *readings[i-k], idx: i - k})
		}
		if r != nil {
			add(entry{val: *r, idx: i})
		}
		if lowSize > 0 {
			vals[i] = low[0].val
			out[i] = &vals[i]
		}
	}

	return out, nil
}

import java.util.*;

public final class Solution {
    private record Entry(long value, int index) implements Comparable<Entry> {
        @Override
        public int compareTo(Entry other) {
            int cmp = Long.compare(this.value, other.value);
            return cmp != 0 ? cmp : Integer.compare(this.index, other.index);
        }
    }

    public static List<Long> windowMedians(List<Long> readings, long k) {
        if (k < 1 || readings == null) {
            throw new IllegalArgumentException("k must be a positive integer and readings must not be null");
        }

        int n = readings.size();
        List<Long> out = new ArrayList<>(n);
        if (n == 0) {
            return out;
        }

        TreeSet<Entry> low = new TreeSet<>();
        TreeSet<Entry> high = new TreeSet<>();
        Entry[] window = k < n ? new Entry[(int) k] : null;
        int slot = 0;
        int index = 0;

        for (Long x : readings) {
            if (window != null && index >= k) {
                Entry expired = window[slot];
                if (expired != null) {
                    if (!low.remove(expired)) {
                        high.remove(expired);
                    }
                    window[slot] = null;
                    rebalance(low, high);
                }
            }

            if (x != null) {
                Entry current = new Entry(x, index);
                if (low.isEmpty() || current.compareTo(low.last()) <= 0) {
                    low.add(current);
                } else {
                    high.add(current);
                }
                if (window != null) {
                    window[slot] = current;
                }
                rebalance(low, high);
            }

            out.add(low.isEmpty() ? null : low.last().value());

            if (window != null && ++slot == window.length) {
                slot = 0;
            }
            index++;
        }

        return out;
    }

    private static void rebalance(TreeSet<Entry> low, TreeSet<Entry> high) {
        while (low.size() > high.size() + 1) {
            high.add(low.pollLast());
        }
        while (low.size() < high.size()) {
            low.add(high.pollFirst());
        }
    }
}

#include <cstddef>
#include <iterator>
#include <optional>
#include <set>
#include <stdexcept>
#include <utility>
#include <vector>

std::vector<std::optional<long long>> window_medians(
    const std::vector<std::optional<long long>>& readings,
    long long k) {
    if (k < 1) {
        throw std::invalid_argument("k must be a positive integer");
    }

    std::multiset<long long> low;   // smaller half; max element is the lower median
    std::multiset<long long> high;  // larger half

    auto rebalance = [&]() {
        while (low.size() > high.size() + 1) {
            auto node = low.extract(std::prev(low.end()));
            high.insert(std::move(node));
        }
        while (low.size() < high.size()) {
            auto node = high.extract(high.begin());
            low.insert(std::move(node));
        }
    };

    auto add = [&](long long x) {
        if (low.empty() || x <= *low.rbegin()) {
            low.insert(x);
        } else {
            high.insert(x);
        }
        rebalance();
    };

    auto remove = [&](long long x) {
        if (!low.empty() && x <= *low.rbegin()) {
            low.erase(low.find(x));
        } else {
            high.erase(high.find(x));
        }
        rebalance();
    };

    std::vector<std::optional<long long>> out;
    out.reserve(readings.size());

    const bool can_expire = static_cast<unsigned long long>(k) <= readings.size();
    const std::size_t window_size = can_expire ? static_cast<std::size_t>(k) : 0;

    for (std::size_t i = 0; i < readings.size(); ++i) {
        if (can_expire && i >= window_size && readings[i - window_size].has_value()) {
            remove(*readings[i - window_size]);
        }
        if (readings[i].has_value()) {
            add(*readings[i]);
        }
        if (low.empty()) {
            out.emplace_back(std::nullopt);
        } else {
            out.emplace_back(*low.rbegin());
        }
    }

    return out;
}

export function windowMedians(readings: (number | null)[], k: number): (number | null)[] {
  if (typeof k !== "number" || !Number.isInteger(k) || k < 1) {
    throw new Error("k must be a positive integer");
  }

  const n = readings.length;
  if (n === 0) {
    return [];
  }

  const cap = k < n ? k : n;
  const vals = new Float64Array(cap);
  const which = new Int8Array(cap); // 0 = inactive, 1 = in low (max-heap), 2 = in high (min-heap)
  const pos = new Int32Array(cap);
  const low = new Int32Array(cap);
  const high = new Int32Array(cap);
  let lowSize = 0;
  let highSize = 0;

  function lowUp(idx: number): void {
    const id = low[idx];
    const v = vals[id];
    while (idx > 0) {
      const p = (idx - 1) >> 1;
      const pId = low[p];
      if (vals[pId] >= v) break;
      low[idx] = pId;
      pos[pId] = idx;
      idx = p;
    }
    low[idx] = id;
    pos[id] = idx;
  }

  function lowDown(idx: number): void {
    const id = low[idx];
    const v = vals[id];
    const half = lowSize >> 1;
    while (idx < half) {
      let c = (idx << 1) + 1;
      let cId = low[c];
      let cVal = vals[cId];
      const r = c + 1;
      if (r < lowSize) {
        const rId = low[r];
        const rVal = vals[rId];
        if (rVal > cVal) {
          c = r;
          cId = rId;
          cVal = rVal;
        }
      }
      if (v >= cVal) break;
      low[idx] = cId;
      pos[cId] = idx;
      idx = c;
    }
    low[idx] = id;
    pos[id] = idx;
  }

  function lowPush(id: number): void {
    which[id] = 1;
    const idx = lowSize++;
    low[idx] = id;
    pos[id] = idx;
    lowUp(idx);
  }

  function lowRemoveAt(idx: number): number {
    const removedId = low[idx];
    which[removedId] = 0;
    lowSize--;
    if (idx < lowSize) {
      const lastId = low[lowSize];
      low[idx] = lastId;
      pos[lastId] = idx;
      lowUp(idx);
      lowDown(pos[lastId]);
    }
    return removedId;
  }

  function highUp(idx: number): void {
    const id = high[idx];
    const v = vals[id];
    while (idx > 0) {
      const p = (idx - 1) >> 1;
      const pId = high[p];
      if (vals[pId] <= v) break;
      high[idx] = pId;
      pos[pId] = idx;
      idx = p;
    }
    high[idx] = id;
    pos[id] = idx;
  }

  function highDown(idx: number): void {
    const id = high[idx];
    const v = vals[id];
    const half = highSize >> 1;
    while (idx < half) {
      let c = (idx << 1) + 1;
      let cId = high[c];
      let cVal = vals[cId];
      const r = c + 1;
      if (r < highSize) {
        const rId = high[r];
        const rVal = vals[rId];
        if (rVal < cVal) {
          c = r;
          cId = rId;
          cVal = rVal;
        }
      }
      if (v <= cVal) break;
      high[idx] = cId;
      pos[cId] = idx;
      idx = c;
    }
    high[idx] = id;
    pos[id] = idx;
  }

  function highPush(id: number): void {
    which[id] = 2;
    const idx = highSize++;
    high[idx] = id;
    pos[id] = idx;
    highUp(idx);
  }

  function highRemoveAt(idx: number): number {
    const removedId = high[idx];
    which[removedId] = 0;
    highSize--;
    if (idx < highSize) {
      const lastId = high[highSize];
      high[idx] = lastId;
      pos[lastId] = idx;
      highUp(idx);
      highDown(pos[lastId]);
    }
    return removedId;
  }

  function rebalance(): void {
    if (lowSize > highSize + 1) {
      highPush(lowRemoveAt(0));
    } else if (lowSize < highSize) {
      lowPush(highRemoveAt(0));
    }
  }

  const out: (number | null)[] = new Array(n);
  let slot = 0;

  for (let i = 0; i < n; i++) {
    const w = which[slot];
    if (w !== 0) {
      if (w === 1) {
        lowRemoveAt(pos[slot]);
      } else {
        highRemoveAt(pos[slot]);
      }
      rebalance();
    }

    const x = readings[i];
    if (x !== null) {
      vals[slot] = x;
      if (lowSize === 0 || x <= vals[low[0]]) {
        lowPush(slot);
      } else {
        highPush(slot);
      }
      rebalance();
    }

    if (lowSize > 0) {
      const m = vals[low[0]];
      out[i] = m === 0 ? 0 : m;
    } else {
      out[i] = null;
    }

    slot++;
    if (slot === cap) {
      slot = 0;
    }
  }

  return out;
}

from heapq import heappop, heappush


def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)

    C = capacity + 1

    # Group roads by (u, v) and prune useless self-loops and dominated parallel roads.
    by_pair = {}
    for u, v, minutes, energy in roads:
        if u == v and energy >= 0:
            continue
        pair = (u, v)
        lst = by_pair.get(pair)
        if lst is None:
            by_pair[pair] = [(minutes, energy)]
        else:
            lst.append((minutes, energy))

    adj = [[] for _ in range(n)]
    for (u, v), lst in by_pair.items():
        v_base = v * C
        u_adj = adj[u]
        if len(lst) > 1:
            lst.sort()
            min_e = capacity + 1
            for minutes, energy in lst:
                if energy < min_e:
                    min_e = energy
                    u_adj.append((v_base, minutes, energy))
        else:
            minutes, energy = lst[0]
            u_adj.append((v_base, minutes, energy))

    INF = 1 << 62
    best = [INF] * (n * C)
    start_state = s * C + capacity
    best[start_state] = 0
    heap = [(0, start_state)]

    station_bases = [u * C for u in set(stations)]

    best_min = INF
    best_swaps = -1

    # Process swap counts layer by layer (0 .. max_swaps).
    # Reaching the exact same (junction, charge) in a later layer is only useful
    # if it strictly improves the minimum arrival time seen in earlier layers.
    for swaps in range(max_swaps + 1):
        while heap:
            d, state = heappop(heap)
            if d > best[state]:
                continue
            if d >= best_min:
                heap.clear()
                break
            u, c = divmod(state, C)
            if u == t:
                best_min = d
                best_swaps = swaps
                heap.clear()
                break
            for v_base, minutes, energy in adj[u]:
                if c >= energy:
                    nc = c - energy
                    if nc > capacity:
                        nc = capacity
                    nstate = v_base + nc
                    nd = d + minutes
                    if nd < best_min and nd < best[nstate]:
                        best[nstate] = nd
                        heappush(heap, (nd, nstate))

        if swaps == max_swaps or not station_bases:
            break

        for u_base in station_bases:
            m = min(best[u_base : u_base + C])
            if m < INF:
                nd = m + swap_time
                full_state = u_base + capacity
                if nd < best_min and nd < best[full_state]:
                    best[full_state] = nd
                    heappush(heap, (nd, full_state))

        if not heap:
            break

    if best_min == INF:
        return None
    return (best_min, best_swaps)

def best_context(messages, budget, max_gap, bonus):
    """Return the maximum context score within budget and max_gap constraints, or None."""
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")

    n = len(messages)
    if n == 0:
        return 0

    # Strictly smaller than any achievable score so max comparisons always prefer valid states.
    neg_inf = -(sum(abs(v) for _, v, _ in messages) + n * abs(bonus) + 1)

    # dp[i][b] = max score on messages[0..i] with message i kept and total length <= b.
    # dp_minus_1 represents the empty prefix (virtual index -1) before any kept message.
    dp_minus_1 = [0] * (budget + 1)
    dp = []
    last_pinned = -1

    # Two-stack max-queue maintaining elementwise maxima of dp[j] for non-adjacent
    # valid predecessors j in [max(last_pinned, i - 1 - max_gap) .. i - 2].
    front = []
    back = []

    length_0, value_0, pinned_0 = messages[0]
    if length_0 > budget:
        dp.append([neg_inf] * (budget + 1))
    else:
        dp.append([neg_inf] * length_0 + [int(value_0)] * (budget + 1 - length_0))
    if pinned_0:
        last_pinned = 0

    for i in range(1, n):
        # Push j = i - 2 into the sliding window of non-adjacent predecessors.
        j_push = i - 2
        vec_push = dp_minus_1 if i == 1 else dp[j_push]
        if not back:
            back.append((j_push, vec_push, vec_push))
        else:
            prev_max = back[-1][2]
            back.append((
                j_push,
                vec_push,
                [a if a > b else b for a, b in zip(vec_push, prev_max)],
            ))

        # Evict predecessors j < low (either too far back or before a pinned message).
        low = last_pinned if last_pinned > i - 1 - max_gap else i - 1 - max_gap
        if front or back:
            newest_idx = back[-1][0] if back else front[0][0]
            if newest_idx < low:
                front.clear()
                back.clear()
            else:
                while (front and front[-1][0] < low) or (
                    not front and back and back[0][0] < low
                ):
                    if not front:
                        while back:
                            idx_b, vec_b, _ = back.pop()
                            if not front:
                                front.append((idx_b, vec_b, vec_b))
                            else:
                                f_max = front[-1][2]
                                front.append((
                                    idx_b,
                                    vec_b,
                                    [a if a > b else b for a, b in zip(vec_b, f_max)],
                                ))
                    front.pop()

        length_i, value_i, pinned_i = messages[i]
        if length_i > budget:
            cur = [neg_inf] * (budget + 1)
        else:
            limit = budget + 1 - length_i
            adj_vec = dp[i - 1]
            gain_adj = value_i + bonus

            if not front and not back:
                cur = [neg_inf] * length_i + [
                    a + gain_adj if a != neg_inf else neg_inf
                    for a in adj_vec[:limit]
                ]
            else:
                if not front:
                    non_adj_vec = back[-1][2]
                elif not back:
                    non_adj_vec = front[-1][2]
                else:
                    non_adj_vec = [
                        a if a > b else b for a, b in zip(front[-1][2], back[-1][2])
                    ]

                cur = [neg_inf] * length_i + [
                    c1
                    if (c1 := (a + gain_adj if a != neg_inf else neg_inf))
                    > (c2 := (na + value_i if na != neg_inf else neg_inf))
                    else c2
                    for a, na in zip(adj_vec[:limit], non_adj_vec[:limit])
                ]

        dp.append(cur)
        if pinned_i:
            last_pinned = i

    # Valid last kept message index j must leave no pinned message and <= max_gap drops at the end.
    final_low = last_pinned if last_pinned > n - 1 - max_gap else n - 1 - max_gap
    if final_low == -1:
        ans = 0
        start_j = 0
    else:
        ans = neg_inf
        start_j = final_low

    for j in range(start_j, n):
        if dp[j][budget] > ans:
            ans = dp[j][budget]

    return None if ans == neg_inf else int(ans)

def min_pruning_cost(
    parent, demand, cap, cut_cost, critical, root_cap, penalty
):
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # Iterative BFS/DFS order from root 0 so children are processed before parents.
    order = [0]
    for u in order:
        order.extend(children[u])

    sub_demand = list(demand)
    has_crit = list(critical)
    for u in reversed(order):
        p = parent[u]
        if p != -1:
            sub_demand[p] += sub_demand[u]
            if has_crit[u]:
                has_crit[p] = True

    INF = 10**18
    # dp[u][w] = min cost inside u's subtree when u is retained and LOAD(u) == w.
    dp = [[] for _ in range(n)]

    for u in reversed(order):
        limit_u = root_cap if u == 0 else cap[u]
        if demand[u] > limit_u:
            continue

        cur = [INF] * demand[u] + [0]

        for c in children[u]:
            dp_c = dp[c]
            # Build effective transition array for child c:
            # load 0 can come from cutting line c (if c's subtree has no critical node)
            # or retaining c with load 0; loads > 0 come from retaining c.
            if dp_c:
                trans = list(dp_c)
            elif not has_crit[c]:
                trans = [INF]
            else:
                cur = []
                break

            if not has_crit[c]:
                cut_c = cut_cost[c] + penalty * sub_demand[c]
                if cut_c < trans[0]:
                    trans[0] = cut_c

            len_cur = len(cur)
            len_trans = len(trans)
            new_max = min(limit_u, (len_cur - 1) + (len_trans - 1))
            nxt = [INF] * (new_max + 1)
            any_valid = False

            for w1, cost1 in enumerate(cur):
                if cost1 == INF:
                    continue
                max_w2 = min(len_trans - 1, new_max - w1)
                for w2 in range(max_w2 + 1):
                    cost2 = trans[w2]
                    if cost2 != INF:
                        total = cost1 + cost2
                        if total < nxt[w1 + w2]:
                            nxt[w1 + w2] = total
                            any_valid = True

            if not any_valid:
                cur = []
                break
            cur = nxt

        dp[u] = cur

    if not dp[0]:
        return None
    ans = min(dp[0])
    return None if ans >= INF else ans

from dataclasses import dataclass
import re

_NAME_RE = re.compile(r"[a-z0-9_]+", re.ASCII)
_ACTION_WORD_RE = re.compile(r"[a-z]+", re.ASCII)
_RULE_ACTION_RE = re.compile(r"\*|[a-z]+(?:,[a-z]+)*", re.ASCII)
_SEG_LITERAL_RE = re.compile(r"[a-z0-9._-]+", re.ASCII)


@dataclass(slots=True)
class _CompiledRule:
  sort_key: tuple[int, int, int, int, int]
  p_kind: str  # "*", "user", "group"
  p_val: str | None
  actions: frozenset[str] | None
  exact_path: str | None
  has_dstar: bool
  min_len: int
  pat: tuple[str, ...]
  head_lit: str | None
  tail_lit: str | None
  decision: str
  rank: int = 0


def _match_dstar(pat: tuple[str, ...], seq: tuple[str, ...]) -> bool:
  m = len(pat)
  n = len(seq)
  pi = 0
  si = 0
  star_pi = -1
  star_si = 0
  while si < n:
    if pi < m and (pat[pi] == "*" or pat[pi] == seq[si]):
      pi += 1
      si += 1
    elif pi < m and pat[pi] == "**":
      star_pi = pi
      star_si = si
      pi += 1
    elif star_pi != -1:
      pi = star_pi + 1
      star_si += 1
      si = star_si
    else:
      return False
  while pi < m and pat[pi] == "**":
    pi += 1
  return pi == m


def _matches_rule(
    rule: _CompiledRule,
    action: str,
    path: str,
    path_segs: tuple[str, ...],
) -> bool:
  if rule.actions is not None and action not in rule.actions:
    return False
  if rule.exact_path is not None:
    return path == rule.exact_path
  if not rule.has_dstar:
    if len(path_segs) != rule.min_len:
      return False
    return all(p == "*" or p == s for p, s in zip(rule.pat, path_segs))
  if len(path_segs) < rule.min_len:
    return False
  if rule.head_lit is not None and path_segs[0] != rule.head_lit:
    return False
  if rule.tail_lit is not None and path_segs[-1] != rule.tail_lit:
    return False
  return _match_dstar(rule.pat, path_segs)


def evaluate_access(rules, requests) -> list[str]:
  if not isinstance(rules, list):
    raise TypeError("rules must be a list")
  if not isinstance(requests, list):
    raise TypeError("requests must be a list")

  compiled_rules: list[_CompiledRule] = []
  for i, rule in enumerate(rules):
    if not isinstance(rule, str):
      raise TypeError(f"rule {i}: not a str")
    fields = rule.split()
    if len(fields) != 4:
      raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")
    effect, principal, action, resource = fields

    if effect not in ("ALLOW", "DENY"):
      raise ValueError(f"rule {i}: bad effect {effect!r}")

    if principal == "*":
      p_spec, p_kind, p_val = 0, "*", None
    elif principal.startswith("user:") and _NAME_RE.fullmatch(principal[5:]):
      p_spec, p_kind, p_val = 2, "user", principal[5:]
    elif principal.startswith("group:") and _NAME_RE.fullmatch(principal[6:]):
      p_spec, p_kind, p_val = 1, "group", principal[6:]
    else:
      raise ValueError(f"rule {i}: bad principal {principal!r}")

    if not _RULE_ACTION_RE.fullmatch(action):
      raise ValueError(f"rule {i}: bad action {action!r}")
    if action == "*":
      a_spec, actions = 0, None
    else:
      a_spec, actions = 1, frozenset(action.split(","))

    if resource == "/":
      raw_segs: list[str] = []
    elif resource.startswith("/"):
      raw_segs = resource[1:].split("/")
      if not all(
          s == "*" or s == "**" or _SEG_LITERAL_RE.fullmatch(s)
          for s in raw_segs
      ):
        raise ValueError(f"rule {i}: bad resource {resource!r}")
    else:
      raise ValueError(f"rule {i}: bad resource {resource!r}")

    lit_count = sum(1 for s in raw_segs if s != "*" and s != "**")
    has_star = "*" in raw_segs
    has_dstar = "**" in raw_segs

    if not has_star and not has_dstar:
      exact_path: str | None = resource
      pat: tuple[str, ...] = ()
      min_len = len(raw_segs)
      head_lit = None
      tail_lit = None
    else:
      exact_path = None
      collapsed: list[str] = []
      for s in raw_segs:
        if s == "**" and collapsed and collapsed[-1] == "**":
          continue
        collapsed.append(s)
      pat = tuple(collapsed)
      min_len = sum(1 for s in pat if s != "**")
      head_lit = pat[0] if pat[0] not in ("*", "**") else None
      tail_lit = pat[-1] if pat[-1] not in ("*", "**") else None

    is_deny = 1 if effect == "DENY" else 0
    compiled_rules.append(
        _CompiledRule(
            sort_key=(lit_count, p_spec, a_spec, is_deny, -i),
            p_kind=p_kind,
            p_val=p_val,
            actions=actions,
            exact_path=exact_path,
            has_dstar=has_dstar,
            min_len=min_len,
            pat=pat,
            head_lit=head_lit,
            tail_lit=tail_lit,
            decision=f"{effect} by rule {i}",
        )
    )

  parsed_requests: list[tuple[str, list[str], str, str, tuple[str, ...]]] = []
  for j, req in enumerate(requests):
    if not isinstance(req, tuple) or len(req) != 4:
      raise TypeError(f"request {j}: expected 4-tuple")
    user, groups, action, path = req

    if not isinstance(user, str) or not _NAME_RE.fullmatch(user):
      raise ValueError(f"request {j}: bad user {user!r}")
    if not isinstance(groups, list) or not all(
        isinstance(g, str) and _NAME_RE.fullmatch(g) for g in groups
    ):
      raise ValueError(f"request {j}: bad groups")
    if not isinstance(action, str) or not _ACTION_WORD_RE.fullmatch(action):
      raise ValueError(f"request {j}: bad action {action!r}")
    if not isinstance(path, str):
      raise ValueError(f"request {j}: bad path {path!r}")
    if path == "/":
      path_segs: tuple[str, ...] = ()
    elif path.startswith("/"):
      segs = tuple(path[1:].split("/"))
      if not all(_SEG_LITERAL_RE.fullmatch(s) for s in segs):
        raise ValueError(f"request {j}: bad path {path!r}")
      path_segs = segs
    else:
      raise ValueError(f"request {j}: bad path {path!r}")

    parsed_requests.append((user, groups, action, path, path_segs))

  compiled_rules.sort(key=lambda r: r.sort_key, reverse=True)
  wildcard_rules: list[_CompiledRule] = []
  user_rules: dict[str, list[_CompiledRule]] = {}
  group_rules: dict[str, list[_CompiledRule]] = {}

  for rank, r in enumerate(compiled_rules):
    r.rank = rank
    if r.p_kind == "*":
      wildcard_rules.append(r)
    elif r.p_kind == "user":
      assert r.p_val is not None
      user_rules.setdefault(r.p_val, []).append(r)
    else:
      assert r.p_val is not None
      group_rules.setdefault(r.p_val, []).append(r)

  sentinel = len(compiled_rules)
  decisions: list[str] = []

  for user, groups, action, path, path_segs in parsed_requests:
    best_rank = sentinel

    u_bucket = user_rules.get(user)
    if u_bucket:
      for r in u_bucket:
        if r.rank >= best_rank:
          break
        if _matches_rule(r, action, path, path_segs):
          best_rank = r.rank
          break

    if groups and group_rules:
      seen: set[str] | None = set() if len(groups) > 1 else None
      for g in groups:
        if seen is not None:
          if g in seen:
            continue
          seen.add(g)
        g_bucket = group_rules.get(g)
        if g_bucket:
          for r in g_bucket:
            if r.rank >= best_rank:
              break
            if _matches_rule(r, action, path, path_segs):
              best_rank = r.rank
              break

    for r in wildcard_rules:
      if r.rank >= best_rank:
        break
      if _matches_rule(r, action, path, path_segs):
        best_rank = r.rank
        break

    if best_rank == sentinel:
      decisions.append("DENY by default")
    else:
      decisions.append(compiled_rules[best_rank].decision)

  return decisions

import datetime
import re

_OPENING_RE = re.compile(r"-?(0|[1-9][0-9]{0,8})\.[0-9]{2}")
_DATE_RE = re.compile(r"(19[0-9]{2}|2[0-9]{3})-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?")
_VALID_KINDS = ("credit", "debit", "fee")
_OD_FEE_CENTS = 2500


def _parse_cents(amount: str) -> int:
    neg = amount.startswith("-")
    if neg:
        amount = amount[1:]
    if "." in amount:
        whole, frac = amount.split(".")
        cents = int(whole) * 100 + int(frac.ljust(2, "0"))
    else:
        cents = int(amount) * 100
    return -cents if neg else cents


def _format_money(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    dollars, rem = divmod(abs(cents), 100)
    return f"{sign}{dollars:,}.{rem:02d}"


def _format_memo(memo: str) -> str:
    norm = " ".join(memo.split())
    if len(norm) > 20:
        norm = norm[:19] + "~"
    return norm.ljust(20)


def render_statement(opening, entries) -> list[str]:
    if not isinstance(opening, str):
        raise TypeError("opening must be a str")
    if _OPENING_RE.fullmatch(opening) is None:
        raise ValueError("opening: bad amount " + repr(opening))
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")

    parsed_entries: list[tuple[str, str, int, str]] = []
    prev_date: str | None = None

    for i, entry in enumerate(entries):
        if not isinstance(entry, tuple) or len(entry) != 4:
            raise TypeError(f"entry {i}: expected 4-tuple")

        date, kind, amount, memo = entry

        if not isinstance(date, str) or _DATE_RE.fullmatch(date) is None:
            raise ValueError(f"entry {i}: bad date {date!r}")
        year, month, day = int(date[0:4]), int(date[5:7]), int(date[8:10])
        try:
            datetime.date(year, month, day)
        except ValueError:
            raise ValueError(f"entry {i}: bad date {date!r}") from None

        if prev_date is not None and date < prev_date:
            raise ValueError(f"entry {i}: date out of order")
        prev_date = date

        if not isinstance(kind, str) or kind not in _VALID_KINDS:
            raise ValueError(f"entry {i}: bad kind {kind!r}")

        if not isinstance(amount, str) or _AMOUNT_RE.fullmatch(amount) is None:
            raise ValueError(f"entry {i}: bad amount {amount!r}")
        cents = _parse_cents(amount)
        if cents == 0:
            raise ValueError(f"entry {i}: bad amount {amount!r}")

        if (
            not isinstance(memo, str)
            or not memo.split()
            or any(ord(ch) < 32 or ord(ch) == 127 for ch in memo)
        ):
            raise ValueError(f"entry {i}: bad memo")

        parsed_entries.append((date, kind, cents, memo))

    balance = _parse_cents(opening)
    lines = [f"Opening balance: {_format_money(balance)}"]
    od_fee_dates: set[str] = set()
    counts = {"credit": 0, "debit": 0, "fee": 0}

    def apply_and_render(date: str, kind: str, cents: int, memo: str) -> None:
        nonlocal balance
        if kind == "credit":
            balance += cents
            sign = "+"
        else:
            balance -= cents
            sign = "-"
        counts[kind] += 1

        memo_col = _format_memo(memo)
        amt_col = f"{sign}{_format_money(cents)}".rjust(14)
        bal_col = _format_money(balance).rjust(15)
        flag = " OD" if balance < 0 else ""
        lines.append(f"{date}  {memo_col}  {amt_col}  {bal_col}{flag}")

    for date, kind, cents, memo in parsed_entries:
        apply_and_render(date, kind, cents, memo)
        if kind == "debit" and balance < 0 and date not in od_fee_dates:
            od_fee_dates.add(date)
            apply_and_render(date, "fee", _OD_FEE_CENTS, "OVERDRAFT FEE")

    lines.append(f"Closing balance: {_format_money(balance)}")
    lines.append(
        f"Credits: {counts['credit']}  Debits: {counts['debit']}  Fees: {counts['fee']}"
    )
    return lines

import re

_PART = r"(?:0|[1-9][0-9]*)"
_RC = r"[1-9][0-9]*"

_VERSION_RE = re.compile(rf"({_PART})\.({_PART})\.({_PART})(?:~rc({_RC}))?")
_MAJOR_WILDCARD_RE = re.compile(rf"({_PART})\.\*")
_MINOR_WILDCARD_RE = re.compile(rf"({_PART})\.({_PART})\.\*")
_AT_RE = re.compile(rf"@({_PART})\.({_PART})")

_OPS = ("!=", ">=", "<=", "=", ">", "<")

VersionKey = tuple[int, int, int, int, int]


def _parse_version(text: str) -> VersionKey | None:
    m = _VERSION_RE.fullmatch(text)
    if m is None:
        return None
    major, minor, patch, rc = m.groups()
    if rc is None:
        return (int(major), int(minor), int(patch), 1, 0)
    return (int(major), int(minor), int(patch), 0, int(rc))


def _parse_clause(clause: str):
    if clause == "*":
        return lambda v: True

    m = _MAJOR_WILDCARD_RE.fullmatch(clause)
    if m is not None:
        x = int(m.group(1))
        return lambda v: v[0] == x

    m = _MINOR_WILDCARD_RE.fullmatch(clause)
    if m is not None:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda v: v[0] == x and v[1] == y

    m = _AT_RE.fullmatch(clause)
    if m is not None:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda v: v[0] == x and v[1] >= y

    op = "="
    ver_str = clause
    for prefix in _OPS:
        if clause.startswith(prefix):
            op = prefix
            ver_str = clause[len(prefix):]
            break

    target = _parse_version(ver_str)
    if target is None:
        return None

    if op == "=":
        return lambda v: v == target
    if op == "!=":
        return lambda v: v != target
    if op == ">":
        return lambda v: v > target
    if op == ">=":
        return lambda v: v >= target
    if op == "<":
        return lambda v: v < target
    return lambda v: v <= target


def pick_version(available, constraint) -> str | None:
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    parsed_available: list[tuple[VersionKey, str]] = []
    for i, element in enumerate(available):
        if not isinstance(element, str):
            raise ValueError(f"invalid version at index {i}: {element!r}")
        key = _parse_version(element)
        if key is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed_available.append((key, element))

    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")

    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    alternatives = []
    for a, raw_alt in enumerate(constraint.split("|"), start=1):
        alt = raw_alt.strip(" ")
        allow_rc = False
        if alt.startswith("?"):
            allow_rc = True
            alt = alt[1:].strip(" ")

        if alt == "":
            raise ValueError(f"alternative {a} is empty")

        predicates = []
        for c, raw_clause in enumerate(alt.split(","), start=1):
            clause = raw_clause.strip(" ")
            pred = _parse_clause(clause)
            if pred is None:
                raise ValueError(
                    f"alternative {a}, clause {c}: invalid clause {clause!r}"
                )
            predicates.append(pred)

        alternatives.append((allow_rc, predicates))

    best_key: VersionKey | None = None
    best_str: str | None = None

    for key, ver_str in parsed_available:
        is_rc = key[3] == 0
        if any(
            (not is_rc or allow_rc) and all(pred(key) for pred in predicates)
            for allow_rc, predicates in alternatives
        ):
            if best_key is None or key > best_key:
                best_key = key
                best_str = ver_str

    return best_str

def decimal_to_half_bits(s: str) -> int:
    """Convert an exact ASCII decimal literal to its nearest IEEE 754 binary16 bit pattern."""
    if not isinstance(s, str) or not s or not s.isascii():
        raise ValueError("Invalid decimal literal")

    n = len(s)
    idx = 0
    if s[0] in "+-":
        sign_bit = 0x8000 if s[0] == "-" else 0
        idx = 1
        if idx == n:
            raise ValueError("Invalid decimal literal")
    else:
        sign_bit = 0

    # Locate optional exponent part ('e' or 'E').
    e_pos = s.find("e", idx)
    if e_pos == -1:
        e_pos = s.find("E", idx)

    if e_pos != -1:
        mant_end = e_pos
        exp_idx = e_pos + 1
        if exp_idx < n and s[exp_idx] in "+-":
            exp_neg = s[exp_idx] == "-"
            exp_idx += 1
        else:
            exp_neg = False
        exp_digits = s[exp_idx:]
        if not exp_digits.isdigit():
            raise ValueError("Invalid decimal literal")
    else:
        mant_end = n
        exp_neg = False
        exp_digits = ""

    if idx == mant_end:
        raise ValueError("Invalid decimal literal")

    # Validate and split mantissa around optional decimal point.
    dot_pos = s.find(".", idx, mant_end)
    if dot_pos == -1:
        int_part = s[idx:mant_end]
        frac_part = ""
        if not int_part.isdigit():
            raise ValueError("Invalid decimal literal")
    else:
        int_part = s[idx:dot_pos]
        frac_part = s[dot_pos + 1 : mant_end]
        if not int_part and not frac_part:
            raise ValueError("Invalid decimal literal")
        if (int_part and not int_part.isdigit()) or (
            frac_part and not frac_part.isdigit()
        ):
            raise ValueError("Invalid decimal literal")

    # Normalize mantissa to scientific form: d0.d1d2... * 10**sci_exp_base.
    int_nz = int_part.lstrip("0")
    if int_nz:
        sci_exp_base = len(int_nz) - 1
        sig_digits = int_nz + frac_part
    else:
        frac_nz = frac_part.lstrip("0")
        if not frac_nz:
            return sign_bit
        sci_exp_base = -(len(frac_part) - len(frac_nz) + 1)
        sig_digits = frac_nz

    # Parse exponent safely without converting arbitrarily long digit strings.
    if exp_digits:
        exp_nz = exp_digits.lstrip("0")
        if not exp_nz:
            exp_val = 0
        elif len(exp_nz) > 10:
            exp_val = -10_000_000_000 if exp_neg else 10_000_000_000
        else:
            exp_val = -int(exp_nz) if exp_neg else int(exp_nz)
    else:
        exp_val = 0

    sci_exp = sci_exp_base + exp_val

    # Fast overflow / underflow checks:
    # sci_exp >= 5  => v >= 100000 > 65520 (infinity)
    # sci_exp <= -9 => v < 1e-8 < 2**-25 (zero)
    if sci_exp >= 5:
        return sign_bit | 0x7C00
    if sci_exp <= -9:
        return sign_bit

    # Every binary16 value and midpoint is an integer multiple of 2**-25, whose
    # exact decimal expansion terminates at or above 10**-25. With sci_exp <= 4,
    # keeping 60 significant digits reaches <= 10**-55, so appending a sticky '1'
    # for any non-zero tail preserves exact comparisons against all midpoints.
    if len(sig_digits) > 60:
        head = sig_digits[:60]
        if sig_digits[60:].lstrip("0"):
            sig_str = head + "1"
        else:
            sig_str = head.rstrip("0")
    else:
        sig_str = sig_digits.rstrip("0")

    dec_mant = int(sig_str)
    dec_exp = sci_exp - (len(sig_str) - 1)

    if dec_exp >= 0:
        num_v = dec_mant * (10**dec_exp)
        den_v = 1
    else:
        num_v = dec_mant
        den_v = 10 ** (-dec_exp)

    if num_v >= 65520 * den_v:
        return sign_bit | 0x7C00

    # Determine binary exponent e = max(-14, floor(log2(num_v / den_v))).
    if (num_v << 14) < den_v:
        e = -14
    else:
        e = num_v.bit_length() - den_v.bit_length()
        if e >= 0:
            if num_v < (den_v << e):
                e -= 1
        else:
            if (num_v << (-e)) < den_v:
                e -= 1

    # Scale by 2**(10 - e) and round to nearest integer, ties to even.
    shift = 10 - e
    if shift >= 0:
        scaled_num = num_v << shift
        scaled_den = den_v
    else:
        scaled_num = num_v
        scaled_den = den_v << (-shift)

    q, r = divmod(scaled_num, scaled_den)
    two_r = r << 1
    if two_r > scaled_den or (two_r == scaled_den and (q & 1)):
        q += 1

    return sign_bit | (((e + 14) << 10) + q)

import heapq


def window_medians(readings, k):
    if isinstance(k, bool) or not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    heappush = heapq.heappush
    heappop = heapq.heappop

    low = []    # max-heap via negation: smaller half, -low[0] is the lower median
    high = []   # min-heap: larger half
    delayed_low = {}   # value -> pending lazy deletions in low
    delayed_high = {}  # value -> pending lazy deletions in high
    low_size = 0
    high_size = 0
    out = []

    def prune_low():
        while low and -low[0] in delayed_low:
            v = -heappop(low)
            cnt = delayed_low[v] - 1
            if cnt:
                delayed_low[v] = cnt
            else:
                del delayed_low[v]

    def prune_high():
        while high and high[0] in delayed_high:
            v = heappop(high)
            cnt = delayed_high[v] - 1
            if cnt:
                delayed_high[v] = cnt
            else:
                del delayed_high[v]

    def rebalance():
        nonlocal low_size, high_size
        # Maintain: low_size == high_size or low_size == high_size + 1,
        # with both heap tops guaranteed live whenever their live size > 0.
        if low_size > high_size + 1:
            heappush(high, -heappop(low))
            low_size -= 1
            high_size += 1
            prune_low()
        elif low_size < high_size:
            heappush(low, -heappop(high))
            high_size -= 1
            low_size += 1
            prune_high()

    def add(x):
        nonlocal low_size, high_size
        if not low or x <= -low[0]:
            heappush(low, -x)
            low_size += 1
        else:
            heappush(high, x)
            high_size += 1
        rebalance()

    def remove(x):
        nonlocal low_size, high_size
        if x <= -low[0]:
            low_size -= 1
            if x == -low[0]:
                heappop(low)
                prune_low()
            else:
                delayed_low[x] = delayed_low.get(x, 0) + 1
        else:
            high_size -= 1
            if x == high[0]:
                heappop(high)
                prune_high()
            else:
                delayed_high[x] = delayed_high.get(x, 0) + 1
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        if i >= k and readings[i - k] is not None:
            remove(readings[i - k])
        out.append(-low[0] if low_size else None)

    return out
